/* 平成25年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h25.committeeSessions.push(...[{"id":"h25-20130925-9","meetingId":"h25-cm09","date":"2013年9月25日","dateIso":"2013-09-25","committee":"文教委員会","time":"午前１０時００分～午後 ２時４４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件整理しています。","topics":[{"id":"topic-01","title":"のいじめ根絶宣言","agenda":"のいじめ根絶宣言","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"役割とか、いろいろと責任の所在とか、子ども同士のやっぱり何かちょっとしたトラブルの背景というのを見過ごさないでほしいと求めました。その点だけ、ちょっとお教えほしいと求めました。","respondent":"渋谷指導課長","answer":"委員ご指摘のとおりで、いじめの様態、状況は、大変さまざまです。ご説明いただいた背景については、また面接等を通して丁寧に見取って、未然の防止に努めてまいりたいと決意しておるところです。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"先日、いじめに対する基本方針の策定ですとか条例化に対して質問を投げかけさせていただきました。さらにこの場で具体的なこととか、ご答弁があればいただきたいのですけれども。","respondent":"渋谷指導課長","answer":"この法律が施行されます９月２８日の方針策定に間に合わせるために、今、第４回目のまとめが９月２６日に行われると聞いております。国の基本方針を受けて都のほうの基本方針、区のほうでも基本方針に基づいた対応について考えてまいりたいと考えておるところです。","id":"exchange-002"},{"speaker":"本多委員","kind":"意見","question":"最後に１点だけ、インターネットを使ったいじめに関するような出来事への対応ですね。非常に、水面下での嫌がらせみたいなこと、そういったものに対する対策についてお考えを説明を求めました。","respondent":"渋谷指導課長","answer":"まず東京都のほうが多分業者委託をして、サイトの監視をして、各区市町村の教育委員会にお知らせいただいて対応するというような対応をしています。自分が思わぬ不注意から加害者にならないというような指導を、徹底していくということで進めてまいりたいと考えているところです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと改めてそこを確認したいのと、平成２年のときにもいじめ根絶宣言をしてますよね。では、改めて、どこが誰に向けてやっているのかというのは、ちょっと確認したいと思います。","respondent":"渋谷指導課長","answer":"対応については改善をしていきたいと考えているところです。そんな手順で周知徹底を図っていきたいと考えているところです。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"６月から数ヶ月程度で、そういう中での自覚を高められるような、ぜひいい成果がしっかり定着できるようにということをここに望みたいと思います。委員会というんでしょうかね、そこのところを本当にしっかりと取り組んでいただきたいということで思っておりますが、どうか尋ねました。","respondent":"渋谷指導課長","answer":"子ども自身が考え、自分たちで１つ一定方向、決意なりを新たにするということが非常に重要だと考えています。子どもたちがしっかりいじめに取り組めるよう、また、働きかけてまいりたいと思います。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"私も本会議で一般質問させていただき、いろんな学校の、２つの事例というのは品川区内の学校の事例なんですね。つくることを急がないで、その過程を大事にしていただきたいということを、ちょっと改めてお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"の保護者アンケートの結果","agenda":"の保護者アンケートの結果","exchanges":[{"speaker":"塚本委員","kind":"意見","question":"最初に、回答率なんですけど、８１.４％ということなんですが、これがちょっと、こういう学校の生徒、通っている生徒に対してのアンケートということでは、もっと高くてもいいのかなと感じるんですけれども、そこら辺はどのように思ってらっしゃいますかとの意見を述べました。","respondent":"渋谷指導課長","answer":"今回、質問紙、無記名で出しているものですので、保護者会の出欠だとか、そういったものと違って、こういった部分では８割の方が協力してくださったのは、比較的高いほうなのかなと認識しております。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"８割で高いということは、何ていうんですか、厳しい回収の仕方をしないと。出せる人は出してくださいと、そういう回収の仕方、回答の求め方というやり方なんか尋ねました。","respondent":"渋谷指導課長","answer":"保護者向けの通知には、ご協力のほどよろしくお願いいたしますということで、協力を依頼するというふうな形です。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問・要望","question":"やっぱり制度的というか、教育の、学校のあり方とか、そういう教育上の仕組みみたいなところに原因を求めるべきなのか。それだと思えば言えると思うんですけれども、その辺をどのようにお考えでいるか、ちょっとお聞きしたいんですけど。","respondent":"渋谷指導課長","answer":"中学生のさまざまな数値の低さの原因についてですが、今、委員のご指摘のとおり、発達段階に伴う部分ということの影響も多いと考えています。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問・要望","question":"４・３・２の固まりとかということは、今後、やっぱりそこは強く保護者などにも理解を求めていく部分と捉えてよろしいんですよね。","respondent":"渋谷指導課長","answer":"１学期に行われた校長連絡会でも、あるいは保護者会の出席率をぜひ上げるような取り組みを進めてほしいというところで、ご依頼をしています。そういう広報の仕方だったり説明の仕方についても、ぜひ工夫をしてくださるように学校にはお願いしています。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問","question":"ちょっと細かいことをお聞きするんですけども、２ページ目のテレビ視聴とゲームの時間、その点が１つ。こういった数値を見ながら今後も何か考え方とかおありなのか、その２点だけ説明を求めました。","respondent":"渋谷指導課長","answer":"ゲームに入って、今後のアンケートのとり方については、そこの部分も改めて検討させていただきたいと思います。土曜日授業については、こういったアンケートの成果なども踏まえながら、次年度以降の計画へ反映していきたいと考えています。","id":"exchange-011"},{"speaker":"大倉委員","kind":"質問","question":"例えば塾と習い事というのを別々にせず一緒くたになっているというのは、塾は塾で、習い事は習い事と。そこを分けたりとかというのはどう考えてるのかというのと、年に１回なのか、実施回数を教えてもらえればと思います。","respondent":"渋谷指導課長","answer":"それから、このアンケートの実施については、ちょっと年度が定かではないんですが、平成１９年度から年間１回とるという形です。昨年度までは保護者アンケートについては、３分の１の保護者の方を対象にして実施してまいったです。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"では今年から、こうした保護者全体に対するアンケートが始まって、こういった結果が出てきたと。データを得て、新しくそういったデータを学校に落として何かやってきたという成果があったりするのかというのを教えていただきたいのと、そこら辺を。","respondent":"渋谷指導課長","answer":"そんなことも考えて、全保護者を対象にして、今年度から実施したです。教育委員会で順次封あけをして、教育委員会のスキャナーで全部読んで、教育委員会が集計・分析をしたです。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"それをそのままやるということで、ではここの学校のデータとかというのでは、一応管理はされているということですか。やっぱりアンケート内容、フィードバックをして、この点もしっかりやってほしいと求めました。","respondent":"渋谷指導課長","answer":"学校のまとまりとして集計をしていますので、学校ごとにまとまったデータは各学校にフィードバックをしているです。今、委員のほうからもありましたように、このアンケートの集計結果について十分活用するようにさせて、また私どもも使用していきたいと考えています。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"例えば行われているんだったら、どういうふうな、こうしていこうとかという会議はあるのかなと。そういうのがあれば、教えてほしいと求めました。","respondent":"渋谷指導課長、田村教育次長","answer":"この分析結果について、課題について説明をして、各学校に問題を投げかけてきた。そんな手順で進めていこうと考えています。やはりなかなか学校だけの取り組みだと難しい、協力を得ないと解決しない問題も、いっぱいこれで浮き彫りになってきたんですね。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"そこを改めて伺いたいのと、とりわけちょっと興味、学年ごとにそれぞれのアンケートの結果が紹介されているんですよね。３分の１ぐらいで、改めて全保護者がどういうふうに認識しておられるかというのを知りたいので、そのことについて質問したいと思います。","respondent":"渋谷指導課長","answer":"ただ、一部、先ほどご説明したとおり、中学校ではより学力を重視していただきたいというようなご要望を受けとめて、今後の施策は考えていきたいです。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっとそのあたりの見解を教えていただきたいのと、品川区の教育方針について理解を求めるということはもちろん大事なことだとは思うんだけども。それはどんな思いがあってこういう設問をしたのかなというのがちょっとわからなかったので、そこを伺いたいと思います。","respondent":"渋谷指導課長","answer":"子どもの意見等々については、またアンケートをとるかどうかということについては、また改めて検討させていただきたいと思います。やっぱり保護者の教育的な関心度を１つはかる目安としてどうなのかというふうな、そういった意味合いでの設問項目だと考えています。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"そういう作業が私は必要なのではないかなとちょっと思っているのですが、そのあたりの見解について伺いたいと思います。４・３・２制は、４年間はこれだとかということはわかっているつもりなんですけども、そういうことを質問したいと思います。","respondent":"渋谷指導課長","answer":"これはもう学校教育だけの問題ではないという認識を新たにしています。そういったさまざまな取り組みについて、目の前の保護者の方たちの考え方、子どもの実態に応じた確かな教育を今後も続けてまいりたいと考えています。","id":"exchange-018"},{"speaker":"南委員","kind":"意見","question":"４・３・２がどういうふうな発達段階でというところは、ぜひそれについては示してほしいと思いますし、やっぱり議論をしていきたいと思っています。とりわけ大事かなと、このアンケートをとった意味かなとちょっと思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"高橋委員","kind":"意見","question":"そういう数字が、もし８月に出た時点から今までで少し関係がわかるのがあれば。そういうのが、これから分析されると思うんですが、現時点でそういったことが、ほかの選択制とかいろんなことでも、もしあればお願いしますとの意見を述べました。","respondent":"渋谷指導課長","answer":"大変申しわけないんですけども、学校ごとの細かい分析というのは、まだこれからになります。各学校にデータを返したのが先週ですので、それぞれのデータをまだ比較してどうこう、学校間の比較というのはこれからの作業になります。","id":"exchange-020"},{"speaker":"高橋委員","kind":"質問","question":"ただ、そうかといって、塾に行っていれば、塾で１日２時間とかを毎日やっている子もいるかもしれない。ですから、その点について、どのようにお考えかというところを。","respondent":"渋谷指導課長","answer":"ただやっていないという、これも保護者がそういうふうに思っているという数字で、子どものやっぱり実態とはかけ離れているのもあろうかと思います。子どもの学習の質に関して、今後どのように調査していくのかということについては、改めて研究させていただきたいと思っています。","id":"exchange-021"},{"speaker":"高橋委員","kind":"質問","question":"全体として家庭学習をどうするかというのを、そういったところを学校のほうに働きかけていっていただけるとよろしいかなと、これは。それについていかがか尋ねました。","respondent":"渋谷指導課長、田村教育次長","answer":"子どもの学力向上を考えていくときに、子どもの学びを考えるという視点が大変重要だと考えておりますので、そんな点は学校のほうにはしていきたいと考えています。 ５年生ぐらいから、予習やってんのという関与の仕方から、ちょっと変わってきたというのがあるんですね。ただ、研究はしていきたい、そう思っています。","id":"exchange-022"},{"speaker":"高橋委員","kind":"質問","question":"あれですかね、個別の指導がされていければいいのではないかと思っています、というふうなお話です。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"沢田副委員長","kind":"質問","question":"４・３・２ということで、これから施策をいろいろどう考えていくかということを分析されて、保護者もわからない。一番保護者に接してるのは先生たちだと思いますので、その辺の意識というのは、むしろどうなってるのかなということをお伺いしたいんですけれど。","respondent":"渋谷指導課長","answer":"ほぼ６年ごとのサイクルで異動してきてというふうな部分は、ずっと、これは相変わらず課題として残っているところであります。自信を持って保護者に説明できるような態勢を、引き続き、研修等で充実させてまいりたいと思っています。","id":"exchange-024"},{"speaker":"沢田副委員長","kind":"意見","question":"冒頭でそういうことだと思います。実際、子どもたちにどう思ってるか聞くのも大切ですけど、先生たちの意識というものもどうなってるのかなというのを知りたいなと思いましたとの意見を述べました。","respondent":"渋谷指導課長","answer":"品川区、施策がずっと続いていきますが、今、ある意味、さまざまな計画を見直す時期であろうとは思っております。児童・生徒の意識だったりとか、そういったことも総合的に、また今後とるようなことも検討してまいりたいと考えています。","id":"exchange-025"}]},{"id":"topic-03","title":"の御殿山幼稚園の再移転に伴う北品川地区保育・教育施設","agenda":"の御殿山幼稚園の再移転に伴う北品川地区保育・教育施設","exchanges":[{"speaker":"南委員","kind":"質問","question":"オープンが平成２７年７月ということなので、保育園、その年の４月の入園というのは、今の現況のまま募集をして入園するわけですよね。認定こども園北品川第二保育園の４・５歳児の方々と、それから御殿山すこやか園の０～３歳児の方々を、そういう作業になるんか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"初めに、新しい御殿山幼稚園移転後の、保育園と併設しました幼保一体施設の開園は、新施設で７月以降で予定しております。北品川すこやか園の北品川第二保育園、御殿山幼稚園として、平成２７年４月に募集をしてまいります。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"それで、非常に、引っ越しも含めて、時期が７月にオープンということで、園運営も子どもも大変な状況なんだろうなとちょっと思うんですね。できたら４月オープンできるように区のほうから働きかけというのはできなかったのか、そのあたりからちょっと伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ただ、７月にならないと、新しい施設ができてまいりませんので、そこの部分はよく検討してまいります。７月の開始の件ですが、竣工の見込みというのが５月ということで決まっておりますので、それは今できない状況だと私ども認識しております。","id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"もともと御殿山幼稚園は戻るという想定で建設・再開発が進められていたわけですから、言ってもやむを得ないという状況があって言わなかったのか。その点について伺いたいということと、あと新しく２つの保育園ができて、０～５歳までの定員をどういうふうに考えているのか教えていただきたいです。","respondent":"金子子ども未来事業部長、今井制度改革・待機児童対策担当課長","answer":"認定こども園北品川第二保育園の４・５歳児、私どもも今、細かいところを想定しながら検討しているところです。７月になるかと思いますけども、検討しているところですので、またそれが決まり次第ご報告したいと考えています。 定員の話が出ましたけれども、現在そこにありますとおり、北品川で定員５１名、０～３歳児、４・５歳児、幼稚園の部分が６２名、このような定員ですので、イメージ的には同じような規模でと考えております。","id":"exchange-028"},{"speaker":"南委員","kind":"質問","question":"ここは３０人定員と書いてあるんですけれども、４・５歳とも３５人定員になっているんですけれども、その辺で地域。子どもとの関係ではそういう設定をしてきたというところについて、どういうふうに考えておられるのかなというのをちょっと伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"御殿山幼稚園が戻るということを前提で考えておりましたが、御殿山幼稚園は、４歳児が３５名在籍されている。今、開発が進んでおります五反田・大崎をにらんだエリアになっておりますので、こちらのほうの幼稚園の需要もあるものと想定しております。","id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"北品川第二保育園の４・５歳児の部分は、入園が早められないか検討するというお話なんですけれども、スペース的にはあるわけですからね。意見で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"塚本委員","kind":"確認","question":"今の質疑の中で確認したいんですけど、移動時というんですかね、どこか行き場がなくなってしまうような人というのはいないという認識でよろしいか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"１つの区立幼稚園の移転ではございませんで、それぞれ新設の部分があるですので、キャパシティーとしてはあります。今現在の２歳児・３歳児は、２年後には新４歳児・５歳児になられますので、継続として進んでいただくという考え方です。","id":"exchange-031"},{"speaker":"高橋委員","kind":"質問・要望","question":"確認が間違っていたら補正していただきたいんですが、1)のほうは保育所型の認定こども園となって、2)のほうは年齢区分型幼保一体施設という形で開設予定と受け取ってよろしいんか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"現在のところ、今ご説明、資料にもありますとおり、品川学園の隣地のところが、認定こども園の北品川第二保育園、仮称です。2)の北品川の、御殿山小学校の南に今度新しい施設になるのが、こちらは年齢区分型の幼保一体施設の予定です。","id":"exchange-032"},{"speaker":"高橋委員","kind":"質問","question":"早ければ平成２７年から可能なんですが、ここの２つに関しては、平成２７年７月に開設の予定ということでよろしいんか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"平成２７年４月に向けての幼保連携型認定こども園は、まだ、まだ公定価格なども示されていない段階です。区内に５つ、全体のスキームの中で考えることですが、品川区独自の幼保一体施設ということで考えております。","id":"exchange-033"},{"speaker":"高橋委員","kind":"質問","question":"ということは、現在のところという話ですので、変わる可能性もあるということでよろしいか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"現在でも品川区は、国が目指している、幼稚園と保育園、それぞれが一体的となった施設運営に取り組んでおります。さらに、国が今度基準を示すというものがどのような基準になっていくのかを十分踏まえながら検討していくということで。","id":"exchange-034"},{"speaker":"高橋委員","kind":"質問・要望","question":"では、推移を見守りながら、新しい仕組みで開園できる可能性もあるので、まあ子育ての先進区、品川区でありますので、新しい施設の仕組みを進めていける態勢をぜひ、まあ時間的な問題があると思いますが、可能ならばとっていただきたいと、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-04","title":"の平成２４年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"の平成２４年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それからその下の４番のところの3)で、業務の適正執行の3)の、その辺を教えてほしいと求めました。先ほどの説明をお伺いしたんですが、私の勉強不足のところを教えていただきたいんですけど、それをちょっと教えてほしいと求めました。","respondent":"立川保育課長、伊崎子育て支援課長","answer":"そういったことについて、やはり職員等への研修等を実施したり、そういったことについての理解を深めていくというという内容でした。再委託の部分につきましては、清掃等の委託等で再委託を実施していると報告を受けております。 １時間、昼間ですと８００円となっております。ファミリーサポートは安定的な収入を確保するものではございませんので、そういったところから、なかなか提供会員の方を増やしていくのが難しいです。","id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"基本的に理解を、今の質問でわかったと思います。そういう方々を、自分の保育を見直すことも他人の方々の保育のやり方を学んでいくということも大事なので、これは大事かなと思って受けとめています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"今後のこととして、真に入所を必要とする者の受け入れというのと、退所に向けた課題の達成度の精査。もうちょっと詳しくお伺いしたいんですけども、現状の状況と見てどういうことを意味しているのかというところと、ちょっと伺いたいと思います。","respondent":"伊崎子育て支援課長","answer":"都営が当たった場合に、アフターケアをしながらそこで生活をという方針で退所いただいた方が、自立が難しかったということも事例としてはあります。そこを見極めながら、本人の自立力を見極めながら、退所の時期を検討していきたい。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"５００万円以上ということで、前年から１００万円以上の伸びを示しているんですけど、若干の金銭のやりとりがあると思っているんですけどね。そういう意味では、精査するというスキームもあってもいいのではないかと思うんですが、その点についていかがか尋ねました。","respondent":"伊崎子育て支援課長","answer":"きちっとファミリーサポートの趣旨あるいは活動内容等をご説明いたしまして、一応、ご理解いただいた上でご登録をいただきたいと。今もそのような努力をしています。","id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"受けとめていける２０世帯分のキャパはずっとあるので、定員を設けなくても、あえて定員を解消していくというふうなことなんですか。ちょっとよくわからなかったので、もう一回、解消する理由というのを教えていただきたいです。","respondent":"伊崎子育て支援課長","answer":"すみません、説明が言葉足らずで申しわけございません。ただ、先ほど申し上げましたように、誰でも入れればいいという施設ではございませんので、そのあたりの兼ね合いが課題となっているところです。","id":"exchange-040"},{"speaker":"高橋委員","kind":"質問","question":"家庭あんしんセンターのほうで２つお伺いしたいんですが、どのような形があったのか、評価してるのかどうかというような点。例えば、こちらの指定管理者に、区として情報提供で研修しているとか、そういったことがあるのかということをお伺いします。","respondent":"伊崎子育て支援課長","answer":"２３区としましては、移管を進めるという方向で、いろいろと検討を進めております。区の中での虐待対応の組織を検討するに当たって、子育て支援センター、子育て支援課を含めて。","id":"exchange-041"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"この資料の中で幾つか教えていただきたいことがあるんですけど、８ページの利用の手続きで、今までと同じという認識です。今、品川区で言えば、全て右側と同じような形にはならなかったのかというところの考え方をちょっとお伺いしたいんですけど。","respondent":"今井制度改革・待機児童対策担当課長","answer":"８ページ左方の、この私立保育所はいわゆる施設型給付の中ですので、これは認可の保育所という形になります。保育所における保育は市町村が実施することとされていることから、児童福祉法第２４条の、市町村の実施責任による実施ということで。","id":"exchange-042"},{"speaker":"塚本委員","kind":"質問","question":"どういう、何ていうんですか、選択肢としてどういうふうに説明されるのかというか。私はどうしても保育園に入らないと、そういう方々が右側に行くみたいな、そういう考え方ができるものなんですかね。","respondent":"今井制度改革・待機児童対策担当課長","answer":"右側の公立保育所というのは、区が実施主体になりますので、区が事業者ですので、区と契約になりますね。認定こども園も地域型保育も直接契約といいますか、保護者と施設との契約になっておりますので、そこの部分の仕組みは変わらないという形になります。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問","question":"６園希望を出して、そういう事務手続というのは今後も残って、そのまま残ると。入園希望の中に、６園の希望の中に認定こども園も書くことができて、区のあっ旋の中で入所が決められていくということになるんか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ここの施設・事業につきましては区のほうに保育の必要性の認定と利用希望の申し込みをいただくというのは、保護者サイドにとって変わりありません。調整の仕方等につきましては、今後、調整の方法と運用等が、国の定めもありますので、今後また改めて検討してまいります。","id":"exchange-044"},{"speaker":"本多委員","kind":"質問","question":"関連するんですけれども、６ページを見てるんですけれども、新たに設置する場合なんですけれども、例えば品川区の地図を全区的に見た場合、新たに設置する、半径何メートルとか、全くそういう縛りはないと見ていいんか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"区内の保育園の設置の距離的な制限についてはございません。私どもは、その地域または近隣の私立・公立の保育園や幼稚園の設置状況を見ながら開設のご相談に乗っております。","id":"exchange-045"},{"speaker":"本多委員","kind":"質問","question":"まあ、現行についてもこれからも、特にそういった縛りがないということで、地域的に、いい意味で、何ていうんですか、いろんな、整備されてて、同じエリアにたくさん、多様なニーズに応えられるようなことも可能だと思っていいんですかね。","respondent":"今井制度改革・待機児童対策担当課長","answer":"区域を区切って考えるやり方というのもあるかもしれないんですが、１つの区の中でどのような形で公立と私立、今後も考えております。","id":"exchange-046"},{"speaker":"本多委員","kind":"質問・要望","question":"わかりました、ありがとうございました。７ページなんですけれども、法人格を求めていくというところなんですけれども、もう少しこの部分をわかりやすく教えていただければと思うんですけど。","respondent":"今井制度改革・待機児童対策担当課長","answer":"保育需要または教育需要を満たしていこうという制度ですので、なるべく現行のいろいろな施設がスムーズに移行しようというふうな観点から、このような形になっています。","id":"exchange-047"},{"speaker":"本多委員","kind":"質問","question":"すみません。事業主が定員を決めていくものなのか、区が決めていくものなのか、その辺だけ説明を求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"品川区の子ども・子育て支援事業計画をつくる、３００を予定するとか、例えば今年は１００の予定しかなくて。支援事業計画の上で、どの程度の利用定員が必要かどうかということを明示してまいりますので、給付の対象にするという形になります。","id":"exchange-048"},{"speaker":"南委員","kind":"質問","question":"その際に、保育園、どこの保育園になるかということも区のほうで指定してくるんですかね。その契約、ちょっとそこまで、どういうふうな形になるのか、もう少し詳しく具体的に伺いたいなと思いました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"先ほどご説明したとおり、３つ目のブルーのところに、希望する施設名などを記載と書いてあります。希望する施設名を書いていただきまして、上位の中からだんだん選考していくという形になって、今と変わらない選考の過程を経るものと考えております。","id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、その時点で、ＡさんならＡさんに対して、保育園に入ることを認定しますよ、必要がありますよ、保育園に入ることを認定しますよと。そのあたり、さっき聞いたんだけど、そこを教えていただきたいです。","respondent":"今井制度改革・待機児童対策担当課長","answer":"新制度で変わりますというご説明をするので、なかなか私の最初の説明がよくなかったかもしれないんですが、変わりません。それか、何々区立保育園ですよという形で、希望の順番に沿ってご回答するという形になっております。","id":"exchange-050"},{"speaker":"南委員","kind":"確認","question":"ありがとうございました。今、どうなっているのかというのを確認したかったので、その契約はなくなったと。","respondent":"今井制度改革・待機児童対策担当課長","answer":"いや、その契約という言葉が多分わかりにくいかもしれないですが、これは、私立保育所の場合、保護者と市町村との契約ですから、今は区のほうにお申し込みいただいて、区がここの私立保育園と手を結んでくださいという形であっ旋調整をしますので、今と変わらない仕組みです。","id":"exchange-051"},{"speaker":"南委員","kind":"確認","question":"私が確認したかったのは、保護者と保育園との関係で契約という作業が入ってくるのかどうかということを聞いたんです。一時期、契約を結ぶというシステムになるという時期があったので、今でもそれは残ってるのかなと思って確認したかったんです。","respondent":"今井制度改革・待機児童対策担当課長","answer":"その場合、保護者と区市町村との契約になります。施設ではございません。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"そうなると非常に保護者にとって、一定のデメリットも出る可能性があるのではないかなということをちょっと心配したので、その辺を確認しました。そういう角度から、バランスある施設配置というのがどういうことなのかを知りたかったので、もう少し詳しく教えてほしいと求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"９ページの上ですが、保育を必要とする子どもに対し、必要な保育を確保するための措置を講じなければならない。こちらの児童福祉法に基づきまして、区としましても、待機児童対策、保育施策を総合的に進めてまいります。","id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"ここについては、それはそれとして今の説明を伺ったんですけども、やっぱり強く求めておきたいと思います。では何が問題だから認定こども園のほうに、国の方針を受けてやっていくんだと考えているのか、そのあたりも含めて伺っておきたいなと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"品川区の保育園、そして家庭的保育事業につきましては、保育所、保育指針にのっとり、またはそれに対応した形で進めてまいりました。国がこの幼保連携型認定こども園の中で示される基準等を踏まえて、今後検討してまいりますし、今も基準を踏まえて検討しています。","id":"exchange-054"},{"speaker":"南委員","kind":"確認","question":"その１つの具体的な事例として懸念しているのは、きのうの質疑でも主張した、園庭の問題等々があると思うんですね。そのことも含めて、やっぱりどういうふうにこれから検討していくのか、その姿勢をもう一度確認しておきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"子どもたちが健康で安全で豊かに育てられるための基準ですので、これを十分踏まえたところを開設していっておりますので、今後もその考え方に変わりはありません。","id":"exchange-055"},{"speaker":"南委員","kind":"質問・要望","question":"どういうふうに捉えているのかというのを、ちょっとこの際、伺っておきたいなと思っています。保育需要に対する施設の整備も含めた量の計画というのを、どういうふうに捉えて、どういうふうに見通そうとしていられるのかを伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"人口、または申込率などを勘案して、適切な開設の量を予算の中でご審議いただきお認めいただいていたところです。支援事業計画の中で、改めてそこの中で考える上では、量のほうを計画の中で策定してまいります。","id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"そういう、上からの指導があるんだろうと思うんですけどね。これも入らないということで６２人という数が出てきている、これについては別に答弁は要らないですから、しっかり受けとめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"高橋委員","kind":"質問","question":"１つだけお尋ねしたいんですけど、調整の面で今と少し違った部分が出てくるのではないでしょうかという疑問があるんですが、その点についてはいかがか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今おっしゃいましたように、短時間の保育利用時間というものも新しく設定する中で、いろんな形の多様な認定をしていくというふうに考えております。９月２０日に行われました、基準検討部会の中で改めて検討されているところですので、また国から一定程度の示しがあると思います。","id":"exchange-058"},{"speaker":"高橋委員","kind":"質問","question":"基準はこれから２０日の認定部会、そうすると、今までとは違った形で多様な認定が出せる可能性はあると。保育所等でもそれを受け入れていく態勢が必要になる可能性があるという言い方で申しわけないですけど、そういう雰囲気でよろしいか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今回、国におきましても、それに加えまして改めて育休明けなどにつきまして、いろいろな考え方を示しているというのが現状です。ですので、これらの方針を踏まえまして、区としましても、認定の基準づくりというものを進めていきたいと考えています。","id":"exchange-059"},{"speaker":"塚本委員","kind":"質問","question":"平成２７年、０・１・２歳児を引き受けるということはあまり期待できない実情だろうかと、品川においてもそうなのではないかと思うんですね。どういう形で、４・５歳児になってくると、どういうふうに進めていく方針なのかをお伺いしたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"保育需要の高止まりが見込まれる中で、東京都は一定、まだ存続すると考えております。地域型給付で今まで認証をやってこられた方が、認可への移行ということも含めて、区としては支援していきたいと考えています。","id":"exchange-060"},{"speaker":"塚本委員","kind":"確認","question":"ちょっと確認なんですけど、３歳児まで受け入れることになっていますけれども、これは今後も変わらないということ。平成２７年の新制度の中でも変わらないのか、その辺はまだ検討の段階で変化があるのかというところを確認したいんですけど。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今の事業の中身をよく確認しながら、小規模保育という国の給付の枠に入れるように支援して、と考えております。家庭的保育事業のほうは０～２歳の枠でやっておりますが、その辺の動向も見ながら、改めて検討していきたいと考えています。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/646567?Template=document&Id=4804#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":71046,"voices":176}},{"id":"h25-20130925-5","meetingId":"h25-cm09","date":"2013年9月25日","dateIso":"2013-09-25","committee":"総務委員会","time":"午前１０時００分～午前１１時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"第５９号議案、平成２５年度品川区一般会計補正予算","agenda":"第５９号議案、平成２５年度品川区一般会計補正予算","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこの確認と、再来年は３分の３ということで、来年も再来年もこういうシステム改修というのはされていくことになるのかということが１点。どういう事業が影響を受けるのかという全体の事業数とか、主な事業とか、そこら辺をお聞かせほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その主なものを教えていただきたいのと、区としては今後どういうふうに取り組むということで、その点についてもお聞かせほしいと求めました。どういう、そこら辺についてわかったら、教えてほしいと求めました。","respondent":"須藤委員長、本城企画財政課長","answer":"いろいろな所管にも入ってきてしまうと思うので、逆にそれらが改修することによってきちんと一括でできるという方向になると思うので、そのあたりをご説明いただければと思います。 今回見込まれているものでいけば、見込まれているものについては、基本的にはおおむね見込んでいる形の経費計上となっているものです。これから改めて、正確なところがわかった段階で、改めてご報告させていただければと思います。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"例えば、それの１.２５倍という基準になっていると思うのですけれども、住民税非課税と課税で大きく違うものというのが本当にたくさん出てくる。そこら辺では、極力影響が出ないようにということで配慮されていくのか、そこら辺についてお聞かせほしいと求めました。","respondent":"本城企画財政課長","answer":"それから、生活保護の受給レベル自体と、今お話がありました就学援助のように、生活保護基準の何倍かという設定をしているものもあります。厚生労働省の通知の趣旨も踏まえて、今後予算編成の中で、来年度に向けて検討していくということになったところです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、今回の生活保護の引き下げであると私は思いますし、もう本当に生活が成り立たないという生存権の問題にもかかわってくると思うのです。改めてお聞かせいただきたいのと、とっていただきたいと思っていますけれども、その点に関してお聞かせほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国からも影響が出ないようにということで出されているわけですから、私は区としてもそういう姿勢で取り組んでいただきたいということで、このことについての姿勢についてちょっとお伺いします。","respondent":"本城企画財政課長","answer":"国のほうは、一般的な通知として来ているところです。現在の事業関係と国からの通知の趣旨と、その全体を踏まえて、これから来年度に向けて検討してまいりたいと考えているところです。","id":"exchange-005"},{"speaker":"いながわ委員","kind":"質問","question":"１７ページで、障害者手帳の交付対象外の子どもたちに補聴器の補助をということで、先ほどご説明いただきました。結構３０万円、４０万円するという話の中で、お願いします。","respondent":"本城企画財政課長","answer":"難聴者に対する支援ですが、現在５人分となっております。９０％分の助成で、１０％が個人負担という形になっています。","id":"exchange-006"},{"speaker":"いながわ委員","kind":"意見","question":"私も詳しいことはあれなのですけれども、実際に今、障害者手帳をお持ちで、補聴器を買う方も大体同じ配分というか、１割負担しかない、助成しかないというのをちらっと聞いた記憶があるのですけれども、その辺ちょっともしお答えできるのであればとの意見を述べました。","respondent":"本城企画財政課長","answer":"申しわけないのですが、今回のものについては、１０分の９の助成ということで、現在手帳を持っていらっしゃる方の助成がどうなっているか、今手元に資料がなくて、申しわけないのですが、今回の助成は、持っていない方に対してそのような形になっております。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ教えてください。もちろん最初から高低差はわかってやっていたはずでしょうから、なぜこれが更正減額なのか、そこら辺をもうちょっと説明していただきたい。","respondent":"本城企画財政課長","answer":"実際に高低差を詳細に検討してみると、擁壁についても対応しなければいけないとか、当初は年度内に基本設計が終わる予定だったものを。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"提案","question":"提案をしていただこうというときに、高低差があって、設計はできませんと言われたのか。何社かいろいろやったら、どういう判断をして、３カ月ぽっとおくらせるということになったのかということを説明を求めました。","respondent":"本城企画財政課長","answer":"さまざまな情報をしんしゃくする中で、行政が判断したという形の中で、今回予算提案をさせていただいているということだと考えております。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だから、これはこれでいいですけれども、そこら辺はぜひお考えいただきたい。それは要望だけにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"その中で公明党などもいろいろ要望とかを出させていただきましたので、その点につきましてはぜひとも進めてほしいと求めました。これを発表した後に、ちょっと順番がどうなのかというのが気になったので、これについてちょっと教えてほしいと求めました。","respondent":"桑村企画部長","answer":"議案説明会等に、各会派の予算説明等をさせていただいて、その後に記者向けに説明させていただきたいです。きちんとした丁寧な説明というのですか、あるいは委員会に説明が必要だと思っていますので、少し丁寧な説明をやらせていただければと思っています。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"ありがとうございました。どうしてもタイミングの問題とか、そのように思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"大森駅の放置自転車とか、区民にとって本当に要望にこたえたものも、そういう要望が取り入れられているということは評価するものです。こういう根本的な生存権保障に関するところでの改悪が入っている予算でもありますので、反対ということで態度表明します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"品川区長期基本計画の中間見直し","agenda":"品川区長期基本計画の中間見直し","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"3)の改訂版素案というのは、今まで４回の委員会の中で、そのことを１つ説明を求めました。","respondent":"黒田長期計画担当課長","answer":"素案としてパブリックコメントを実施するというところまで至っておりますので、そういう形で進めさせていただいて、さまざまな意見を反映していきたいと考えています。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ということは、それが最後の１２月下旬の答申についての議論という仕切りになるのでしょうか。それともう一つ、これについての区民への説明会をぜひ開いていただきたいと改めて要望したいのですけれども、その点はいかがか尋ねました。","respondent":"黒田長期計画担当課長","answer":"今後の進め方ですが、第５回の改訂委員会を１１月１３日に行います。１００ページを超えるような冊子ですので、説明会を開いて説明するというものではないのかなと、説明会を開催する考えは今のところございません。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこの中で質問や意見などにも答えるという、ご検討いただきたいということで、私は強く要望します。一度議題としてこのことについて、ここの場で質問を含めて話し合う場をぜひつくっていただけたらと思うのですけれども、どうか尋ねました。","respondent":"須藤委員長","answer":"そのこと自体、総務委員会で議題にして議論するという考え方は、今のところは持っていません。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"パブリックコメントを受けてというのではなくて、このたたき台について、議会の中でもやりとりができるように、ぜひしていただきたいというところなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"さっき統合型ＧＩＳの説明をいただいた中で、品川区で統合型にはなっていないけれども、ＧＩＳを使っているという、土木管理課と、あと何があるのかというのを、内容を含めてもう一回説明を求めました。","respondent":"桑村企画部長","answer":"つまり、地図情報は同じ共通基盤を使っているのですけれども、各課が連携しない形でつくっています。それから、建築課が指定道路の管理で使っていると、４つのところが使っているというのが区の実情です。","id":"exchange-018"},{"speaker":"浅野委員","kind":"質問","question":"区民の皆さんには、こういうふうにして数多く公開していますけれども、あれは統合型になっているかなとは思うのですけれども、わかりました。区の情報がわかっていないと、質問するにもと思いましたので、ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/904361?Template=document&Id=1962#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":33137,"voices":73}},{"id":"h25-20130926-14","meetingId":"h25-cm09","date":"2013年9月26日","dateIso":"2013-09-26","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ０時２０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"公有地の活用に関すること","agenda":"公有地の活用に関すること","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"需要との関係でどういうふうに見ているのかということをちょっと伺っておきたいと思いますし、今、教えてほしいと求めました。それと同時に、どういうふうになっているのかというところの検討状況、そのあたりももう少し教えてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"今回、ご意見を賜った中でさらに検討を深めて１０月の末が回答期限ですので、それに向けて最終的な調整をしていきたいといったものです。実際動き出せるのは平成２６年度以降になってくるだろうとは考えてありますが、条件、そういったところを詰めながらといったところです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"高齢化率の高い状況になっていくわけですから、定期借地ってなるとこの間の関係では３０年ぐらいのスパンですよね、たしか。しっかりと品川区の施策がつくられる、定期借地との関係ではどういうふうに見ているのか、その辺をちょっと伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"運用をしていったときの年額の負担、区の負担がどのぐらいなのか、そういったところも考えなくてはいけないというところがあります。そういった財政的な負担のところも踏まえながら、どういった選択肢がよろしいのかというのは今後検討を深める部分だろうというふうに思います。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"区民の方々の要望の高いものをやっぱり選択をしていただきたいということと、そういう運営形態をとっていただきたいということ。には、高いかもしれないけれども、そういう選択をぜひしていただけるようにということをちょっと強くお願いして終わらせようと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"浅野委員","kind":"質問・要望","question":"南委員からもいろいろ質問があったと思うんですけれども、保育園ですと、一定の線が出たということですかね。この点を一つちょっと教えていただきたいのと、こういうときにどこまで区のほうから回答をする内容ですか、例えばそういうことなのか。","respondent":"柏原行財政改革担当課長","answer":"建物の部分ですけれども、まだこれはちょっと内部で検討している、どのぐらいのボリュームが建つかというのはうちの内部では検討しているんですが。","id":"exchange-004"},{"speaker":"浅野委員","kind":"意見","question":"３階建てがせいぜいで、４階が一部建つかどうかですけれども、できるだけ有効活用していただければと。どういうふうに進めていくのかも含めてということになりますと、高齢者の施設ですとか、ぜひともとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"グループホームの検討ということでお話を伺って、グループホームということで、グループホームというのが一番いいかなというふうにも思っております。道路の関係で少しセットバックすると考えて、金額的にちょっとわからないので、出してよければ、ある程度数字を教えてもらえればと思います。","respondent":"柏原行財政改革担当課長","answer":"これはあくまで参考値というレベルですけれども、土地の価格といたしましては、２億４,８００万円ほどです。ただし、前回ご覧いただいたとおり、建物の面積については若干そういった制約が出てくるだろうというふうに考えてあります。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"大体、坪二百五、六十万かなというところを見てて、２億４,８００万円。１０月末というと、その辺はどういうふうに我々のほうには通知が出てくるのか、それを教えていただけますか。","respondent":"柏原行財政改革担当課長","answer":"そういった形で今検討を進めているところです。その直近の部分でこういった形になりましたという報告が一義的にはそういう形で出てくるということになろうかと思います。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問・要望","question":"高齢者福祉以外の例えば障害者福祉ですとか、あるいは医療系ですとか、そういったことも検討の俎上には上っていたんでしょうか。いた上で、購入したということなんでしょうか、そこだけ教えていただけますか。","respondent":"柏原行財政改革担当課長","answer":"ただ、いろいろ検討していく中に、高齢者のグループホームというのを第一案としていくのがよろしいんではないかという方向で今まとめたところです。そういった情報も、事業課と連携しながら、検討をさらに深めていくです。","id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問","question":"北側になるんですかね、あと不動産屋の売却の看板等が内部に見えた経緯があったので、その辺の情報をどう把握されていたか。あるいは、もし把握されていたとしたら、検討に上がったのかどうかだけお知らせください。","respondent":"柏原行財政改革担当課長","answer":"その部分につきましては、現在もちょっとどういった状況かという情報を収集しています。細かい状況については、周りの状況もまだ１月ぐらいありますので、よく調査しながら検討していきたいというものです。","id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問・要望","question":"長期的に考えても、やはりチャンスと捉えて、チャンスがあれば前向きな検討をしていただければと思いました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"原委員","kind":"意見","question":"私のほうも、ここは品川の北エリアですので、まず一番初めに聞きたいのは、北エリアというよりは品川区が優先的にと、前回そんなようなお話だったんですけれども、それは変わっていないのかそこをまず聞いておきたいとの意見を述べました。","respondent":"柏原行財政改革担当課長","answer":"優先的というのは、国のほうからの照会がということでよろしかったでしょうか。先に情報提供をしますといったことですので、委員おっしゃるとおり、優先的にまず話です。","id":"exchange-011"},{"speaker":"原委員","kind":"質問・要望","question":"具体的には青葉会ですかね、ですから今先ほどあべ委員からもお話があったように、先端のこともちょっといろいろ検討していただきたい。ですから、買うとなると本当に区からぽんとお金が出る形でしょうから、その辺をちょっとまたご意見いただければ。","respondent":"柏原行財政改革担当課長","answer":"購入、財政の負担の面であるとか、そういったところを踏まえながらどういった形が一番よろしいのかということで考えていきたいと思います。３０年のスキームのほかにも５０年のスキームもあるというふうには聞いておりますので、総合的に判断していくというふうに思っております。","id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、日数的に時間もないんですけれども、もう一回ご検討いただきたいということを要望としてお願いをしておきたいと思います。頑張ってオプションがとれればとっていただきたいと、そういうことです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"井上副委員長","kind":"質問","question":"土地が出てきてどうしましょうというよりも、何がどういうふうにというのは、今どのような状況にあるんか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"４物件、５物件というのはわかったんですけれども、なかなか情報をとりづらいというところがあります。そうはいいましても、区としましても、それは全庁を挙げて情報をなるべく早くとっていくという体制をとっていきたいというふうに思っております。","id":"exchange-014"},{"speaker":"井上副委員長","kind":"質問・要望","question":"建物とか広さによっても制約があるわけですから、出てくるのだということを想定して計画づくりをしていただきたいというふうに思うんですが、そういう方針でなっているのかどうかの確認だけお願いします。","respondent":"柏原行財政改革担当課長","answer":"いろいろな施設がこういったところで必要だというのは我々も含めて所管部門と検討、いろいろ計画として検討している部分ではありますけれども、なるべく早くこちらからも情報をとるような形をとっていきたいというものです。","id":"exchange-015"}]},{"id":"topic-02","title":"契約のあり方に関すること","agenda":"契約のあり方に関すること","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"検討会を開かせていただいた中で、今お配りしています２点について要望、また追記をしていただきたくお願いをします。しかしながら、私ども強く訴えていたものですから、そのような部分。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"南委員","kind":"提案","question":"今の自民党のご提案についてちょっと質問なんですけれども、３項目のほうは理解できるし、いいと思います。これが後から続くということですよねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"渡部委員","kind":"提案","question":"今回、正副のほうでお示しさせていただいている記以降の１番から５番までを見させていただきました。本文等も読んでみまして、新たな項目として追加をさせていただきたい、そのような形で提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"南委員","kind":"提案","question":"自民党の提案については、提案趣旨もよくわかりました。〔「大いに反省してくれよ」と呼ぶ者あり〕口頭でちょっと言いますけれども、いいか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"南委員","kind":"提案","question":"意味がわからなくなってきたなあ」と呼ぶ者あり〕建設的に提案してるんですから、そんなことをおっしゃらないでください。じゃあ、どうしよう、これ、コピーしてきますかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"じゃあちょっと、いいですか。事前にだったでしょう」と呼ぶ者あり〕〔「それ、正副に失礼だよ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"南委員","kind":"提案","question":"１番目のところに、上から３行目、「労働環境の整備などに」というふうにつなげたらどうかと思います。「調査研究」ではなくて、「図ること」に変えたらどうかという、そういう提案ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"あべ委員","kind":"提案","question":"それから次、２番のところで提案されていた、「地域社会貢献など総合的に評価」というのはまさに３番で提案している内容なので。４番のご提案は、言葉の問題ですので内容的に変わるところではないので、私としてはどちらでもいいんじゃないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"確認","question":"一点だけ確認なんですけれども、私も質問させていただいて、ここにはこの地域貢献を導入することに含まれているのかどうか。あえてこれを入れてくださいというわけではないんですけれども、それについて一応お聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"４番に関して、導入をする、まず最低制限価格制度をそのまま採用するかどうかもまだこれからの検討だということだと思いますんで。これからやることなんですけれども、何かもうちょっといい言い方がないのかなということはちょっと今感じております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"南委員","kind":"提案","question":"それぞれうちの提案についてもいろいろご意見いただいてありがとうあります。そういう点では、やっぱりきちんと具体的なことを盛り込むことが、私は提言ですから必要なんじゃないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"須藤委員","kind":"提案","question":"最初に自民党の案、いただいたんだけども、我々も今共産からいろいろご提案されたことを加味してこの２つの文案を整理をしてきたつもりなんで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱり文言を入れていくという、そういうことで、ここをこれはこういうふうな角度で言ってるんだよというふうに受け取っていただきたい。必要なんじゃないかなというふうに思いますので、その辺も配慮、考慮してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"須藤委員","kind":"提案","question":"区内業者、もちろん区内業者を総合的な点数として加味するけども、それだけで本当にいいんだろうかということも我々の中で考えながらやっている。余り片方だけを強調しちゃうと、ぜひ我々の提案というか文章はそういう意味も入っているよということまでご理解をほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"とりわけ１番の労働環境の整備というふうになっているんですけども、一般的にはね。具体的にわかるようにしていただきたいということだけ、ちょっと強調していきたいと思いますので、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"あべ委員","kind":"提案","question":"今回の、地域貢献評価みたいなものの中には準区内業者の扱いというものも入るのだというご確認がもしできるのであれば、もし可能であれば。皆さんのご意見を伺いたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"確認","question":"営業拠点の所在地というところで、大まかな例示がされているので、これは含まれているというふうに私は考えております。そこの判断については、先ほど私も委員長にその意味も込められているんですねということで確認をさせていただいたんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"あべ委員","kind":"質問","question":"今私はちょっと流れがよく読み切れなかったということで、それは既にもう含まれているという理解でよろしいんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"原委員","kind":"確認","question":"自民党に確認なんですけれども、先ほどの５があって、今までの。それで、自民党案なんですが、５にこれを入れて、今までのやつの５を６にするという解釈でよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"原委員","kind":"意見","question":"このバランスはどこかに入れてほしいなという考えでおります。でも、もう最終的には無所属もみんなも今回の件に関しては委員長、副委員長に最終的にはまたご苦労をかけますが、よろしくお願いできればと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"井上副委員長","kind":"確認","question":"５のところでお伺いしたいんですけれども、いろいろ正副でまとめるときに議事録を確認して皆さんから出たというところで取りまとめているんですけれども、そこのところをまず確認させてもらいたいんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"提案","question":"「迅速に行うとともに、開示されるように努められたい」というのは、どういうふうに実施されるかということの質問をした際にお答えいただいている。そこだけでなく、ほかの事業者にもわかるような形をとることを考えるべきではないだろうかということを、この提案の中にとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"井上副委員長","kind":"質問・要望","question":"体制としてということだけでいいということでの確認なのかというのは、このことについてどうかということをお伺いしたいのと、それについては今。ちなみに、行政としては、開示をすることによって区民へのデメリットというのはあるのかどうかというところを経理課長にお伺いしたいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"提案","question":"体制づくりというのは今４人とおっしゃったけど、その体制を考えていかないと、前段の話です。３番の下のほう、いろいろなことが引っかかってくると思うんで、ここら辺も含めての提案ですとの意見を述べました。","respondent":"平澤経理課長","answer":"私のほうから、まず初めに人員体制の件ですが、ちょっと誤解があるといけないのでご説明します。それから過去の状況、そういったことも加味した上での今後の検討課題になろうかなと、今はそういう感じがしております。","id":"exchange-039"},{"speaker":"あべ委員","kind":"提案","question":"今のご説明をちょっと伺っていまして、５番のほう、評価体制づくりというのは別に人員体制のことまで言及しているものではないと感じております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"やはり今までは通知をされていなかったわけですから、自分たちがどのように評価されていたかは正直わからないわけです。ですから、そういうエッセンスはこもっているということはこの委員会の意思として入れていただきたいなとは思っているんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"あべ委員","kind":"意見","question":"そういう順番であると理解しておりますので、どう解釈するかというのは、事実上あまり変わりないかなと思うんですが。突き詰めて考えればそういう順番かなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"鈴木（真）委員","kind":"意見","question":"逆に言うと、評価の段階で特殊事情は勘案していないのかなというふうに聞こえてしまうんですけど、区の今の体制は。ここら辺はどうなっているのかとの意見を述べました。","respondent":"平澤経理課長、中山総務部長","answer":"工事成績評定が継続してずっとやっているような場合は、これまで積み重ねた、きちんとした優秀な評価を多分積み重ねていったんだと思います。… このステージはいいんですが、開示をするとなった場合には、これはもっと社会的な評価につながる。経験、こういうものも必要かと、そういう認識は持っているです。","id":"exchange-043"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それが原因であったら、評価する時点においてそこを考慮してないんですかという、そこの部分をちょっと。確認なんですけど。","respondent":"平澤経理課長","answer":"当然そういったことにつきましては、斟酌する対象となっています。","id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"確認","question":"そこら辺のところを確認したかった。お答えはもういいので。","respondent":"山元委員長","answer":"皆さんのご意見さまざまいただきましたけれども、とりあえずこちらの正副で取りまとめさせていただいてよろしいですか。","id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"だから、待つのは待ちますけども、いいんじゃないですか、とりあえず休憩は１時間とると。だから、できた時点での再開ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そこら辺まとめるのに例えば２０分ぐらい見ていただいて、１２時から再開していただいて、ある程度正副に任せますんですから。でしたら、１２時から始めれば、そんなに極端な、長く伸びないんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"南委員","kind":"提案","question":"お疲れさまでした。私どもの提案はどういうふうに具体的に入ったのか、ちょっとそこは確認をしたいと思いますとの意見を述べました。","respondent":"山元委員長","answer":"皆さんもご承知のように、今回は掲げるというか記入せずに今回のこの案文にさせていただいたということで、お気持ちは十分わかっております。しかしながら、この文章の中には申しわけありませんが、今回は割愛させていただいたです。","id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱり区内事業者の、またいろいろな総合評価についても思いを取り入れて臨んでいただきたいということをちょっと、申したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/631596?Template=document&Id=5954#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":32183,"voices":107}},{"id":"h25-20130927-17","meetingId":"h25-cm09","date":"2013年9月27日","dateIso":"2013-09-27","committee":"震災対策特別委員会","time":"午前１０時００分～午後 ２時４７分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を64件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"二次避難所が１９施設、福祉避難所が１２施設についても、それぞれ避難所運営訓練が実施された避難所が幾つあるのか伺いたいと思います。今わかるようなものがどこにあるのか伺いたいのと、平常時から区民にもわかるような工夫をしてほしいと求めましたけども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"平成２３年度から耐震化の取り組みが始まっておりまして、今年度末現在で３３カ所の工事が完了する予定で今進んでいるというふうに伺っております。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり５３の避難所、また実施できるように区が支援していくということがとても大切だと思いますけどもその点を伺いたいと思います。伺ったところ、１日分もちますよと、状況を伺いたいと思います。","respondent":"鈴木防災課長","answer":"この２人１組の地区担当がそれぞれの避難所連絡会議の出席やさまざまな区の必要な支援のご意見やご要望をお伺いして対応するという体制で支援を行っ…先ほど申し上げましたように。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"いわゆる既存の区有施設、こういうマンホールトイレをつくっていくという計画を立てるべきだと思いますけども、この点も伺いたいと思います。実際はどうなのかというところも含めて、どういう協定内容になっているのか、その中身もあわせて伺いたいと思います。","respondent":"鈴木防災課長","answer":"そこについては先ほど申し上げましたように、区の地区担当や地域センターとの連絡の中でさらに支援を継続していくというのが現在の考え方です。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろんいろいろ追加してほしい点はありながらも、この点、具体的に伺いたい。実際どうなのか、そういう訓練を実施してはどうかと思うのですけども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"三つの手段でそれぞれ対応できるようにという形をとっておりまして、外部からの支援の中にも物資が入ってきますので、不足して困る状況にはないと。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的に外部から協定があるのかないのか伺いたいのと、ちょっと伺いたいのは、本当に全くない状態でいいのかと思うのですよね。そういう備蓄というのはいろんな災害を想定されますので、ぜひ考えていく必要があると私は思いますけども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"このような方法、複数の手段を通じてできるだけスムーズな対応ができるようにということで、その支援をしていくという考え方で進めております。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"トイレが間に合っているというのと、仮設住宅が一、二週間後にはできるというのは、ちょっと違うのではないかという点をご説明いただきたい。","respondent":"鈴木防災課長","answer":"確かに仮設住宅は１週間、そのようないろんな手段を講じて対応するというのが災害時の考え方ですので、その一例ということで申し上げたものです。対応を考えるという点では、３段階の方法で、とりあえず対応はできているというふうに考えているところです。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"最大限に多くの生徒がいらっしゃる場合のことをご質問させていただいて、１点お願いしたいのですけれど、学校側から見た流れというものをちょっとお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"児童・生徒が在校中に災害が発生した場合につきましては、学校の対応としては、児童・生徒等の安全確保を第一に対応するというのが大原則になります。被害の状況を踏まえながら校長の指揮のもと避難所の開設に協力する、それが大原則になっています。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"学校と普通の避難所の違いというのは、生徒がいるかいないかというのが、それは授業があるときですけど、その辺が、ちょっと違いがとてもあると思いますけれど、そこの混乱というものに関してちょっと心配があるので、その辺、学校と地域と一緒に訓練をするようなことはあるのか尋ねました。","respondent":"鈴木防災課長","answer":"全ての学校でまだ実施しているわけではございませんが、児童・生徒の保護者の方の引き取り訓練も含めた災害時の対応の訓練等が既に昨年度あたりから幾つか実施されておりますので、しっかりとそういう対応をしていきたいというふうに考えております。","id":"exchange-008"},{"speaker":"本多委員","kind":"確認","question":"それで、確認は災害協定を結んでいる都立学校、私立学校、社会福祉施設等も大災害が起きて、足りなくなってしまうと想定しますよね。そういったところの連絡調整は大丈夫なのか尋ねました。","respondent":"鈴木防災課長","answer":"それからいろんな連携につきましては、区と協議をした上で対応ということが明記してありまして、有事の際の連絡はとれるようにしています。相談をしているということで、できるだけ本来の区立小・中学校の避難所と同じような対応ができるようにということで連携をしています。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問","question":"別のことを聞きます。以前お聞きしたときに、細かく決められたのかどうか、状況を説明を求めました。","respondent":"鈴木防災課長","answer":"各学校におきます教室の割り振りですが、先ほどご説明の中にあったように、避難所連絡会ごとで割り振り等も決めていただいております。地区に１カ所ですので、教育委員会ともご相談をして、改めてもう一回確認をするという作業をしています。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問","question":"畳１枚で１人ということでわかるのですけども、一般的に何か１人に畳１枚ぐらいですよという、書いたらどうかという意見です。５ページのところですけども、備蓄でおわんについてはどういうふうに考えているのか尋ねました。","respondent":"鈴木防災課長","answer":"おわん、つまり食器の関係のご質問でよろしいですか。","id":"exchange-011"},{"speaker":"本多委員","kind":"質問","question":"品川の場合は４ページにも生活用水井戸４０施設とあるので、サランラップは必要ないと思いますが、これは教訓から活かしてほしいと求めました。いかがか尋ねました。","respondent":"鈴木防災課長","answer":"サランラップというのは確かに一つの方法だと思います。今検討する中で、ご提案のあったラップも含めまして、よりよい方法なり複数の手段を講じるということで今後検討させていただきたいと思います。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問","question":"いわゆる委員が見えている。防災区民組織の方々は町会の方々ですから、その現状ですね、構成員の現状を説明を求めました。","respondent":"鈴木防災課長","answer":"防災区民組織のメンバーの方については各組織の本部長、もしくは防災の部長ですので、比較的あまり交代がなく安定している状態です。対応することが可能でして、同じメンバーで対応しておりますので、しっかりとお話ができる関係を築いているところです。","id":"exchange-013"},{"speaker":"こんの委員","kind":"質問","question":"どうしてもかわる時期というのがあるので、だからこそ申し送りなり、マニュアルの中身が大事だというふうに思うのですね。さまざまだと思いますけど、現状どうか尋ねました。","respondent":"鈴木防災課長","answer":"ただ、現状としましては、大体割合でいけば、平均すると１割程度は女性の方も入っていただいております。区の職員も含めまして、１割といいますと、多分避難所連絡会議にお一人かお二人ぐらいは女性の方が入ってくるケースが多いというところが現状です。","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問・要望","question":"３・１１のときもそうですし、ぜひ構成員の中に女性の方が入っていただきたいということは、一言申し上げていただきたいと思うのですね。そのお考えでいいのですが、こういうことが必要かと思いますけど、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"協定を結んで支援関係にあります宮古市から実際の対応のときの教訓とか課題についての情報、こちらでもそれを精査してまとめたところです。","id":"exchange-015"},{"speaker":"こんの委員","kind":"質問","question":"もう一つの質問ですけども、備蓄倉庫の一つは整備、学校によっては備蓄倉庫の整備というのをどうされているのか。これはいわゆる整備としては、学校がするものなのですか、それともどこが所管としてその整備をするものなのか尋ねました。","respondent":"鈴木防災課長","answer":"区側と学校、区職員と、それから地域の方と協力し合って進めるという形になります。これから調査をかけますので、その中で把握をしながら、支援なりお願いという働きかけも今後していきたいというふうに考えております。","id":"exchange-016"},{"speaker":"こんの委員","kind":"質問","question":"学校も確かにお気持ちはあると思うのですが、学校の先生たちもなかなかそこまでは手が回らないのが現状かというふうに非常に思います。どうかこれは防災課と連携をとりながら、平常時はなかなかそこまでのところは難しいかと私は思いますけれども、どうか尋ねました。","respondent":"鈴木防災課長","answer":"防災課のほうでしっかり調整をして、地域の方の取り組みを促すような働きかけを含めて、しっかりと体制を整備していきたいというふうに考えております。","id":"exchange-017"},{"speaker":"沢田委員","kind":"質問","question":"今のこんの委員の質問とちょっと関連するかもしれないのですけども、日中学校があるときには生徒の避難等、生徒が優先されると。地域の防災避難所連絡会議の構成員との関係というか、そのあたりはどういうふうになっているのか尋ねました。","respondent":"鈴木防災課長","answer":"それから教職員がいない場合についての対応ですが、これにつきましては、つまり防災区民組織の各本部長たちが中心に対応していただくことになります。","id":"exchange-018"},{"speaker":"沢田委員","kind":"質問・要望","question":"もう１点ちょっと別のことですけども、特に飲料水のことでお伺いしたいのですけども、避難所には全て受水槽があるということなのでしょうか。こういう受水槽というものの状況というのはどうなっているのかということをお伺いしたいのと、ペットボトルは、この備蓄はどこにされるのか。","respondent":"齋藤庶務課長、鈴木防災課長","answer":"学校の受水槽は残してあります。水を飲む水道管は直結をしておりますが、トイレだとか雑排水、そして防災用のために受水槽は残してあります。ペットボトルの備蓄の場所ですが、基本的には各学校の防災倉庫にもスペースが許す限りは配備をしております。","id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"受水槽は学校にはあるということでしたけど、ほかの避難所はどうですか。全部受水槽はあるということか尋ねました。","respondent":"鈴木防災課長","answer":"受水槽に遮断弁の方式はとっておりませんが、最初から防災の視点を入れて設計しておりますので、備蓄を含めた対応が可能になっております。ちょっと申しわけありません、申しわけありません、確認がとれておりません。","id":"exchange-020"},{"speaker":"沢田委員","kind":"意見","question":"受水槽に入らなかったから、夜間の工事でも水が出ていたけれども、これからはそうなりますという話をされていた。ほかの施設とか、これは別の話になってしまいますけども、これからそういったことを考えたほうがいいのかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"木村委員","kind":"質問","question":"この９,０００箱、それは配布をするのか、それとも避難所で避難をしてきた人たちのためのものなのかということ、それをお聞きしたいと思います。７年計画でのペットボトルですけれども、水というものは、こういうペットボトルというのはあるのか尋ねました。","respondent":"鈴木防災課長","answer":"この１８０万回分の簡易トイレは、あとは区の備蓄倉庫に備蓄をするということで、各ご家庭とか個人に配るものではございません。１０年間程度備蓄できるものも今出てきておりますので、５年とか１０年のものですね、今入れ替えの中で進めているところです。","id":"exchange-022"},{"speaker":"木村委員","kind":"質問","question":"１４万人、１５万人となった場合、その対応ができるのかどうか。１２万人は確保しているけれども、それ以上の、例えば２万人とか３万人増えた場合、想定外になった場合のことをちょっと教えてほしいのですけれども。","respondent":"鈴木防災課長","answer":"なお、その場合に、想定を超える数が必要になるケースも確かにあります。その場合には、まずは想定する人数が１日以上もつ数がありますので、引き続き対応できるような体制を組むというのが現在の考え方になっております。","id":"exchange-023"},{"speaker":"木村委員","kind":"質問","question":"配付をするということは、わかるのですけれども、聞いたのは、１２万人以上の避難者が出た場合に、想定外の避難者が出た場合に、例えば１２万人は確保しているけれども、それ以上の避難者の方々の対応はできるのかとお聞きしました。","respondent":"鈴木防災課長","answer":"失礼いたしました。１２万人を超える避難者が発生した場合、それを補完する１２万人に対応できる簡易トイレ、マンホールトイレも含めて対応しまして。","id":"exchange-024"},{"speaker":"木村委員","kind":"意見","question":"２万人、３万人増えた場合、想定外のことを今聞いているわけです。お願いしますとの意見を述べました。","respondent":"鈴木防災課長","answer":"それ以外の区の施設で使えるところ、全て人材とそれから資機材、備蓄物資を導入することで避難所の対応ができるようには考えております。それを超える場合には、補完避難所や他の施設で対応するというのが現在の計画になっております。","id":"exchange-025"},{"speaker":"つる委員","kind":"質問・要望","question":"それはちょっと要望ですけれど、おむつの処理をするときに、お尻拭きというのはすごく大事だと思うのですね。先ほど衛生用品の見直しとおっしゃっていたので、そうした中に加味していただけるかどうか、その辺、説明を求めました。","respondent":"鈴木防災課長","answer":"もしくは水が使えても避難所生活でお風呂に入れないような場合、確かに赤ちゃんだけでなく、大人もそういう衛生的な対応が必要になります。それから１枚のタオルぐらいの大きさのもので、今そのご相談をしながら、そういう衛生関係の対応の充実も今いろいろ検討しています。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問","question":"ぜひそれは進めてください。ごめんなさい、不勉強で、名前はすごく聞いていたので、有名な名前ですが、サラヤ株式会社というのは何業界でしたか尋ねました。","respondent":"鈴木防災課長","answer":"多分一番有名なのは、ヤシノミ洗剤というのをお聞きになったことがありますか。あれをつくって、販売していらっしゃる会社です。","id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"すみません、ぜひ進めてほしいと求めました。計画をつくっているところが３分の１で、それから訓練をやっているところが３分の１だったのか、その辺もう一回確認のために説明を求めました。","respondent":"鈴木防災課長","answer":"さっき申し上げました３分の１ぐらいというのは、マニュアルをつくって訓練をするような活発な活動をしているところが３分の１です。申しわけありませんが、詳細な内訳について、今ご報告ができない状況です。","id":"exchange-028"},{"speaker":"つる委員","kind":"質問・要望","question":"参考程度でちょっと教えていただきたいのですけど、５の1)の共通ルールのところで、どういう事例で対処とか対応されたのかというところですね。事例だとか、また品川区でマニュアルを作成されている中で、どういうふうに決めているよという参考があれば説明を求めました。","respondent":"鈴木防災課長","answer":"先ほど申し上げましたように、宮古市から東日本大震災のときの実際の対応の中で情報をいただいた中には、その項目がございました。ただし、ある程度の期間長期化する場合には、そこはやはり適宜対応というようなことになってしまうかというのが現在の考え方です。","id":"exchange-029"},{"speaker":"つる委員","kind":"確認","question":"一昨年でしょうか、平成２３年から品川区も防災区民組織をまずは対象にということで認識しているのですけど、ＨＵＧ（ハグ）がありますよね。ＨＵＧであれば、机上での訓練ですから、また逆にこうしたほうがいいのではないかという意見が出しやすいのではないのかと思うのですよね。","respondent":"鈴木防災課長","answer":"そのようなツールを使いまして、ぜひ地域でもご活用くださいということでご紹介したり、体験していただいているという取り組みがあります。","id":"exchange-030"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ本当に、あくまでも机上の訓練ですけれど、積極的に区のほうからというか、防災課のほうもそういうお声かけをして、実施できるようにやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"松澤委員","kind":"意見","question":"トイレ、こういう数がありますという話もしましたけど、結論的には、３日間は当然トイレは間に合うということでしょうね。だけど、どのぐらい間に合うというふうに考えているのか、その点を聞きたいと思いますとの意見を述べました。","respondent":"鈴木防災課長","answer":"先ほど申し上げました１８０万回分のトイレだけではなくて、耐震化が進んでいて被害を受けなかったトイレは、水が確保できる限り使用できます。１８０万回分と、外部からの支援が来る二、三日間の間は何とか対応が可能だというふうに考えております。","id":"exchange-032"},{"speaker":"松澤委員","kind":"意見","question":"もう一つ、備蓄の食糧ですけれども、初期の３日間といいますけれども、東京都が２日、品川区が１日分という想定の中で、品川区は２.５日分ある。５日だなんていう記事を見たことがありますけど、２.５日で了としているのかどうなのか、ちょっとそこを聞きたいと思いますとの意見を述べました。","respondent":"鈴木防災課長","answer":"ただし、委員ご指摘のように、余裕を持ってといいますか、しっかりと対応できることを考えると、多いにこしたことはございません。これをあわせますと２.５日ですので、さらに外部の支援も含めて、それから都の備蓄も含めて何とか対応するという状況で備えているのが現状です。","id":"exchange-033"},{"speaker":"松澤委員","kind":"質問・要望","question":"学校避難所運営訓練、マニュアルをつくって活発にされている訓練が３分の１という話を伺ってびっくりしたのですね。やはりパスワードがどうとか、学校関係者と品川区の本部だけでできることですから、こっちの学校に行かなくてはいけないという話がありますよね。","respondent":"鈴木防災課長","answer":"申しわけありません、今後しっかりと力を入れまして１００％に、できる限り達成できるように区の支援もしっかりとしていきたいと考えています。","id":"exchange-034"},{"speaker":"大倉委員","kind":"質問・要望","question":"何点か確認という感じでお伺いできればと思っています。簡単にちょっとお伺いしますが、そこを教えていただきたいのと、そこはどういうふうな考え方なのか教えてほしいと求めました。","respondent":"鈴木防災課長","answer":"ご質問の１点目、建物、施設とは限りません。それからもう一つの避難所とそれから補完避難所の区分。","id":"exchange-035"},{"speaker":"大倉委員","kind":"質問","question":"一時集合場所というところで、ここで見ると４８ページの西五反田西二町会は書いてなくて、ちょっとお伺いをさせていただきました。１２６ページ、この辺のことについて、ちょっと教えていただければという質問です。","respondent":"鈴木防災課長","answer":"１２６ページの日野学園に関して、日野学園はご存じのように新しく一貫校としてつくって、収容人数の規模がかなり大きく余裕があります。もし収容人員、収容しきれなくなった場合には、日野学園の余剰の部分で受け入れるという意味で補完の指定をさせていただいている部分です。","id":"exchange-036"},{"speaker":"大倉委員","kind":"質問","question":"区としても積極的に取り組んでいただいて、よりスムーズな避難、そして安全な避難ができるように取り組んでほしいと求めました。キャパが大きいから、入ってこられなかった場合はどうなってしまうのかというところまで考えがあるのかどうかというのをお伺いできればと思います。","respondent":"鈴木防災課長","answer":"補完避難所の考え方です。考え方としましては、避難所全体で受け入れるという考え方ですので、収容するということで対応するというのが現在の考え方です。","id":"exchange-037"},{"speaker":"大倉委員","kind":"質問・要望","question":"日野学園、入れないから、では違うまたほかの施設に行ってくださいというような連携というのはとれているというようなことで認識しました。夜間ですから、夜に回っている方々ですから、その話し合いができるのかできないのかというところも教えていただきたい。","respondent":"鈴木防災課長","answer":"鍵につきましては、お渡しいただいておりまして、その方たちに学校のほうの対応ができない時間帯であれば入っていただくように考えているところです。","id":"exchange-038"},{"speaker":"大倉委員","kind":"確認","question":"警備員が来て、あけて中を確認するということなので、夜間については協議会の方たちの判断であけていただくということで認識しましたので結構です。１点ちょっと確認ですけど、その点、今どうなっているかお知らせほしいと求めました。","respondent":"鈴木防災課長","answer":"具体的には都のほうでペットの対応のためのセンターの設置を行います。学校避難所の施設の状況とか、その場合には、近隣の区の施設等でそのための場所を確保するというのが現在の計画での規定になっております。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問・要望","question":"すみません、１点、今のペットのことについて、ちょっと私も聞きたいと思っていたので最後に一つだけお伺いします。できないという話があったかと思いますけれども、されているのかどうか、ここをちょっと確認させてほしいと求めました。","respondent":"鈴木防災課長","answer":"申しわけありません、まだ現時点では各避難所連絡会議に情報提供をしておりません。もしくは避難所ごとにこれを考えていただくときには必要な、お知らせをした上で、避難所での対応を考えていただくようにしたいというふうに考えます。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"二つだけ伺いたかったのでご質問するのですけども、約１２万人とあるのですけど、私立学校も含めて１２万人だと思うのですよね。実際の計画では何人派遣される計画になっていらっしゃるのか伺いたいのと、そこも含めて、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"委員ご指摘のとおり、区のあらゆる施設を含めて１２万人に対応です。１２万人を超えたときに、すみません、説明のほうがちょっと不適切でした。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"簡易型プロポーザルによって策定業務を契約したと伺っていますけれども、区はその策定にどうかかわったのか、この経過を伺いたいと思います。現状についてですけれども、本日わかるかどうかあれですけど、準備中も含めて今現在どれぐらい進んでいるのか伺いたいと思います。","respondent":"鈴木防災課長、中村建築課長","answer":"それから現状につきましては、先ほどご説明した中のマンション管理組合の防災対策等検討交流会。ただし、居住する方の構成だとかに合わせたものをしっかり… スプリンクラー等の建築の設備に関する地震に対応しているかどうかですけれども、まず結論から申し上げますと、対応しております。… それから、このマンションの管理組合の検討交流会も含めまして、全てのマンションでの取り組み状況を現時点ではちょっと把握できておりません。","id":"exchange-042"},{"speaker":"中塚委員","kind":"提案","question":"もう１点提案したいのが、マンション、こうしたところで先行的に実施していくということも大切ではないのかと思うのですね。それがまたＰＲとして区民に示していく、こういう役割もあるのではないかと思いますけども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"各マンションでの取り組みの支援制度というご提案ですが、促進、支援をしていきたいというふうに考えているところです。庁舎管理との協議も必要ですので、今やるやらないというのはお答えできませんが、そういう必要も出てくるのかなというふうに考えているところです。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"まずはどういう実態があるのか、ぜひ急いで進めてほしいと求めましたので、改めて伺いたいと思います。初期消火というよりも、火災の発火の原因そのものを取り除くという視点で実施したと伺っておりますけれども、それぞれご答弁ほしいと求めました。","respondent":"鈴木防災課長","answer":"横浜市の場合は、その地区に限定をしてモデル的に実施をしているというのが横浜市の取り組みです。取りつけの簡単なものも出てきておりますので、現時点で区のほうで感震ブレーカーについての何か経済的な支援、補助をするという予定はございません。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"昨年度の末ぐらいでしょうか、ある意味なかなかすぐにつかないのでしょうか、ぜひ検討して進めてほしいと求めました。私は対象を広げるべきだと思っていますけども、この感震ブレーカーの設置というのは、感震ブレーカーの件だけ改めてご答弁ほしいと求めました。","respondent":"鈴木防災課長","answer":"それから、責務の部分もありますので、現時点で区のほうで個人の感震ブレーカーについての補助を実施する予定というのはございません。何でもかんでも重要だからということで、そういう意味からも感震ブレーカーに関しては現時点で補助をするという予定はございません。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"つまり、火災の発生の原因を取り除く対策をしっかり考えたらどうかということなのですね。しっかりマンション特有の被害を未然に防ぐ対策として捉えてやっていくべきだと思いますけども、改めていかがか尋ねました。","respondent":"松代防災まちづくり事業部長","answer":"そういう中で、私どもがまずすべきことは何かということでいろいろと検討して、できることを計画的に、今全力を挙げてやっているところです。計画的なものとして設置を、そういったものを支援する考えは今のところはないですので、ご理解をいただければと思います。","id":"exchange-046"},{"speaker":"こんの委員","kind":"質問","question":"何点かお聞きしたいと思います。もう既に年２回ですから、現状、交流会はどのような状況か尋ねました。","respondent":"大串住宅担当課長","answer":"簡単にちょっと設立の経緯をご説明させていただきたいと思いますけれども、平成２３年に、それの基礎調査ということで調査を行わせていただきました。実は明日ですけれども、今年度初めて、通算で言えば３回目になりますけれども、交流会を予定しております。","id":"exchange-047"},{"speaker":"こんの委員","kind":"質問","question":"これはどういうふうにお考えですか。先ほど全戸配布という話もありましたけれども、これを配っただけでいいのかという話もあるかと思いますけど、どのようにお考えか尋ねました。","respondent":"大串住宅担当課長","answer":"会報をお配りさせていただいたりとか、なかなか防災だけに特化して交流会を進めていくのは難しいことというふうに考えているところです。","id":"exchange-048"},{"speaker":"こんの委員","kind":"提案","question":"きっかけづくりとしてはいろいろな委員からも提案なり、こうしたものがあったらいいという提案があったりして、より実用的というんでしょうかね。手をかしてあげられるというような体制も含めてのマンションへＡＥＤを設置する、そうしたものへの支援というのは、どのようにお考えか尋ねました。","respondent":"鈴木防災課長","answer":"ご提案のありましたマンションにおけるＡＥＤの設置ですが、今までちょっとそういうような取り組みがなかったもので、近年やはりプライバシー。","id":"exchange-049"},{"speaker":"こんの委員","kind":"質問・要望","question":"中の方が外の出来事に気がついて手を差し伸べられるということもあるでしょうから、ぜひ研究をしてみていただきたいというふうに思います。自助としての力というか、そこら辺がまだまだだと、ここら辺はどう対策を今後とっていきますか尋ねました。","respondent":"奥田河川下水道課長","answer":"そういった中で、実は津波避難建物みたいな形で既に指定しておりますところが、ビル１軒とあとホテル１軒があります。すごくそういった意識が高くなってきておりまして、３軒目といたしまして、委員ご指摘のとおりすごく意識が高まってきているというのが現状です。","id":"exchange-050"},{"speaker":"こんの委員","kind":"質問","question":"徐々に意識が高まっていて、進んでいるということですけれども、マンション対策だから海沿いの方々は特にという言い方がちょっと妥当かどうかわかりませんが、早目にやはり自主防災組織を立ち上げるぐらいの、地域によっては力を入れなければいけないのかと思っているのですけど、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"基本的な防潮堤による対応が約３.５ｍ、最大津波が２.６１ｍということで、直ちに津波の危険はないという状況が一つあります。とはいえ、沿岸部に関しては、そういう津波の視点も重要ですというような情報もあわせてお知らせすることが重要になるかというふうに考えております。","id":"exchange-051"},{"speaker":"こんの委員","kind":"意見","question":"エリアを確かに限定というのは、それは私も考えておりません。やはりどうしたらこのマンション対策、そういった方面も考えながら進めるということも大事かというふうに思いますので、一応意見で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"塚本委員","kind":"質問・要望","question":"資料の２ページ目の４番のマンション管理組合と区の災害時協力協定のところで、(2)の協定締結の状況ということで、災害時協力協定９９本あります。残りの９５本についてちょっとお伺いしたかったのですけど、また物資備蓄のための場所の提供、ちょっと教えてほしいと求めました。","respondent":"鈴木防災課長","answer":"まず今ご質問にありましたこのマンション以外の９５件を含めた協定の対象、それから一般的な民間の事業者の方、多岐にわたるものがあります。","id":"exchange-053"},{"speaker":"塚本委員","kind":"質問・要望","question":"今お話を伺った中で、周知というのですかね、そういうことが地域に知られているのかどうか。災害発生時にどういった動きになるのかというのを教えてほしいと求めました。","respondent":"鈴木防災課長","answer":"と申しますのは、対応できないときまで来られても困るとか、今は一律に情報公開してお知らせするというようなことはしておりません。","id":"exchange-054"},{"speaker":"塚本委員","kind":"質問・要望","question":"今個々の取り組みでしっかりやっていくというお話で、ぜひそれはやっていただきたいというふうに思います。避難所としてマンションも含めて今後拡大をしつつ、進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"つる委員","kind":"提案","question":"私のほうでも今年の予算特別委員会でも提案させていただいたことにも関係するのですが、これは提案させていただきましたが、この間。そうしたことで提案させていただいたのですが、これについても提案させていただいたのですが、三つですかねとの意見を述べました。","respondent":"鈴木防災課長","answer":"ただ、申しわけありませんが、現在までそういう取り組みをしていないこともあります。区のほうでどこまでそういう公的な支援ができるかというのは、ちょっと今後研究をさせていただきたいというふうに考えるのが現時点の現状です。","id":"exchange-056"},{"speaker":"つる委員","kind":"質問・要望","question":"随時確認したいと思います。その辺をお聞かせいただきたいのと、もしあるのだったら、その辺も含めて説明を求めました。","respondent":"鈴木防災課長","answer":"ハンドブックの制作の中であわせて行いましたので、ちょっと個別にこの番組１本当たり幾らというのが明確ではない部分があります。それから、区の番組やケーブルテレビの中で確保している中での放送ですので、これを流すための放送経費が特に発生するということはないです。","id":"exchange-057"},{"speaker":"つる委員","kind":"質問","question":"委員会後でも結構なので教えていただくか、もしくは決算の場でも、情報共有という意味も含めて教えてほしいと求めました。先ほど反響というところもちょっとお聞きしたのですけれど、その辺のところ、その辺はわかるのか。","respondent":"藤田都市計画課長","answer":"そうした中で、あわせてケーブルテレビのご加入等についてもご検討をということで、情報の提供は私どものほうでしています。実績としては、その中でどうしたというところまでは把握はできていないです。","id":"exchange-058"},{"speaker":"つる委員","kind":"質問","question":"２分物を５本つくられているのでＤＶＤとかに焼いて、焼くというのは大した経費ではないと思うのですね、１枚当たりね。こういったものもＤＶＤに焼いて配布するとか、そういったことを検討されたらどうかと思うのですけど、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"ご提案いただきましたように、確かに必ずケーブルテレビをご覧いただけるマンションばかりとは限りませんので、有効な手段と思います。今後のいろんな支援策の中で、ぜひ案として検討させていただきたいと思います。","id":"exchange-059"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ検討してほしいと求めました。それはマンションそれぞれの性格でしょうけれども、そうしたことも含めて、こういった啓発の拡大をぜひやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"沢田委員","kind":"質問","question":"マンションとか、新しいマンションというのは、受水槽とか貯水槽とかというのはついていないのが普通ですか。飲料水になったりということで、災害時に活用できると思うのですけれども、そのあたりというのは現状どうなっているのか尋ねました。","respondent":"中村建築課長","answer":"ただ、地震に対して重さで不利なところもありますので、建物個々によって今使い分けがなされている状況です。割合としても、今のところ半々ぐらいなのかという感覚です。","id":"exchange-061"},{"speaker":"沢田委員","kind":"質問","question":"下だと汲み上げてポンプで電力がかかるということだと思うのですけれども、できるだけこういうところに、高層マンション等に設置できるのだったら設置したほうがいいのではないかと思ってお伺いをさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"本日、午前、午後の質疑の中で、なかなか手元に数字がなくて答えられなかった部分が幾つかあったと思いますので、資料で渡しても、また次の委員会で資料を渡しても、報告するでも、若干補足したほうがいいかと思いますので、正副でご議論いただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"中塚委員","kind":"質問","question":"そういうところでしょうかね。それぞれ質問された方の思いもあるかと思いますけど、幾つか議論を聞いていて思いましたので、そのことを出していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/480548?Template=document&Id=6440#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":75016,"voices":147}},{"id":"h25-20131002-4","meetingId":"h25-c-settlement","date":"2013年10月2日","dateIso":"2013-10-02","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時５１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を147件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"あくつ副委員長","kind":"質問・要望","question":"振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。第６項、５階の理事者控室に当委員会の模様を放送いたしますので、そちらでお聞きいただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明は終わりました。 それでは、平成２４年度品川区一般会計歳入歳出決算","agenda":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明は終わりました。 それでは、平成２４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"本多委員","kind":"質問","question":"４点質問します。７０ページの財政調整交付金もプラス２２億円の２年ぶりの増ということで、総括的にどのように成果を思っているのか、その辺を説明を求めました。","respondent":"本城企画財政課長","answer":"財政調整交付金のモデルとなりますいわゆる調整３税について、財政調整交付金という形で、想定していたよりも高い伸びを示しているものです。さまざまなＰＲとか、徴収に当たっての努力を重ねてきた結果、このような状況が確保されたと考えているところです。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"その後も、墨田区、足立区、葛飾区、江戸川区、大田区も東京都と今月にも締結をする動きがあると伺いました。品川区はどういう状況だったのか、この平成２４年度について状況を教えてほしいと求めました。","respondent":"鈴木防災課長","answer":"都営住宅等に関する東京都との協定に関してのお尋ねですが、昨年度、平成２４年度につきましては、都のほうから品川区のほうにそのような打診が来ておりませんので、平成２４年度についてはそういう協定の締結の事実はございません。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問","question":"平成２４年度は都から打診がないということですけれども、仮にこういうのというのは、都から言わなくても区から働きかけたりしないものか。例えば平成２５年度は、そういう試みがあるのかどうか、今後についても説明を求めました。","respondent":"鈴木防災課長","answer":"今後の取り組みについてですが、区としましても、民間の事業者の方とか、施設について、同様の協力の協定、お願いをしていますので、都のほうと協議をいたしまして、可能な都営住宅等があれば、ぜひそういう方向で協議を進めていきたいと考えております。","id":"exchange-004"},{"speaker":"本多委員","kind":"質問・要望","question":"７６ページのシルバーセンター使用料についてですが、前に伺ったところ、その考え方をお聞かせください。シルバーセンターの用途と、あと、全区的な暫定利用の用途について、２点説明を求めました。","respondent":"白鳥高齢者いきがい課長、柏原行財政改革担当課長","answer":"そういう中でも、やはりお近くの利用目的に沿った施設のほうを利用していただきたいということでご協力をいただいてきたところです。区民集会所、あるいは文化センター等の利用ということでお願いをしたいというところで… そういったときの施設にかかる暫定の利用の考え方ということであろうかと思いますけれども、全庁的な、総合的な判断もしながらということでやっている現状です。","id":"exchange-005"},{"speaker":"本多委員","kind":"質問","question":"これ、事業部が違っても、この辺、臨機応変にやっていけるものなのでしょうか。事業部をまたいでも臨機応変にできるのか、説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"基本的にはその事業をやっている部門が責任を持って行っておるのですが、事業部をまたぐような場合は、全庁的な調整も含めて、企画部も入って調整させていただいているです。","id":"exchange-006"},{"speaker":"本多委員","kind":"質問・要望","question":"よろしくお願いします。８７ページの国民体育大会の事業補助金について聞いていきますが、詳しく教えていただきたいのですけれども、状況を教えてほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"８７ページ、国民体育大会補助金についてご説明をします。そういうものの中で、私ども、平成２４年度は計上させていただいて、歳入を得たものがこの１,５８６万６,０００円ということにあります。","id":"exchange-007"},{"speaker":"本多委員","kind":"意見","question":"４日と予定をされておりますし、天王洲でのグラウンド・ゴルフは９月に既に実施されたということで、スムーズにできたのか。グラウンド・ゴルフの実施状況等、準備を長年してきた成果といいますか、その辺についてお聞かせほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"その５会場の連絡調整会議を定例的に開催をいたしまして準備を進めてきました。それで、明日、明後日、本番を迎える万端ということで、着々と準備を進めているところです。","id":"exchange-008"},{"speaker":"本多委員","kind":"質問","question":"既に行ったグラウンド・ゴルフ等の品川区内での発展性というのでしょうか、まずは品川で行われるという２種目について、発展性についてはどういうふうに感じられていますか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"グラウンド・ゴルフですが、先ほどもご説明しました、グラウンド・ゴルフは非常に地域の方々の愛好者が多いと。今後は、少しずつではありますけれども、ハンドボールが普及していくのではないかと考えています。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問・要望","question":"スポーツ全体で歳入も考えて、屋上の活用、庁舎の屋上等も視野に入れていってほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"６７ページの特別区民税、９５ページの寄附金、９８ページの広告料収入と同じページの区史等有料頒布収入についてお尋ねしたいと思います。まずこのふるさと納税の平成２３年度、平成２４年度ですね、それを教えてほしいと求めました。","respondent":"高森税務課長","answer":"寄附金控除ですけれども、平成２４年度が５,２１８件、平成２３年度は３４０件でございました。","id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"そういう視点だったものですから、それがどのぐらいあるのかと、こういうところなのですね。オリンピック・パラリンピックに関する基金の提案の後で、すごいすてきな提案だと思いましたけれども、その辺のご見解はいかがか尋ねました。","respondent":"寺嶋協働・国際担当課長","answer":"一つの財源にしながら、地域の子どもたちの活動や品川の地域の発信といった事業に取り組むことができるのではないかと考えておりますと。今回、改めて本基金の可能性について、さまざまな角度から研究して広くＰＲしていく必要があろうかと考えております。","id":"exchange-012"},{"speaker":"つる委員","kind":"提案","question":"そういうような提案もあると、品川区に対するふるさと納税も増えていくのではないかと、このようにちょっと思いましたので。そういう消火器の格納庫、ボックスにそうした広告的なものを載せるということをちょっと提案したいと思うのですが、このあたりはいかがか尋ねました。","respondent":"鈴木防災課長","answer":"学校避難所の場所を表示する標識に同様に広告を募って、経費を捻出しまして、設置をするという協定を結んでおります。ご提案につきましても、よいスポンサーの発見だとか、お願いの状況が進むようであれば、今後検討をしていきたいと考えております。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問","question":"１基５万円ぐらい、それが広告料収入で行って来いで賄えるとか、そういったところもご検討してほしいと求めました。いわゆる品川区でオフィシャルグッズとか、そうしたものの販売事例とか実績、このあたりについて説明を求めました。","respondent":"工藤総務課長","answer":"そのような啓発の用語を載せて図書カードを作成したりしております。東海道の宿場の場面を刷り込んで風呂敷を作製しておりまして、そういった形でグッズをつくっているところです。","id":"exchange-014"},{"speaker":"つる委員","kind":"提案","question":"品川区の開催地である競技を含めた、関連したようなものとかを、例えばオフィシャルグッズで販売をするというようなことを提案したいと思います。こういうことも自分なりにアイデアを考えたのですけれども、そういうアイデアも含めた何か品川区のほうで何か考えがあれば説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"今までの候補地よりもより厳しくなるですので、なかなかハードルは高いと思ってあります。そうはいっても、区としてのＰＲ部分はあると思いますので、研究するです。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"わずか残りましたので、ぜひその辺含めて、税外収入という観点も含めて、ぜひご検討ほしいと求めました。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"木村委員","kind":"質問","question":"そして、参考までに、平成２２年度、平成２３年度の歳入の金額は幾らでしたか。それも説明を求めました。","respondent":"谷口交通安全担当課長","answer":"１カ月にどのくらいの台数を売却するかですけれども、大体自転車で５００台を超える台数を売却しております。幾らかということで、平成２４年度は１台１,２００円ぐらいで売却をいたしております。","id":"exchange-017"},{"speaker":"木村委員","kind":"質問・要望","question":"そして、平成２２年度のご答弁では、従来休みに当たる月曜日や祝日も休まず引き取りに対応しているというご答弁がありました。そのように認識をされているのか、それとも何か別の対策が実行されたのかどうか、あれば教えてほしいと求めました。","respondent":"谷口交通安全担当課長","answer":"啓発につきましては、指導啓発プラス、放置自転車のクリーンキャンペーン等もまちの方と協力しながら実施しています。業者、年末年始を除いて実施している、返還を実施していますけれども、毎年、少しずつではありますが、返還率が向上しています。","id":"exchange-018"},{"speaker":"木村委員","kind":"提案","question":"数日、一応何日かかけて撤去というような規則があるのかどうか、それも教えてほしいと求めました。これは一つ提案ですけれども、これを天王洲付近の駅近にある、お答えほしいと求めました。","respondent":"谷口交通安全担当課長","answer":"区内には現在保管所に適した土地もない状況にありますので、現状では保管所を新たに開設するのは難しいと考えているところです。その利用率の状況を踏まえて、また考えていく必要もあるのかと思っているところです。","id":"exchange-019"},{"speaker":"木村委員","kind":"質問・要望","question":"平成２４年度に不法駐輪による事故とか、そういうものが報告されているのかどうか、それらがありましたらお聞かせをほしいと求めました。そういうことを前向きに考えてもいいのではないかと、このように思っておりますが、ご答弁を再度お願いいたします。","respondent":"谷口交通安全担当課長","answer":"撤去に伴う事故につきましては、現在報告等は聞いていない状況にあります。駐輪場の整備を進めておりますので、今年度も大森駅のほうも視野に入れて検討していますので、成果として駐輪場の整備を進めているところです。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"７７ページ、７３ページ、集会所使用料をお聞きします。このアップした理由をちょっとお聞かせいただきたいのと、また、消費者センター使用料の内容を説明を求めました。","respondent":"米田商業・観光課長","answer":"平成２４年度、１２カ月分ということで、およそ金額として前年度より約３カ月分の伸びがあるというようなことでご理解いただければと思います。","id":"exchange-021"},{"speaker":"吉田委員","kind":"提案","question":"これは例えば提案ですけれども、大井町の駅ビルにあるアトレの派出所が１階にあると思います。２０２０年のオリンピック・パラリンピックに向けて、そういうお考え等、今後の展開等ございましたらお願いしますとの意見を述べました。","respondent":"米田商業・観光課長","answer":"種々検討も行ったところですが、事務局機能も兼ねてということでの移転ですので、困難であった。そういった意味で、いわゆる施設の設置以外にどういうことができるかというようなことについて幅広く検討、発信を行ってまいりたいと思います。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"先ほどセンターの使用料のことで、これは賃料ということでよろしいのでしょうかね。関連団体ということで、一般の何％ぐらいいただいているのかをちょっとお願いいたします。","respondent":"米田商業・観光課長","answer":"公有財産管理運用委員会にお諮りした結果、一般の５割というようなことで、５割減免の額でお支払いいただいているものです。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"５割ということで、これが９４万３,３９２円、年間で１８８万円で、大体１カ月にしますと１５万七千幾らですかね、そのくらいなのです。款をまたいでしまうかもしれないですけれども、人件費がどこに入っているのか、私、わからなかったので、それも説明を求めました。","respondent":"平澤経理課長","answer":"財産台帳価格の、建物の場合には、１０００分の６を基準利回り、期待利回りといたしまして計算するということになってあります。その分をお貸ししているということがありますので、一般のいわゆる普通財産の貸し付けとは違った計算になっているです。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"２０２０年のオリンピック・パラリンピックに向けて、観光の情報発信地としてぜひＰＲを充実していっていただきたいと思うのです。続きまして、お時間がないので、すいません、７３ページの集会所使用料についてお伺いいたします。","respondent":"久保田地域活動課長","answer":"これで１３の地域センターの中で残っているのが荏原第一地域センターです。区単独ではなかなか難しいということで、今検討していますけれども、そういった中で地域センターの耐震化を進めていきたいと思ってあります。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"荏原第一が耐震がまだというお話をお聞きしました。荏原第三と第五が新しくなりましたけれども、利用客の、利用の方のお声などを拾っていらっしゃるのかをお願いいたします。","respondent":"久保田地域活動課長","answer":"荏原第三のほうは、特に地域の方から集会所の形式が非常によくなったということで好評いただいてあります。バリアフリーにつきましても、全体的にバリアフリー化をしてございまして、どなたでも気軽にご利用できるようになってあります。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"決算シートではついに基金が６９９億円となりましたけれども、その健全財政のつくり方を伺いたいと思います。この堅実な健全財政、職員定数削減とあるが、どういう仕組みで増やすことができるのか、伺います。","respondent":"本城企画財政課長","answer":"いろいろな行革に取り組んできた成果だということの関係でご質問があったのだと思いますが、中長期的な、そういうことです。３０億円につきましては、すべての歳入と歳出の収支差が３０億円ということで、それは次年度の繰越金のほうに回っていくという関係です。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"３０億円の黒字ですけれども、次年度の繰越金に３０億円ということなのでしょうか。でたかだか１年間で７０億円、３月補正からは５０億円も基金繰入金が取り崩さなくてよい財政状況とは、改めて伺いたいと思います。","respondent":"本城企画財政課長","answer":"先ほどもちょっとご説明させていただきましたが、最終補正の段階よりも１３億円ほど増えたこと、１０億円ほど増えたこと。当初予定していた取り崩しがしないで済んだ結果、当初予算に比べて少ない取り崩しで済んだという、このような関係です。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"単純に差となる５８億円はどこへ行ったのか、伺いたいと思います。財調だったり、それ以外にも働いている要素がなければこの５８億円が説明ができないと私は思いますけれども、この点伺いたいと思います。","respondent":"本城企画財政課長","answer":"当初予定よりも歳入面、結果的に当初取り崩しを予定していた基金が取り崩さずに済んで、このような決算状況になった。一方では、余力が出た部分を最終補正等の段階でさらに積み増して、全体として基金残高となっている、そのような関係です。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"この３０億円黒字というのは概念的な金額で、実際のお金の流れとは違うという、そういうことでしょうか。これはなぜかというと、改めてこの点、伺いたいと思います。","respondent":"本城企画財政課長","answer":"３０億円につきましては、これは冒頭も説明させていただきましたが、実額に基づいたものです。歳入の見込みをつくるときに、基本的には財源に穴があかないようにかたく見込むということで、そのような形で見込んだ結果。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"改めてその点を伺いたいと思います。こういう関係に力学が働いていると思うのですけれども、いかがか尋ねました。","respondent":"本城企画財政課長","answer":"そのプロセスの中のご説明をさせていただきましたが、将来的な施策運営のために、基金も含めて財源確保しながら進めていっているです。","id":"exchange-031"},{"speaker":"中塚委員","kind":"意見","question":"税収は限られている、堅実な財政運営とおっしゃいますが、いずれにしても、当初予定していなかった予算から生まれた余力分、余裕分、真っ先に区民の暮らし応援にこそ充てるべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問","question":"事項別明細書のほうの３４ページで、不納欠損額が１６５万５,４００円で、収入未済額が６,３１７万７,０８６円ということで計上されております。平成２３年度の決算書を見ても、どういった手続きといいますか、その辺の手続きのところをお伺いしたいと思います。","respondent":"久保田会計管理者","answer":"放棄になったとか、そういうことをそれぞれ決裁して、決定するということになってあります。今回、この資料については、私どもの会計管理室で集約して、資料としてお出ししていると、こういう状況です。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"そういうことでいきますと、収入未済額が今年度で６,３００万円強あるわけですけれども、これが今後どういうふうに推移をしていくのか。毎年毎年６,０００万円ぐらいのものが出てくるとなると、どこを見ればわかるのかというところをお伺いしたいと思います。","respondent":"久保田会計管理者","answer":"特に滞納になった場合については、滞納繰越としてこの未済金額は残ったままで、また毎年計上されるという形になるかとは思います。そういうようなところが一般的な状況です。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問","question":"滞納として繰り越されるというようなことをお伺いしたのですけれども、今どれだけ残っているということがわかるのかどうかということ、まずその点をお伺いしたいと思います。","respondent":"久保田会計管理者","answer":"今の３５ページのところからずっと追っていただくと、それとも債権として残っていくかという、２種類が出てくるのかというふうには思っております。","id":"exchange-035"},{"speaker":"塚本委員","kind":"質問","question":"積み重ねてきて、実はこれだけの債権があって、これだけの放棄をしているというようなことがある使用料については言えると。業務のあり方として改善をすべき点があるのではないかといったような見方も必要なのではないかと思うので、表というか、その点いかがか尋ねました。","respondent":"久保田会計管理者","answer":"収入未済額のほうについて具体的にどういう形に今後なっていくかというのは、この決算の中で出すのにはなかなか難しい課題もあるかと思いますので、いずれにしても検討してみたいと考えていますので、よろしくお願いします。","id":"exchange-036"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは要望というか、これは意見ですけれども、よろしく検討のほうをお願いしたいと思います。平成２３年度に比べて改善しているということで、数字の上でもＰＲの効果というのがどの程度出ているのかといったところをお伺いしたいと思います。","respondent":"高森税務課長","answer":"９８％以上の方が現年度で納付いただいているわけですので、残りの２％の方については、ご相談いただく。財産があれば、滞納処分を行って、納付を促していくというふうな形で今進めているところです。","id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"いろいろＰＲされている内容をご説明いただいてありがとうあります。実際数字として、収入未済額が、平成２３年度に比べて改善したという、そういった数字の上での成果というのもきちっと出ているということか尋ねました。","respondent":"高森税務課長","answer":"持ち直してきた部分が５億円ほどあったということと、平成２４年度は徴収額が９億円ほどになって、増額になってあります。ですから、この上積み部分の４億円以上がさまざまな形での徴収努力によって増額したと認識しています。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"７年後の先の話ではありますが、あと、ここに非常にたくさんの外国の方がオリンピック・パラリンピックのときに来られるのではないかと。区として今後どういうふうに取り組んでいかれるかとか、実際にあるいは検討を始めているとか、そんな状況をちょっとお伺いしたいと思います。","respondent":"工藤総務課長","answer":"そういった中で、委員ご提案の外国人の方の取り組みというものを今重点的に目標を掲げて行っているところです。そういった中で何か連携した形で相乗効果ができるような部分というのは、私どもも品川区として競馬組合のほうに申し上げたいと考えておるところです。","id":"exchange-039"},{"speaker":"渡部委員","kind":"質問","question":"基金のよしあしというのではなくて、調べていてわからなかったので伺わせていただいたのですが、学校のことを聞きます。８５ページの記載の中で、広さによってなのか、補助基準額の違いというのがどういうふうに出ているのかというのをまず教えていただけますか尋ねました。","respondent":"齋藤庶務課長","answer":"委員のご質問にお答えするに当たって、８２ページに３目教育費負担金というものがあります。あるいは武道場、プールといったものについての付加的なお金が、交付金が頂戴できるです。","id":"exchange-040"},{"speaker":"渡部委員","kind":"確認","question":"もう１回確認ですけれども、ざっくりでいいので、例えば改築するとなるとどれぐらいかかるのかというのをわかれば教えてください。パーセンテージでいいです。","respondent":"齋藤庶務課長","answer":"小学校であれば１１億円、中学校であれば６億円ということで算定されておりますので、それで有効活用しているです。おおむね恐らくは３分の１は行かないだろうと考えております。","id":"exchange-041"},{"speaker":"渡部委員","kind":"質問","question":"施設格差の問題を含めて、建築計画、長い目で見たとき、どういうふうにしていくか。基金に対してもどういう感じで積み増していくかというのを総合的にお話ほしいと求めましたが、よろしいか尋ねました。","respondent":"本城企画財政課長、齋藤庶務課長","answer":"あるいは、それらを含めてトータルな観点から財源の見通しを立てる中で、基金としてどれだけ見込まなくてはいけないのか。平成２０年ごろ、かなり基金を取り崩しながら改築需要に対応してまいりましたので、見通しを立てているところで… 委員のご指摘の老朽度との関係ですが、耐震補強工事を行いました。おおむねの基準が６５年でございまして、長寿命化も含めて補修をしています。","id":"exchange-042"},{"speaker":"渡部委員","kind":"質問・要望","question":"これからしっかり計画を練って、必要なところはやはり必要にかかるわけですから、しっかり使ってほしいと求めました。これは３年で切れるよというのが何かあったような気がしているのですが、どういうふうな形で維持をされていくのか、説明を求めました。","respondent":"齋藤庶務課長","answer":"その後の維持管理経費については３年間見ていきます、こういう約束になっております。肥料をまく機械などを現物で頂戴いたしましたので、こういった機器も活用しながら、学校を中心に維持管理に努めていきたいと考えています。","id":"exchange-043"},{"speaker":"渡部委員","kind":"意見","question":"補助金が切れて芝が維持できないという、ちょっと残念なことにならないように、何とか地域の方々のお力を借りながら、貴重な芝生、天然芝の校庭ですので、品川区として頑張って維持していただけるようお願いを申し上げて終わらせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"向委員","kind":"質問","question":"どんどん伺っていきますが、特に図書館コピー代でちょっとお尋ねしたいのですが、平成２３年度は収入が７,６０４万円ほどあったと思うのです。どういう目的で２階のスペースにたくさんの本を、いいと思うのですけれども、あえてあそこに本を置いてある理由をちょっと説明を求めました。","respondent":"多並公園課長、安藤文化スポーツ振興課長、江部健康課長","answer":"続きまして、区民の利用者の割合ですが、アンケート調査をした結果、５％程度ということで、今のところ利用があります。平成２４年度… 委員ご指摘のとおり、品川歴史館には、図書の資料室が２階にはあります。１階事務室に声をかけていただけますれば… 平成２４年度まで助成がございましたけれども、平成２５年度から一般財源化して、平成２５年度は組んでおります。","id":"exchange-045"},{"speaker":"向委員","kind":"質問","question":"高いものだと２,４００万円ということで聞いたのですが、そういうお話は出たことはないのでしょうか、その点を伺わせてください。コピーのサイズはＡ３までということだと、それをお尋ねしたいのと、ちょっとざっとですね。","respondent":"多並公園課長、安藤文化スポーツ振興課長、中元品川図書館長","answer":"有料という件ですが、なかなか今の無料の中でアクセスということで、便利のいい大井町とのピストンということが重要かと考えています。購入についても… ２階の閲覧コーナーの照明の件ですけれども、早速現場を確認いたしまして、明るさを確保するような形で工夫をさせていただきたいと思ってあります。図書館のコピー機のサイズの件ですが、現在Ａ３までということで、大変コピー機のコストの面も考えざるを得ません。","id":"exchange-046"},{"speaker":"高橋委員","kind":"質問・要望","question":"この差が出たのは、今回の決算で出たのは、どういった点でしょうか。それからもう一つは、起債の利子のほうですけれども、これは約３,５００万円ですかね、決算額が下回っている。","respondent":"本城企画財政課長","answer":"決算額との関係です、予算の関係ですが、当初予算を組んで、減税補てん債等を組んだ初めの段階と利率の変更がありまして、その分の差が出たものが決算額の差となっているものです。","id":"exchange-047"},{"speaker":"高橋委員","kind":"確認","question":"両方ともそうですか。平成２３年度の場合は、もう１回確認で、利率の変更でこの２つの予算と決算の差が出たのか。","respondent":"本城企画財政課長","answer":"先ほどご答弁させていただいたとおり、利率の見直しの関係でこれだけの差が出てきたという形です。","id":"exchange-048"},{"speaker":"高橋委員","kind":"質問","question":"編成時では確定していないのですが、出納閉鎖期間の間にそういう話をきちっとして、こういった決算のほうに出てきたという理解なのですか。比率が変更になったというのは、どういう時期にどうなるのかがわからないので、すいません。","respondent":"本城企画財政課長","answer":"利率の変更があった時点は、年度の途中で利率の変更があって、最終的にその分だけ変わった分が、予算額と差異がある部分です。","id":"exchange-049"},{"speaker":"高橋委員","kind":"質問","question":"そのように利率の変更が年度途中にあって、こういう差が出てくるということで、答弁からわかりました。１０年以上経っていますから、過去にどういったときに一時借り入れをしたことがあったのか、もしわかれば教えてほしいと求めました。","respondent":"久保田会計管理者","answer":"例えば平成７年度の場合には、一時的に資金が不足したという場合もありましたので、そういったときに期間を限定してお借りしたということはあります。大体主なものとしては、そんな状況です。","id":"exchange-050"},{"speaker":"高橋委員","kind":"確認","question":"確認ですが、２３区の中でこの金額については、ほかの２３区と比べてどのような形になっているのでしょうか。これからも健全財政と、先ほどお話ありましたが、確保していっているのかどうか、地方債に関連してその見通しをお伺いしたいと思います。","respondent":"本城企画財政課長","answer":"起債についての基本的な考え方ですけれども、なるべく借金をしない形で対応し、その財源の手当てがあるものについて借り入れをしているという形です。","id":"exchange-051"},{"speaker":"高橋委員","kind":"質問・要望","question":"実質的に区の負担はどれぐらいかということと、その数字をお伺いするのと、不断の見直しで健全財政を維持していってほしいと求めました。区の負担だけ、すみません。","respondent":"本城企画財政課長","answer":"起債の元手となりますものとして、減債基金で積み立てている部分等あります。逆にマイナスになるという形で、十分そういう部分、財源が確保されているという状況になっております。","id":"exchange-052"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは８１ページの母子生活支援施設運営費、それから、９９ページのリサイクル活動推進事業、その２点をお伺いしたいと思います。そこでまず改めてお聞きしたいのが、事業の目的と、それから、利用者、対象の入所の要件というのがあれば、教えていただきたい。","respondent":"伊崎子育て支援課長","answer":"平成２４年度は、子育て支援課といたしましては、今申し上げました要件に適合する方を入居していただけるように図っているところです。対象につきましても、今ご指摘ありましたアフターケアを含めまして、より地域の中で自立生活を送れるような方を対象としています。","id":"exchange-053"},{"speaker":"こんの委員","kind":"質問","question":"いわゆるここにはモニタリングの評価の中にもありましたけれども、改善する点として、真に入所を必要とする者の受け入れというふうにありました。真に入所を必要とすると、今ご答弁いただいた入所要件と真に必要という、ここら辺はどのようなことをお考えか尋ねました。","respondent":"伊崎子育て支援課長","answer":"なかなかご本人の意思が、なかなか入所に至らないというところもございまして、こういった方たちの対応をどのようにしたら入所に向けていけるのかというところが一つの課題と捉えております。","id":"exchange-054"},{"speaker":"こんの委員","kind":"質問・要望","question":"入所施設のあり方、また、入所するに当たっての必要な方への支援ということをぜひお考えをほしいと求めました。こちらの内訳を若干教えていただきたいのと、あるいは、事業から見る事業の現状とか評価というところを説明を求めました。","respondent":"伊崎子育て支援課長、小林品川区清掃事務所長","answer":"確かに支援を必要なご家庭というのは数多くいらっしゃいますが、自立支援というところに目的を持ってやっていこうというふうに考えております。支援が必要な方につきましては… したがって、収入も出ていないのですが、ただ、資源回収業者が、むしろ収益が出ないために回収できない分だけ区が回収した紙パックがこの金額です。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問","question":"８４ページ、９１ページの住宅・建築物耐震化支援策についてお伺いをいたします。そこでお伺いしますけれども、当初予算が１１億１,３００万円余ですが、決算額が５億３,９００万円余になっています。","respondent":"品川木密整備担当課長","answer":"当初予算と決算額の差ですが、これは端的に申しますと、特定緊急輸送道路沿道建築物耐震化、こちらが耐震改修費用、これだけで大体８億円程度でありますけれども、用意をしておりまして、これが昨年度１件も執行がなかったということで、これだけの差が開いてあります。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問","question":"２点お伺いしたいのが、そして２点目は、これのことです。今お伺いしたらば、まずこの決算額を教えてほしいのと、できていないのか。","respondent":"品川木密整備担当課長","answer":"まず件数としまして、５５件、特定緊急輸送道路の診断件数のほうは実績としています。お考えになる期間もあるということで、改修、それから補強設計のほうはつながらなかったと考えております。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本当に計画を立てて予算もつけたのですから、今後の対策をお聞かせいただきたいのと、あと課題についてお伺いします。達成率がわかったら説明を求めました。","respondent":"品川木密整備担当課長","answer":"東京都とそれから区のほうが連携しまして、耐震化のほうを促していきたいと考えております。こういった活動を中心にして、今後も耐震化の啓発等を区で行っていきまして、目標の９５％にしていきたいと考えております。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほども理由は伺いましたけれども、私、先日、共産党の一般質問の区長の答弁、住宅耐震化は自助であると。十分お願いしたいのと、２点目は、いかがか尋ねました。","respondent":"品川木密整備担当課長","answer":"金額改定のことをおっしゃっているのかというふうには考えるのですが、それから平成２３年度、２倍から３倍近く前よりも増加しております。一応このことを見て、区としてもこれから啓発等をしていきたいと考えています。","id":"exchange-059"},{"speaker":"藤原委員","kind":"質問・要望","question":"歳入ですが、一般質問で大きく伺っているので、本日は細かく伺わせていただきたいと考えています。料金が６分割というのですか、非常に効率が悪いと思いますが、区としての見解を説明を求めました。","respondent":"平澤経理課長、堀越人事課長、井浦戸籍住民課長、安藤文化スポーツ振興課長、伊崎子育て支援課長、白鳥高齢者いきがい課長、谷口交通安全担当課長","answer":"私からは総務費負担金、職員互助会の歳入についてご説明を申し上げます。そのほか、塵埃の処理等がこちらの負担金に、年間の歳入となっているもので… 職員互助会で歳出のほうですが、職員互助会に際しましては、そういった福利厚生の事業に関して支援をするということで助成を行っているものです。… なぎさ会館のここ５年間の件数の平均ですが、年間３３９件でございまして、平成２４年度の実績を見ますと、３２２件で、約５％の減となっています。","id":"exchange-060"},{"speaker":"藤原委員","kind":"質問","question":"臨海斎場との推移を合わせるとどうでしょうかということと、あと、品川区民でお亡くなりになった方が全体でどのぐらい１年間あるのか。極めて施設の中で低いわけですけれども、特に低い八潮についての見解と、そもそもどういうふうに利用料は設定しているのか、お伺いします。","respondent":"本城企画財政課長、伊崎子育て支援課長、井浦戸籍住民課長、安藤文化スポーツ振興課長","answer":"これ、これは独立した節として新たに加えた関係で一番最後に載っていますが、雑入の中の位置づけではないということでご理解いただければと思います… そちらを含めますと、２,７４４件ご利用がございました。去年に比較しましても増えているところですが、引き続きホームページ… 逆に、証明交付業務という比較的定例的な業務につきましては、１.５倍から２倍程度増えてあります。","id":"exchange-061"},{"speaker":"藤原委員","kind":"質問","question":"確かになぎさが受け皿になっているということは評価するのですけれども、やはりそれでも１０％ちょっとではないですか。その辺がいかがでしょうかということと、外国人の利便性というお話を伺ったのですけれども、その辺についてはいかがか尋ねました。","respondent":"井浦戸籍住民課長","answer":"区内でお亡くなりになった方の約１２％前後の方が毎年お使いになっていただいております。その場所、あるいは葬儀に対する考え方が変わってきていると、そのような状況も総合的に見ながら今後考えてまいりたいと考えています。","id":"exchange-062"},{"speaker":"井上委員","kind":"質問・要望","question":"地域福祉推進包括補助金と９６ページの諸収入のシルバー人材センター貸付金返還金と７１ページの負担金の中からお伺いをしたいと思います。もう少し品川区として福祉施策を充実していくことを求めたいと思うのですけれども、お伺いしたいと思います。","respondent":"本城企画財政課長","answer":"少子高齢化の対応を含めて充実させていく傾向の中で、その中では、２３区の中の一般的な状況と軌を一にしていると考えているところではあります。","id":"exchange-063"},{"speaker":"井上委員","kind":"質問・要望","question":"当然増えていくだろうと思いますけれども、バランスの問題で、やはり力を入れてほしいと求めました。そのハードルをぜひ高く意識をしていただきたいと思っているのですが、何かお示しいただけるものがあったらお願いしたいと思います。","respondent":"中山障害者福祉課長","answer":"今後区の中では、まず心の差別の解消というところでは、障害者福祉課が中心になってやってまいるところです。それから、バリアフリーのところにつきましては、所管の道路課ですとか、そういうところで対応していくようになっていくと考えています。","id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"今回２０１２年は所管が高齢者福祉課からものづくり・経営支援課になって見えなくなってしまっているのですけれども、お伺いをしたいと思います。その理由を説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"新たにものづくり・経営支援課のほうで就業関係の業務を担うことになりまして、そうしたことに伴って、組織改正に伴って動いたです。それで、貸付金につきましては、そうした関係で、ものづくり・経営支援の部分に記載をさせていただいているというものです。","id":"exchange-065"},{"speaker":"井上委員","kind":"提案","question":"私たちは、わかりやすい、区民にもわかりやすい予算書、決算書を提案をした中で、逆行していると思える。この中で、低所得者等対策事業ということでありますけれども、その部分で、生活福祉関連の事業内容とそれぞれの金額を説明を求めました。","respondent":"竹田生活福祉課長、本城企画財政課長","answer":"あるいは受験の費用を貸し付ける受験生チャレンジ貸付事業、それから、低所得者や離職者に対する相談窓口の設置の事業です。貸付金のほうが… 今回全体を整理する中で予算書の表記に合わせた形の表記にさせていただいている関係で、人材センターの支援事業もこのような形の表記に合わせたです。… 受験生チャレンジと低所得者の窓口設置と申し上げましたが、もう一つございまして、生活保護の法外で行っております被保護者自立促進事業もあります。","id":"exchange-066"},{"speaker":"井上委員","kind":"質問","question":"予算書を違う形でつくらないと決算書がそうならないので、決算書をつくる段階でわかりやすい表記へぜひお願いしたいと思います。それから、中高生の就学支援事業が２つあるということでしたけれども、それぞれの実績と高校進学につながった人数の推計を説明を求めました。","respondent":"竹田生活福祉課長","answer":"こちら、低所得者の部分と生活保護受給者の家庭に対する支援と大きく分けて２つあります。高校生が２１人、中学生が７７人、高校生が２８人となっております。","id":"exchange-067"},{"speaker":"井上委員","kind":"質問","question":"卒業がどうだったのかということがとても大事なことなのですけれども、何人の方が卒業されたのか、説明を求めました。","respondent":"竹田生活福祉課長","answer":"生活保護受給者に向けたこちらの次世代育成支援ですが、平成２１年度から始まっております。１人中退、平成２４年度におきましては、２５人が進学して１人中退ということになっております。","id":"exchange-068"},{"speaker":"井上委員","kind":"提案","question":"ぜひ提案をしていきたいと思うのですが、款のほうで、歳出でやりたいと思いますとの意見を述べました。","respondent":"平澤経理課長","answer":"貸し付けに伴う金額だというふうにお答えしたところではありますが、うちは平成２３年度も同一の金額をいただいているところです。","id":"exchange-069"},{"speaker":"山元委員","kind":"質問・要望","question":"私からは７５ページの歴史館使用料と時間があれば隣の７４ページのこみゅにてぃぷらざ八潮、これについてお伺いをしたいと思います。これはどういうことなのか、まず初めにこちらをご説明ほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"それからまた建築基準法第１２条点検というのがございまして、その点検をやったところ、やはり非常に老朽化が各所で進んでいました。そんな中で書院で賄ったというところで、今回茶室が決算書には掲載をされてございません。","id":"exchange-070"},{"speaker":"山元委員","kind":"質問・要望","question":"予算書では８０回のところ、５２回しか使われていないというのは、何が原因で使用が少ないのでしょうか。その辺はどのように思われているか、現状教えてほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"そういうような茶室を今後本当に大切に使っていくために、しっかり調査をして、記録をさせていただきたいと考えています。そして、書院の回数の減ですけれども、これは自然減と申しましょうか、回数が少なかったです。","id":"exchange-071"},{"speaker":"山元委員","kind":"質問・要望","question":"ここでちょっと一つ教えていただきたいのは、午後９,０００円というふうに、書いてあります。この辺、どういうふうな形で決められているのか、その辺をちょっと教えてほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"非常に難しいご質問ですけれども、歴史館は昭和６０年５月にでき上がりました。この利用の料金の設定をされたものというふうに推測できますけれども、これ、ちょっと調べさせていただきたいと思います。","id":"exchange-072"},{"speaker":"山元委員","kind":"質問","question":"この講堂を使用するときに、見学するお子様たちの説明会等々で使うということでありますが、それ以外にも使った２０回でしょうか。それとも含んでいないのか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"その中で、そういう歴史を学んでいる、そういう登録団体の方がいます。そういうような方もここを利用して、今申し上げた広く区民を対象にした講習会等をやった、こういうような回数もここには含まれているところです。","id":"exchange-073"},{"speaker":"山元委員","kind":"質問","question":"基本的に伝統的文化活動を推進するようなものでないと使えないということであれば、それ以外のもし何か申し込みがあったときにお断りしたのかどうか。さっきお話していました、内容は、それでもあくまでも基本的に伝統的な活動をしない人のところには貸せないということなのか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"大森貝塚から、何世紀にわたってのものができているというもので、非常に評価されている意見も多数私は聞いてあります。そんな中で、歴史館というものがこういうものだということを今後も皆様に周知をして、来ていただきたいと考えています。","id":"exchange-074"},{"speaker":"鈴木（真）委員","kind":"質問","question":"８６ページで知的障害児通園施設給付費、９２ページの経済センサス活動調査、この点についてお聞きしたいと思います。２点説明を求めました。","respondent":"久保田地域活動課長、安藤文化スポーツ振興課長","answer":"この経費の積み上げですけれども、調査にかかる経費をそれぞれ積み上げてまいりまして、必要なものを要求をしてということで、実施をしています。実際にそういうのを積み上げてやったところ… そして、この回数ですが、ほぼ少年野球の実施の状況です。コマで申しますと１,５５９コマありまして、日曜を入れますと、使用率というのが５８.３％になってあります。","id":"exchange-075"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その点について教えてください。年末年始、このときはたしか開いていると思いますが、その点もちょっと確認をさせてほしいと求めました。","respondent":"久保田地域活動課長、多並公園課長","answer":"私ども、必要な額ということで要求して使っているところでございまして、事業が終わった後きちんと精算をして、不用な額が出ればお返しをしています。 鮫洲運動公園につきましては、年末年始の期間は閉鎖した形で管理しています。","id":"exchange-076"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"委託金の精算ということですが、そうすると、これは年度内に精算しているのですか。これは要望事項があるので、ちょっとその辺、お考えを教えてほしいと求めました。","respondent":"久保田地域活動課長、多並公園課長","answer":"精算の件ですけれども、これは、国と決められた期日までにきちっとそういった手続きをして、実績の報告もして、手続きを進めてやっているものです。 たこ揚げということで、地元の皆様のご要望もいただいておりますので、開放する形で今後検討してまいりたいと考えています。","id":"exchange-077"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そういう意味でお聞きしているのですが。もう１回、お答えを。","respondent":"久保田地域活動課長","answer":"すいません。私の説明のほうが不足していまして、実際にかかったというものをきちんと報告をして、それでお金のやりとりをやっているです。","id":"exchange-078"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、委託金で歳入が合わなくなってしまうのではないですか。そこら辺ちょっと、もう一つほかに聞きたいことがあるので、簡単にもう１回答えて。","respondent":"本城企画財政課長","answer":"合わない分は、あとは人件費のほうで払っている分もありますので、それも含めて合っているという形になっております。それも含めた、人件費は人件費の支出の中で書くような形になって、歳出はそのような単位になっているです。","id":"exchange-079"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう１点お聞きしたかったのは、品川児童学園の関係です。５５年に移管する前からもう建っている建物なので、まずいつごろからこの建物は建っているのか、ちょっとそれを説明を求めました。","respondent":"中山障害者福祉課長","answer":"品川児童学園についてのお尋ねですが、こちらの建物、昭和４６年に竣工ということになっておりますので、四十数年たっている状況です。","id":"exchange-080"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、この建物の老朽化している中、それと、敷地がたしか２,７００m2以上ある広い敷地です。今後、この建物の改築とか、広い意味での展開を考えたときに、区の考え方をちょっとお聞きしたいのですが。","respondent":"中山障害者福祉課長","answer":"１階のところがいわゆる通園部門ということで、知的障害児の方の通われている施設になっています。今工夫を凝らしながら、２階のところで相談とコンパスという事業を、長計の後期の期間の中で一定の方向性を考えていければと思っているところです。","id":"exchange-081"},{"speaker":"鈴木（真）委員","kind":"意見","question":"隣にプチレーブもありますし、あれの活用、今後考えたときに、どう考えるのか。それだけのさっき言った２,７００m2ある中で、その辺、もう１回お答えをお願いしたいと思いますとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"例えば特別支援学校の卒業生の方の受け皿であるとか、あるいは、重度障害を持たれた方の受け皿といったところも今後必要になってくると考えています。","id":"exchange-082"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"改めて建替えということで、ぜひ実現に向けてほしいと求めましたので。民生費の中でちょっとお聞きするかもしれませんが、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問","question":"それはそれで結果論ですから構わないと思いますけれども、しかしながら、この基金をどう考えていくのか。それが平成２４年度の考え方としては、そこら辺の今後の区の事業の展開のあり方についての考え方をお聞きしたいと思います。","respondent":"今井制度改革・待機児童対策担当課長、本城企画財政課長","answer":"ご質問の保育料や利用者負担の今後の考え方ですが、委員ご案内のとおり、平成２７年４月から子ども・子育て支援新制度が始まってあります。この中で、利用者負担額という形で今検討中でございまして… 必須のものであれば、過去に積み立てたものもきちっと使いながら事業を展開していかなくてはいけないという、そういうような基本的な考え方の中での形と考えております。","id":"exchange-084"},{"speaker":"西本委員","kind":"質問・要望","question":"基金というのは、本来はいろいろな意味で行革などを進めていて基金をためていこうというのはありますけれども、それがどうなるかわからないですよね。事業の計画性なり、当初予算を立てるべきではなかろうかと私は考えますが、その考え方についてご意見をほしいと求めました。","respondent":"今井制度改革・待機児童対策担当課長、本城企画財政課長","answer":"公立施設における施設型給付の財源については、現行どおり区市町村が１０分の１０負担ということで、国からも示されております。検討中ですので、今の利用者負担というふうなご意見も踏まえまして、区としても改めて研究してまいります。どうしても中長期的に年度間の均衡を図りながら事業を計画的にやっていくという関係で、どうしても財政運営上必須なものだと考えているところです。","id":"exchange-085"},{"speaker":"西本委員","kind":"質問・要望","question":"保育料について、最後、これ、全体的にいろいろ、制度変更もありますので、考えてほしいと求めました。子育て支援という意味からいうと、公平性というところを考えて、補助金等々のあり方についても考察お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"７０ページの財調交付金についてお伺いしたいと思います。８億円用意したけれども、１件もなかったというお話ありましたけれども、そのことについてお伺いをまずしたいと思います。","respondent":"本城企画財政課長","answer":"財政調整交付金の基本的な性格ですが、個別の補助金の場合のように、特定財源として来るわけではありません。あるいは収入額を見込んでいくということなので、それを積み上げていくという、そのような関係です。","id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そこら辺の確認と、そこの不用額が今回６６億円ということですけれども、そのことについての確認も一つお願いしたいと思います。あわせて、次の質問ですけれども、平成２４年度の基準財政需要額の変更の特徴についてはどういう特徴があるかについてお伺いしたいと思います。","respondent":"本城企画財政課長","answer":"年度年度、たくさんの決算全般について見直しを行いまして、算定をし直すという作業をプロセスとしてやっているところです。トータルとしての標準的な経費について増減が出てきているという、そういう総体の中での関係だということでご理解いただければと思います。","id":"exchange-088"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとも、丸々財調算定されるものなのか、そこら辺のところがわかったら教えてほしいと求めました。新規算定で予防接種と緊急輸送道路のところが入ったということは確認させていただいてよろしいか尋ねました。","respondent":"本城企画財政課長","answer":"緊急輸送道路についても、それぞれかかった実額を反映させているという関係です。それで、実額を基準にして、その４分の３を財調の中で算定するという形です。","id":"exchange-089"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ということは、４分の３ということですが、財調の中に組まれたということで考えていいのかということを１点お聞かせください。平成２４年度がどうかということでお聞かせいただきたいのですが、実際の区の職員数が何人なのかということをお聞かせほしいと求めました。","respondent":"堀越人事課長","answer":"平成２４年度の区の財調人数につきましては、２,６８７名です。区の職員数につきましては、２,５９５名ですので、あい差が９２下回っているという、そういう状況です。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これがこんなにあい差が広がったというのはどういう理由なのかわかったら教えていただきたいのと、そこのところの確認をお願いしたいと思います。そして平成２５年にはそこの一部が具体化されて、また、そこら辺がどう財調が誘導していくのかというあたりをお聞かせほしいと求めました。","respondent":"本城企画財政課長、堀越人事課長","answer":"基本的に財調が誘導するというような位置づけではありませんで、計画的にできるような形で見込んでいくという、そのような位置づけの中です。ただ一方、人件費の見合いの形できちんと委託に出したものはきちんと見込んでいくという… 繰り返しの答弁になりますけれども、今、企画財政課長が説明したとおりです。平成２２年度におきましては、そういった中で経費算定において見直しを図ったということで、数字について動いているというふうに理解しています。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはりどう少なくしていくかという、この９２人というのは、財調で余る部分に入ってくるだろうと思います。そこの５％の特別交付金、品川区では１７億円ですけれども、そのことについても説明を求めました。","respondent":"本城企画財政課長","answer":"都市計画交付金との関係ですが、平成２４年度に都市計画交付金の４年間の関係の財調算定幾らあるかということで、平成２４年度は３５億円余です。災害等々、特別な事情に対応しての交付金ということなので、再開発については基本的にその中に含まれているものではございません。","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"４年間で７５％出していく、そのトータルが３５億円という、平成２４年度は３５億円ということですが、この具体的な開発と、それが幾らかというふうなところがわかったら教えていただけたらと思います。","respondent":"本城企画財政課長","answer":"財調の細部の内訳ということで、今手元にはあるわけではございませんが、都市計画交付金の関係で、トータルとして財調算定先というのが平成２４年度分では３５億円余ということで、トータルの数ということでご理解いただきたいと思います。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"再開発のある自治体とない自治体というところがあると思いますけれども、そこら辺のところの財調の公平性という点についてはどう考えられるかについてもお聞かせほしいと求めました。","respondent":"本城企画財政課長","answer":"再開発も含めて、その時々の事情を反映して、それぞれの需要に見合った財調算定になっていると考えています。","id":"exchange-094"},{"speaker":"若林委員","kind":"質問","question":"これは例年こういう傾向みたいですけれども、調定額が約３倍ぐらいですかね、１５億円超というふうにはね上がっております。時間があれば、緊急輸送道路についても触れたいと思いますが、以上３点、お願いいたします。","respondent":"久保田会計管理者、高森税務課長、山崎ものづくり・経営支援課長","answer":"今回４月の場合には、やはりこの４月だけで見ると、その中から支払って十分にこの運用をしているという状況です。… ２７ページですね、収入済額、これは前年度の滞納繰越分の収入未済額と前年度の現年課税分の収入未済額が翌年度の調定額というふうな形で入ってくる。… 昭和４７年から、当時中小企業の資金繰りの支援策としまして、区が直接債務保証というような制度ではございません。","id":"exchange-095"},{"speaker":"若林委員","kind":"質問・要望","question":"教えていただきたいのと、どういうお財布の状況なのかというのを、ここをちょっと確認をしておきたいと思います。年度末の一番、１２カ月の中で一番大きな収入が入るというのはどういうことになっているのかということについてもお聞きをしたいと思います。","respondent":"久保田会計管理者","answer":"預金にしておくとか、大体そういうことで、いつでも使えるように持っているのが歳計現金というふうに考えてもらって結構かと思います。","id":"exchange-096"},{"speaker":"原委員","kind":"質問","question":"私は成果報告書のほうの７８ページ、一般質問のときにも質問させていただいたのですけれども、報告書の７８ページですね。歳入の観点から、というのは中長期的な見方にかかわってくることの質問をできればしたいと思いますので、契約上からご説明をもらえればと思います。","respondent":"荒井広報広聴課長、平澤経理課長、本城企画財政課長、永尾高齢者福祉課長、山崎ものづくり・経営支援課長","answer":"１件当たり３００円の手数料と、それからコピー代といたしまして、１枚当たり１０円というもので計算させていただいているところです。… 使用料関係についてお答えいたします。行政財産使用許可につきましては、使用料の計算方法が使用料条例の中で決まってございまして… 不用品の売払収入の関係ですが、いろいろなところにまたがっております。学務の関係ではピアノを売り払ったり、そのような諸々の収入の総計です。","id":"exchange-097"},{"speaker":"原委員","kind":"質問・要望","question":"１６万２９０円という、具体的にお教えいただきたいということですけれども、その辺までわかりますでしょうか。ちょっと質問の内容、法務の契約のご担当のほうがよろしいかもしれないので、その辺をお答えほしいと求めました。","respondent":"荒井広報広聴課長、本城企画財政課長、山崎ものづくり・経営支援課長","answer":"情報公開についての考え方ですが、そういった方たちの請求に基づいて、個人情報の保護を図りながら公開していくという考え方でやっているものです。… 先ほどの不用品の売り払いの関係ですが、一番額として大きいのが、ピアノを売り払った１２万５,０００円です。ナンバープレートについては１万６,０００… そうしたことで、貸付金もその運営を支援するための一つですし、また、区としまして、団体あてに補助金なども交付しているというようなことです。","id":"exchange-098"},{"speaker":"原委員","kind":"質問","question":"、全体的には、これで。本日は歳入でしたので、明日続けて関連の質問をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"あべ委員","kind":"質問","question":"保育園保育料、あるいは住宅使用料に関連して、婚姻歴のないひとり親家庭の寡婦控除のみなし適用ということでお伺いをしたいと思います。余裕があれば臨海斎場までお伺いできればと思います。","respondent":"工藤総務課長、多並公園課長","answer":"私のほうからは、品川区の平和基金につきましてのお尋ねにお答えいたします。基金の額が２億円ですけれども、利子が生み出されております６０万円、私どもの平和事業の中で充当されているものです。 私からは品川区地球環境基金についてお答えいたします。基金の額としましては３０億円で、その運用益というところで、各事業に活用していく形で行っているものです。","id":"exchange-100"},{"speaker":"あべ委員","kind":"質問","question":"地球環境についても、あるいは事業の数というものにどうも関連性がどの程度見られるのか、増えたからといって新たな事業が始まるわけでもない。その目的に対してこのお金が使われているというふうに言えるのか、その辺の考え方というのをもう少し理解できるように教えてほしいと求めました。","respondent":"本城企画財政課長","answer":"今お話にもございましたように、その中で一定の基金の中で充当すべき事業もある程度安定して運営していかなくてはいけないという一方にあります。その年度に必要な、全体として基金を一番の基本的な元手として事業も計画的に運営しているという、そのような形です。","id":"exchange-101"},{"speaker":"あべ委員","kind":"質問・要望","question":"今年の３月の予算特別委員会の中で、ひとり親家庭、みなし適用を品川区としてもぜひ検討していただきたいということを質問でさせていただきました。品川区としても、品川区としてもまた新たに一つギアをアップしてご検討いただきたいと思うのですが、区としてのお考えはいかがか尋ねました。","respondent":"本城企画財政課長","answer":"今委員ご指摘がございました最高裁判所での裁判とか、その他の各自治体等の動向については、当然私どものほうとしても把握しています。そのような取り扱いについてこれから広まってくる傾向等、注意深く見きわめながら、引き続き研究してまいりたいと考えているところです。","id":"exchange-102"},{"speaker":"あべ委員","kind":"質問・要望","question":"これが結果的に歴史的に今後振り返って、あれは不平等な状態だったねという状態がないように、ぜひ変えるべきところは変えていただきたいと。こういったことを絶対に繰り返さないためにも、ぜひできることはやっていくという姿勢で導入を強く望みますが、区としてのお考えを説明を求めました。","respondent":"井浦戸籍住民課長","answer":"そのような状況に対して、地方公共団体としての対策としましては、考えられる方策といいますか、全国的にも３通りのものがあります。効果的なものはないかということで、先駆的な自治体を研究しまして、あわせて国の立法の動向等も見ていきたいと考えています。","id":"exchange-103"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひこの２０年のときを機に、品川区としてもあと一歩踏み出してほしいと求めました。もし理事者の方のこの２０年に向けた思い、そして、その中での品川区のさまざまな制度の見直しということ、お考えがあれば説明を求めました。","respondent":"井浦戸籍住民課長","answer":"品川区としましても、戸籍の適正執行ということで汗を流しているわけです。これも大事ですので、さまざまなお立場の方の権利を慎重に見ていきながら、委員ご指摘の趣旨を踏まえて研究してまいりたいと考えています。","id":"exchange-104"},{"speaker":"あべ委員","kind":"質問","question":"私、伺ったつもりだったのですけれども、戸籍のお話だけのご答弁だったのは少々品川区の姿勢として寂しいものと捉えております。臨海斎場については明日お伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"松澤委員","kind":"質問","question":"１４款都支出金５目土木費補助金、９０、９１ページに関連してお聞きをしたいと思います。この公園について区にはどのような声が届いているのか、そこをちょっとお聞きしたいと思います。","respondent":"多並公園課長","answer":"文庫の森につきましては、オープンしまして、皆様から、まず開放的な公園であるということと、なかなか広々した公園であるということで、非常にご好評いただいているところです。","id":"exchange-106"},{"speaker":"松澤委員","kind":"質問","question":"あるいは従前居住者用、どうしても品川区に住みたいという方たちのための住まいとして残す。この辺についてどう思っているのかという考えを聞きたいのと、当然収用されるわけですから、その点についてお聞きしたいと思います。","respondent":"多並公園課長","answer":"最近の例で申しますと、２６号線がかかったところで、いわゆるたこ公園と親しまれていた公園が同じような形でかかったところがございました。２９号線につきましても、どのような形でそこの状況を踏まえながら協議してまいると、そのように考えてあります。","id":"exchange-107"},{"speaker":"松澤委員","kind":"質問・要望","question":"今お話伺いましたように、公園として新たに整備をする可能性があるのならば、その辺もしっかりと念頭に入れてほしいと求めました。もとの町会長が地主だったものですから、売っていただくという話になっておりましたけれども、いまだに整地されていないのですね。","respondent":"品川木密整備担当課長","answer":"その中で、非常にこの用地、広い用地ですので、もう少し一体的な防災まちづくりができないかということで、少し検討をしている状況です。まだ現在は一体まちづくりのほうを検討している段階です。","id":"exchange-108"},{"speaker":"松澤委員","kind":"質問","question":"７７ページですけれども、福祉関係団体等に対する支援に配慮しつつも、行政財産の活用による新たな財源の確保にも努められたい。やはりは何らかの手を打たなければいけないと思うのですが、これについての見解、今後どのようにしようとしているかについてお伺いしたいと思います。","respondent":"平澤経理課長","answer":"私どもといたしましては、まず初めに、貸し付けの実態を改めて見直すとともに、現状がどんな状況にあるのかというのを調査をしています。それを受けまして、今後の方針について考えていくというところの段階です。","id":"exchange-109"},{"speaker":"松澤委員","kind":"質問・要望","question":"では今まで得ていたお金によって福祉団体が活動してきた実績もあるわけですから、その間にはいろいろ事業の見直し等々があると思います。その決意を聞きたいと思います。","respondent":"平澤経理課長","answer":"自動販売機の収入益につきましては、活動団体の収益の重要な部分であるということは認識しています。委員ご指摘のとおり、そういった関係も含めまして、今後慎重に検討していきたいと考えているところです。","id":"exchange-110"},{"speaker":"松澤委員","kind":"意見","question":"そこの雑入のところ、３ページですね。４１万１,２５５円、法定外公共物不法占拠に伴う不当利得というふうに書かれておりますけれども、この内容についてお知らせくださいとの意見を述べました。","respondent":"安井土木管理課長","answer":"本件の法定外公共物の不法占拠ですが、上神明児童遊園におきまして、昭和２０年から旧公共溝渠を不法に占拠されていた方がおりました。平成２３年の８月に退去していただいたのですけれども、こちらのほうを不納欠損とさせていただいたという経緯です。","id":"exchange-111"},{"speaker":"松澤委員","kind":"質問","question":"何ていうのですかね、これも、このケースによると不当利得ということになるのでしょうか。この辺ちょっとお聞きしたいと思います。","respondent":"安井土木管理課長","answer":"それを１件１件調査しながら、実際囲い込んでいらっしゃる方と個別にお話し合いをさせていただきながら、こういったものを解消していく。公共溝渠として廃滅しているものであれば、売却、買い上げていただくというようなことを進めていくというような方針です。","id":"exchange-112"},{"speaker":"松澤委員","kind":"質問・要望","question":"公共溝渠はできるだけ早く区民に簡単に売却するような方向にしていただいて、このような不法占拠ということがないような形にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"浅野委員","kind":"質問","question":"過去にこのようなことがあったのかどうかということと、懸念事項ですか、これは１点教えてほしいと求めました。アスベストについては、１０％程度の決算額になっていますけれども、それぞれの事業の推進結果、これについて教えてほしいと求めました。","respondent":"野呂瀬環境課長","answer":"歳入の関連、助成です。補助金は１０分の１０ですけれども、予算に対して申請がそれだけなかったということで、このぐらいの結果になっているというものです。","id":"exchange-114"},{"speaker":"浅野委員","kind":"質問・要望","question":"事項別明細書に出ていた２項目でありますけれども、これは３８万円ですか、これが結果として０円になっているということ。そして、もう一つ、クリーンエネルギー促進補助金、これが６万９,０００円ですか、これが０円になっているということ。","respondent":"平澤経理課長、野呂瀬環境課長","answer":"平成２４年度で電気自動車を購入いたしました。７月に入りましてそれはいただいたというところでございまして、平成２４年度の決算では出てこないです。 当初予算で組んだときには３８万円の予算を組んだところですけれども、結果的にはゼロだったという、そういう結果です。","id":"exchange-115"},{"speaker":"浅野委員","kind":"質問","question":"それぞれご答弁ありがとうあります。こちらの３８万円については、当初３８万円で計画していたけれども、この件を教えてほしいと求めました。","respondent":"野呂瀬環境課長","answer":"その時点では、地球温暖化を推進しているものでつくという方向で行っているというお話でした。当初予算に見込んだところですけれども、急遽その補助金がつかなくなったと、こういう状況です。","id":"exchange-116"},{"speaker":"浅野委員","kind":"確認","question":"前に確認していたけれどもだめになったというのは、都との調整、今後しっかりといい意味で強気で臨んでほしいと求めました。それと、歳入の足し方というのでしょうか、そういうものは整合がとれているのかどうかをお伺いします。","respondent":"齋藤庶務課長","answer":"最終補正で出させていただきましたのは、日本スポーツ振興センターから採択をいただきまして、その実績払いということになります。工事の５分の４、対象工事の５分の４を補助するということで交付金を頂戴いたしますので、整合はとれているです。","id":"exchange-117"},{"speaker":"浅野委員","kind":"質問","question":"平成２５年度、平成２５年度も同じように実績払いになるかと思いますけれども、平成２５年度も同じように年度末になるのかどうかを説明を求めました。","respondent":"齋藤庶務課長","answer":"平成２５年度分につきましては、事情の変更がございまして、歳入は見込めない状況になってあります。天然芝整備の自治体を優先する、これまで実績があったところは対象外にするですので、この部分についての歳入は見込めない状況となっています。","id":"exchange-118"},{"speaker":"浅野委員","kind":"意見","question":"しっかりとオリンピック・パラリンピックに向けて、児童・生徒にとっても楽しめる、また活躍できる場を与えてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-119"},{"speaker":"南委員","kind":"質問","question":"６７ページの特別区税、とりわけ特別区民税について伺います。この税金の収納事務を担当されている課長として、区民生活を今の状況をどのように見ておられるか、その辺のご認識をまず伺いたいと思います。","respondent":"高森税務課長","answer":"区民生活の状況についての認識ですけれども、区民の人口等々によりまして、さまざまな影響を受ける状況になってあります。平成２３年度は横ばい、そして平成２４年度は、先ほど申し上げましたように、調定額としては５億円ほど向上したという状況だという認識です。","id":"exchange-120"},{"speaker":"南委員","kind":"質問・要望","question":"そのあたりをちょっと伺いたいと考えています。改めて先ほどの見解、どういうふうに評価というか、その点についてももう少し踏み込んだ見解を示していただきたいと考えています。","respondent":"高森税務課長","answer":"平成２３年度は５２.８％。そして平成２４年度は５１.９％ということで、課税標準額２００万円以下の方ということで見れば、そういうふうな数字が見えてくる状況です。","id":"exchange-121"},{"speaker":"南委員","kind":"質問","question":"収入率として１０３.３％ですか、１３億円を増額させている、ここをどういうふうに努力しているのかということについてちょっとお尋ねしたいと思います。","respondent":"高森税務課長","answer":"１０３％ということで今お話がありました。予算額から対比して１０３％ということで、例えば５年間のいろいろな収入状況、必ずしも予算の上を行くというのは変な状況ではないです。","id":"exchange-122"},{"speaker":"南委員","kind":"意見","question":"２００万円以下がずっと増えてきている、背景はどういうところにあるのかということを聞いているので、その辺についてもう一度お尋ねしたいとの意見を述べました。","respondent":"高森税務課長","answer":"そういうふうな場合においても、分割納付をしていただくなり、さまざまな形で努力をいただいているところです。なお、これに伴う延滞金等々が発生した場合については、それはまた個々に対応させていただいているのが実情です。","id":"exchange-123"},{"speaker":"南委員","kind":"質問・要望","question":"その辺についてもお聞かせいただきたいのと、来年４月から増税になるようですけれども、ちょっとそのことを改めて先に言っておきたいと思います。ぜひ答弁お願いします。","respondent":"高森税務課長","answer":"本当に申しわけないことですけれども、納税義務者数から見ると、平成２３年度と平成２４年度を比較いたしますと、平均の税額は向上しています。","id":"exchange-124"},{"speaker":"須貝委員","kind":"質問","question":"私、歳入全般について企画部にお伺いしたいと思います。これは区民から見ても大変不自然に感じるのですが、これについてちょっとご見解を説明を求めました。","respondent":"本城企画財政課長","answer":"最終的な見込みの段階で、必要な分だけきちんと財源手当てをして、結果として財政運営全体の中でおおむね３０億円程度の黒字幅の財政運営状況が続いているという形で考えております。","id":"exchange-125"},{"speaker":"須貝委員","kind":"意見","question":"これだと３０億円先に黒字を出しといて、それは区長の腕なのかもしれないけれども、ちょっとおかしいと思うのですね。その点についてもう１回ご見解を説明を求めました。","respondent":"本城企画財政課長","answer":"基本は単年度、予算を財政運営している中で、行政としては単年度で収支の均衡を図るということが基本であると思います。あるいは、そのバランスの中で、財政運営の結果として今のようなおおむね３０億円レベルの黒字が続いているという状況だと考えているところです。","id":"exchange-126"},{"speaker":"須貝委員","kind":"質問","question":"その中で、工事の工期が理由で、工事、どうしても延ばさなくてはいけない理由があるのもあるのですが、それは大体どれぐらいの金額があったのか。それから、事業として予算を立てたのに、実際使われなかった、本当の不用額だと思うのですが、それは総額幾らあったのか、わかれば説明を求めました。","respondent":"本城企画財政課長","answer":"年度を締めた段階での全体の不用額は６６億円余です。","id":"exchange-127"},{"speaker":"須貝委員","kind":"意見","question":"それが一遍に８億円か９億円出していたのが、全く使われなかったとか、相当の額しか、ほんのわずかしか使われなかった。これは私はちょっと違うと思うのですが、その点についてちょっとご見解を説明を求めました。","respondent":"本城企画財政課長","answer":"あるいは生活保護についてですとか、経済の見通しが最終的に最終補正立てる段階ではなかなか最終的な事業規模が見込み切れないところがあります。そういう状況も見込めるということの可能性がありますので、あるいは経済状況の中で、最終的になかなか見込みづらいもの。","id":"exchange-128"},{"speaker":"須貝委員","kind":"意見","question":"でも、これも区としては、毎年少しずつ増えてきていると、これは数字として、何も今年始めたわけではないのでね、平成２４年度。いや、きちんと見込みを立てていたのかと逆に言わざるを得なくなるのですが、その点についてちょっともう一度ご見解を説明を求めました。","respondent":"本城企画財政課長","answer":"今、お話伺いましたように、当然事業の予算立てた段階、あるいは最終補正の段階等、節目節目があります。可能性がなかなか見込めないものとか、なかなか見込みづらい幾つかの要因によって最終的に残ってしまうものがあったのが不用額ということで。","id":"exchange-129"},{"speaker":"須貝委員","kind":"質問・要望","question":"入札前に業者間で談合等の問題を起こした場合は、その業者にペナルティーとして何らかの制裁を課すと思いますが、どのような制裁があるのでしょうか。二、三でいいですから、簡潔に説明を求めました。","respondent":"平澤経理課長","answer":"談合という話です。一定の期間の指名停止、または回避と言ってはあれですけれども、そういったことをするような段取りになります。","id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"もう一つお伺いしたいのですが、入札前に暴力的構成員などの反社会的勢力にかかわった場合に、これはどのような制裁が課せられるのか。これもちょっと１例、２例でもいいのですが、説明を求めました。","respondent":"平澤経理課長","answer":"反社会的ということになりますと、こちらのほうは要綱がございまして、そういった事情がある場合は、契約解除も含んだ厳しい措置を行うように要綱上は定めてあります。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"２年ちょっと、約３年間にわたって契約を、放置していたと。事実上放置していたということですが、このように報道されているのですが、これに対して品川区としてはどのような態度をとるのか尋ねました。","respondent":"久保田会計管理者","answer":"これは当然ながらそちらのほうとも協議しながら対応していかなくてはならないということで、２３区の会計管理者の会が、あるいは。改めてこの辺については、みずほ銀行のほうの考え方がはっきりした上で、こちらにも説明に来てほしいということで申し入れはしています。","id":"exchange-132"},{"speaker":"須貝委員","kind":"意見","question":"というのではなくて、やはり素早い行動、そしてどうするのか。ちょっと対応として、自治体の対応として何か違うふうに思えるのですが、その辺についてちょっともう一度ご見解を説明を求めました。","respondent":"久保田会計管理者","answer":"確かに今経理課長が説明したとおりではありますけれども、これは、慎重な対応が必要だと考えているところです。履行場所等によって、何が一番今必要かということも含めて、やはり私どもとしては慎重に見きわめながら対応していきたいと考えております。","id":"exchange-133"},{"speaker":"須貝委員","kind":"意見","question":"何よりもまずいのが、約３年間にわたって、金融庁が指摘したにもかかわらず放置していた。だから、そこはちょっと私は違うと思いますが、もう一度だけご見解を説明を求めました。","respondent":"久保田会計管理者","answer":"あるいは、それに対してみずほがどう考えるか、全く明らかになっていないわけです。それをしっかり聞きながら、区として対応することが一番やはり必要だろうと、大切だろうと考えております。","id":"exchange-134"},{"speaker":"須貝委員","kind":"質問・要望","question":"何らかの区としての、自治体としての責任ある対応をとって、方針をとってほしいと求めました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"いながわ委員","kind":"質問","question":"都支出金で、９０ページから９１ページにかけての土木費補助金についてお伺いします。補助基本額というのが４つ出ていますが、予算額では恐らくもう１個あって、執行されていないのかどうなのかというところを説明を求めました。","respondent":"本城企画財政課長","answer":"都市計画交付金の増になった理由ですが、当初よりも補助金の交付率が変更になった関係で、その分多くなっているものです。当初交付率が２０％だったものが３４.６％ということで、交付率が上がったものに連動するものです。","id":"exchange-136"},{"speaker":"いながわ委員","kind":"質問・要望","question":"決算に出ているわけですから、本来やるべき事業が、ちょっと思ってしまったのですね。２年前からずっとやっていくわけですから、そういうのをしっかり計画立ててやってほしいと求めましたが、いかがでしょう。","respondent":"品川木密整備担当課長","answer":"全く見込みがないものを予算計上しているということはございませんので、ある程度の見込みがあるもの、これについては予算計上しております。","id":"exchange-137"},{"speaker":"いながわ委員","kind":"質問・要望","question":"もう既に都市計画道路の２９号線も着々といろいろ説明会も開かれているわけですから、そういう要望です。例えば目的外利用というのですか、使用というのですかね、いかがお考えか尋ねました。","respondent":"工藤総務課長、荒井広報広聴課長","answer":"区のほうでもそのような形で最大限ＰＲを区内全体に図っていきたいと考えております。私ども区としても、いろいろとやれることはやっていきたいというスタンスです。 区として大井競馬場への応援策といたしましては、広報誌のほうで大井競馬場を扱ったりとか、あるいはケーブルテレビの番組等で扱っているところです。","id":"exchange-138"},{"speaker":"たけうち委員","kind":"質問","question":"私は１００ページの雑入の中の雑入、それから、７８ページの戸籍証明手数料、時間があればしたいと思います。この中に自動販売機の設置の使用料というのですかね、設置者はどこになっているか、説明を求めました。","respondent":"多並公園課長、平澤経理課長","answer":"自動販売機です。１０の公園の中に２０カ所自動販売機を設置し、４５０万６,０１６円ということで、利益配分という形で納付をされているものです。 私のほうから行政財産使用許可に基づく自動販売機の設置についてお答え申し上げます。使用料につきましては、使用料規則に基づくものと、あと、福祉団体に基づくものは免除という形になっているところです。","id":"exchange-139"},{"speaker":"たけうち委員","kind":"質問","question":"健康センターが６台、歳入として７万６,０００円というのが報告があったのですけれども、これはわかりますか。それから、公園のほうがあったので、公園のほうは、４５０万円というのは、これは入札か尋ねました。","respondent":"多並公園課長、江部健康課長","answer":"公園内の自動販売機につきましては、平成２４年に簡易型プロポーザルという形で公募をし、４社の事業者の中から、その中で入札をかけて今のような形で決まったものです。 品川健康センターにあります自動販売機の中で、５台分は住友エスフォルタが設置しておりますが、これは指定管理の契約の中に含まれたものです。","id":"exchange-140"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今まで多分どういう形でやっていたのかわからないのですけれども、２１万円の歳入だったのが、入札をやったら１,６００万円になったと。明日やれるかどうかも含めてちょっとお聞きしたいと思いますけれども、どういうことでしょうか、説明を求めました。","respondent":"井浦戸籍住民課長","answer":"法務省を中心に検討した中で、登録型本人通知制度についても学識経験者の中で検討されまして、その中で見送られたという経緯もございまして。それから、こういう立場のお方は、区としてはきっちりと制度化されているということで見ていかなければいけないと考えているところです。","id":"exchange-141"},{"speaker":"たけうち委員","kind":"質問","question":"あれですかね、不正かどうかわからないけれども、事前に登録している方のほうにとられましたよという通知をされますよね。そのときは、そういう仕組みになっているのではないかと思うのですが、その辺はどう理解されていますか。","respondent":"井浦戸籍住民課長","answer":"この第三者による戸籍の請求、特に問題になっているのが弁護士等による職務上請求です。もともと職務上請求については、第三者の氏名、依頼人の氏名を明らかにしないで請求することができるというふうに制度づけられているものです。","id":"exchange-142"},{"speaker":"渡辺委員","kind":"質問","question":"午前中のつる委員の質問にもありましたが、在外の方をどう把握されているかを１点伺いたいのと、大きく明確には打てるものではないと思います。この項目ですか、およそどういうふうに、寄附を区民に案内するという点で伺えればと思います。","respondent":"寺嶋協働・国際担当課長","answer":"そもそも地域振興の寄附金につきましては、協働事業の観点から設置した寄附金でございまして、こういう形でＰＲしています。法定上では細かな１つずつの事業についてのご紹介というか、この事業に寄附していただきたいと、そういう形でのご案内にはなっていないのが現状です。","id":"exchange-143"},{"speaker":"渡辺委員","kind":"質問","question":"日本の寄附事情というのですか、金額でどうこうではないと思うので、次に日本赤十字社。そんな点も踏まえて、品川区の寄附に対する今のスタンスですとか、そういったものを伺えればと思います。","respondent":"寺嶋協働・国際担当課長","answer":"金額の予算上の設定につきましては、金融機関で約３００万円程度寄附金がいただけるということを前提にＰＲ等に努めているというのが実態です。","id":"exchange-144"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それを１点伺いたいのと、もう１個、ファンドレイザーの活用となっているのです。寄附を迎えに行くというのは嫌らしいという見解もあるかとは思いますが、この２点、見解をお知らせください。","respondent":"寺嶋協働・国際担当課長","answer":"１点目の目的を限定してというお話につきましては、そういったことも踏まえまして、今後の検討課題とさせていただきたいと思います。現在のところ、そういった形での検討はまだしていないのですけれども、こちらのほうもあわせて十分に研究していきたいと思います。","id":"exchange-145"},{"speaker":"渡辺委員","kind":"質問","question":"では、寄附の話は以上で、施設のところで、調理室がある施設、公営施設という点で伺えればと思います。八潮地域センターというので、区でそういう教室だとか料理の行事をしたいといったときにはどういうところがあるのか、まずお知らせください。","respondent":"安藤文化スポーツ振興課長、久保田地域活動課長","answer":"それと、あとは、今委員ご指摘のとおり、きゅりあんにも調理講習室があります。文化スポーツ振興課主管ですと、その２つです。 地域センターの集会所の関係でいきますと、八潮地域センターの中に料理講習室が、約６４m2ほどの広さのものが１つあります。","id":"exchange-146"},{"speaker":"渡辺委員","kind":"質問・要望","question":"わかりやすく言うと、電子レンジだとか炊飯器が、６台のテーブルがあって一遍に使うとどうしても対応できないと。その辺について、今後の道筋だとか、意識をしていただきたいという思いがあったので、ご答弁をほしいと求めました。","respondent":"久保田地域活動課長、安藤文化スポーツ振興課長","answer":"そういう備品等のことに関しましては、利用団体のほうから要望いただいていますので、老朽化等に伴って順次見直しをしています。配線等の工事についても、各年度の予算のときに検討させていただいて… 私どものほうでも、利用者の団体の方と直接お会いしまして、要望等を聞きまして、そういう要求等を掘り出していったものがありますので、今後とも利用者の方々の意見を聞いて整備をしていきたいと思っています。","id":"exchange-147"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/571589?Template=document&Id=1372#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":117343,"voices":390}},{"id":"h25-20131003-4","meetingId":"h25-c-settlement","date":"2013年10月3日","dateIso":"2013-10-03","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を154件整理しています。","topics":[{"id":"topic-01","title":"◯伊藤委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２４年度品川区一般会計歳入歳出決算","agenda":"◯伊藤委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"それから１１１ページのオリンピック・パラリンピック東京招致気運醸成事業、それから１１４ページの歴史館経費についてお伺いします。２０１６年のオリンピック招致のときから今回の２０２０年のオリンピック招致に至るまで、担当の方の感想を説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"それから２０２０年にまた手を挙げてやっていくというところで、そういうところでまずは皆さんにそういう気運を醸成していったところです。商店街連合会、観光協会等とも連携をしまして、本当にまちぐるみで応援をしてきたです。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"ホッケーとビーチバレーと、７年後ということでありますが、今後のこういった競技との結びつきを強めていくということも大切かなと思います。ホッケーやビーチバレーも、いろいろと進めていっていただきたいと思うんですけれども、そういったことのお考えというのを説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"今後の私どものホッケーとビーチバレーの醸成のやり方ですけれども、今ちょうど区は、来年度予算に向けて施策等を考えているところであります。そんな中で、来年度以降、何ができるかということを、これから本当に精力的に考えていきたいと思っています。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に、１１４ページの歴史館の経費についてお伺いします。例えば分室をつくるとか、荏原のほうも品川の中でも荏原という地域もあるわけですから、そういったことも考えられるのかなと思います。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で歴史館の内部でもあらゆる資料を展示しまして、皆さんにご紹介させていただきたいというふうに考えています。品川の誇る歴史や文化などを全国的に情報発信できるように積極的にＰＲをしていきたいというふうに考えてあります。","id":"exchange-003"},{"speaker":"沢田委員","kind":"意見","question":"それから、今、それ以外のふだんの歴史館事業ということでやられている講演会の充実等ももっと図られたほうがいいんじゃないかなと思います。そのあたりを説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"ちょっと申し上げますと、浮世絵とかそういうものは６５２点もありますし、古文書、または民俗資料等たくさんあります。そんなような形で来館者の増員を図っているところです。","id":"exchange-004"},{"speaker":"沢田委員","kind":"意見","question":"使っていただける方がいる以上、やっぱり利用していただくという、その辺の明確な判断が必要なのかなと思います。その値段でも納得して利用していただけると思いますので、そういったところの今後の考え方というか、簡単にお聞かせほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"８０年たって老朽化が進んで、先日申し上げたように、いろいろな場所で改修が出てきます。その保存をして区民の皆さんにも公開をしていきたいというふうに考えていますので、そこら辺を今年度、区として十分検討していきたいと思っています。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に、外国人学校の保護者補助金についてお伺いします。予算特別委員会のときにお伺いさせていただいたんですけれども、改めてもう一度確認させていただきたいんですけれども、現状を説明を求めました。","respondent":"工藤総務課長","answer":"現状ですけれども、今、朝鮮学校のほうに５名、中華学校のほうに７名、韓国学校のほうに３名、合計１５名通ってあります。この方々のいわゆる保護者に補助金という形で月額７,０００円を補助という形でお支払いしています。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問・要望","question":"そして、７,０００円ということで、そういったところはどうなっているのかということを伺わせてほしいと求めました。そういったところ、この辺のお考えというのは、どういうふうになってこの施策がなされているのか説明を求めました。","respondent":"工藤総務課長","answer":"品川区のほうでも昭和５６年から朝鮮学校に対しての助成制度を創設して現在に至っているところです。この時点で都内の２３区の多くの区で韓国学校、中華学校まで拡大して助成を実施していた、品川区としても制度の拡大を図ったものです。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"外国人学校ということでこの補助金制度はあるわけですから、それは所得制限を設けてということであれば。ちょっと時間が短くなってしまったんですけれども、１０５ページの区内企業との連携促進ということでお伺いさせてほしいと求めました。","respondent":"工藤総務課長","answer":"決算、不用額が１４０万円余出たという、その件です。私ども、活動レポート作成という部分の一般需要費を組んでおりましたけれども、いわゆる契約落差ということで不用が出たというものが主なものです。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問・要望","question":"一般質問もさせていただきましたけれども、やはりこれから区内企業との連携というのは大変大切だと思います。防災対策等で結ばれていると思いますけれども、そういったことをぜひとも進めていくために、予算をちゃんと充実して執行してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"つる委員","kind":"提案","question":"人権啓発の映画「尊厳への道－人権教育の力」を職員研修等で有効活用する提案をさせていただいて、私も実はウエブサイトを見させていただきました。あわせて、今年、人権尊重都市品川宣言制定２０周年記念事業が行われていると思いますが、その中での活用も改めて提案をしますが、いかがか尋ねました。","respondent":"提坂人権啓発課長","answer":"職員研修のほか、２０周年記念ということも踏まえまして、人権のひろばの中の映画で活用させていただきたいということを考えております。ただ、コスト面とかも総合的に勘案させていただいて検討させていただきたいと考えています。","id":"exchange-010"},{"speaker":"つる委員","kind":"提案","question":"屋上の活用についてご提案がありまして、ちょうど今年の１月に息子が１歳になったものですから、屋上の庭園を見に行こうと思って連れていったんです。そういう話題が出たものですから、これは経理課のほうでされているというふうに伺ったんですが、この辺を説明を求めました。","respondent":"平澤経理課長","answer":"それともう１点が、やはり直にお客様の声ということで、これはいただいているところです。こういった取り組みが非常に喜ばしいということや、ちょっと雑草が繁っているのでもう少しどうにかしなさいといったご意見を頂戴することもあります。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"投票率向上、こういう観点でお尋ねをしたいと思います。この実施について、品川区選挙管理委員会としての見解、これを説明を求めました。","respondent":"諸岡選挙管理委員会事務局長","answer":"それから、期日前投票については、港区もそうだったんですが、これは記号式投票はできませんでした。いろいろ長所、欠点ありますので、私どもとしても、その港区の結果を検証して、今後も検討していきたいと思っています。","id":"exchange-012"},{"speaker":"つる委員","kind":"提案","question":"唯一５０％を切っていたかと思うんですが、より身近に感じてもらうという情報提供をしたらどうかなということを提案させてほしいと求めました。もう一つが、この定例会でも提案がありましたけれども、模擬選挙の実施の拡大、これもお願いしたいなと思いますとの意見を述べました。","respondent":"諸岡選挙管理委員会事務局長","answer":"明るい選挙推進協議会の皆さんとともに取り組んできているところでございまして、模擬選挙も延山小学校で昨年実施されました。あるいはポスターコンクール、学校でも積極的に取り組んでいただいていますので、これから充実して進めていきたいというふうに思っているところです。","id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"それぞれ提案させていただいたことを含めて、ぜひ啓発を強めてほしいと求めました。ちなみに、２０代前半の投票率が前回比２.７ポイント増加するという成果があったようでありますので、参考にしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"向委員","kind":"質問・要望","question":"戸籍事務についてなんですけれども、婚外子の出生届について、ちょっと取り扱いを伺っておきたいと思います。品川区として、今後の対応はどうなるのか教えてほしいと求めました。","respondent":"安藤文化スポーツ振興課長、井浦戸籍住民課長","answer":"では、私のほうから、まず成果報告書１１４ページの歴史館の施設改修経費についてご説明します。そしてまた、星空と音楽の夕べということで… お尋ねの出生届の非嫡出子、嫡出子の欄の取り扱いですが、最高裁の中でも、違憲とまでは言えないという判決です。","id":"exchange-015"},{"speaker":"向委員","kind":"質問","question":"基本的に共通な様式はあると思うんですけれども、明石市が削除した用紙というのは、独自に簡単につくれるものなのでしょうか。印刷作成とかは区のほうでやってくださいということで、こういった決算の戸籍事務の中にもお金は入っていると考えていいのか尋ねました。","respondent":"井浦戸籍住民課長","answer":"戸籍の届出用紙については、様式について標準的なものが定められておりますので、それぞれの実施機関の責任の範疇で印刷をして用意しています。","id":"exchange-016"},{"speaker":"向委員","kind":"質問","question":"せっかくなのでお尋ねしたいかなと思うんですけれども、控室の真下が戸籍住民課なので、出されている様子をよく目の当たりにすることもあります。区でもらおうと思えば３５０円で取れると思うんですが、これは品川区でも特別な受領書を発行していただけるということで考えてよろしいのか尋ねました。","respondent":"井浦戸籍住民課長","answer":"おっしゃるとおりでございまして、１通１,４００円頂戴するんですけれども、年間１００点弱ですが、申請をいただいております。","id":"exchange-017"},{"speaker":"向委員","kind":"質問","question":"海外などでは、本当に形はさまざまなんだなと思っています。目黒区役所のようにウエディングのそういったセレモニーをどこかでしてほしいというよりかは、今のところおありでしょうか、説明を求めました。","respondent":"井浦戸籍住民課長","answer":"婚姻届あるいは出生届、大変おめでたい人生にとっての局面であるということで受けとめてありますので、戸籍住民課だけではなく、庁内の関係課と相談しながら、適切な対応ができないか研究してまいりたいというふうに考えてあります。","id":"exchange-018"},{"speaker":"向委員","kind":"質問・要望","question":"五反田文化センターのプラネタリウムとかお尋ねしたんですけれども、きれいな施設、何かしら転用できるような施設が区内に幾つかあると思います。そういった使用については、今まで実績とか、今後そういう要望があれば利用できると考えてもよろしいか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"例えば歴史館の庭園で今質問されたような結婚披露宴だとか、そういうものは、今までの例にはございません。今後の展開として、また庭園を全国に紹介できるような、そういうものもあわせて情報発信ができるようなものを今後研究していきたいと思っています。","id":"exchange-019"},{"speaker":"向委員","kind":"質問","question":"２分ほどありますので、１１７ページ、消防団運営費について、ちょっとお尋ねをしたいことがあります。そういったときもあるんですが、これというのは、もう単年度ということで基本的に考えてよろしいのか尋ねました。","respondent":"鈴木防災課長","answer":"基本的に品川区のほうから消防団の運営のための補助金、それから装備品の補助金、２種類をお渡ししております。団の運営費のほうもそちらにお使いいただくことは可能と考えております。","id":"exchange-020"},{"speaker":"向委員","kind":"意見","question":"使い方については、各団のほうでということですね。ありがたく感じているという声を周囲でも聞いておりますので、引き続き、ご支援のほうをとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問","question":"そして１１７ページの集中豪雨等対策費、そして１１６ページの小・中学校消火ポンプ配備、時間がありましたらやりたいと思います。７４万７,２３５円ということで、ダウンした金額の理由は何かあるのかお聞きしたいのと、そして言語の種類をまず説明を求めました。","respondent":"荒井広報広聴課長","answer":"したがいまして、平成２３年度に発行いたしましたので、平成２４年度は発行を見合わせたという形になります。平成２４年７月に住基法の改正がありまして、外国人の方の登録等につきまして変更がありましたので、補完版といたしまして発行したところです。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"ところで、区内にお住みの方は無料というふうに私はお伺いしたんですけれども、これは違うものなんでしょうか。これをちょっとお伺いしたいです。","respondent":"荒井広報広聴課長","answer":"外国語版生活情報誌等の「等」の中身ですが、先ほど少し説明させていただきました追補版といいますか、補完版のものがここに含まれているところです。","id":"exchange-023"},{"speaker":"吉田委員","kind":"提案","question":"その中に地域における外国人にどのような情報提供が必要だと思うかという質問に、６８.２％、すごいパーセンテージが出ました。マナー等も説明して織り込んだらどうかなというのがありますが、私の提案なんですけれども、その辺をお伺いしたいと思いますとの意見を述べました。","respondent":"荒井広報広聴課長","answer":"それから同時に発行いたしております外国語版のマップにつきましては、順次、できるだけわかりやすい表記にしているところではあります。その中でも、年に１回は必ずごみ出しルールなどについてはご案内しています。","id":"exchange-024"},{"speaker":"吉田委員","kind":"提案","question":"防水板設置の助成についてお伺いしたいんですけれども、今、そういう建物がたくさん増えてまいりました。この２点、お伺いしますとの意見を述べました。","respondent":"鈴木防災課長、奥田河川下水道課長","answer":"この経費につきましては、台風や大雨のときに水防本部を設置いたしまして、そこで監視であったり、倒木等の対応をしたりするための経費です。平成２４年度につきましては… 委員からもご指摘ございましたように、平成１５年以降、建築確認を得て行います開発環境指導要綱の対象物ですとか、半地下の建物は除いております。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１１２ページ、１１１ページ、庁内のことでお伺いいたします。改めて、なぜ減免制度をつくらないのかお聞かせほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"さまざまな活動にご利用いただいてもらうというような観点から、総合的な文化施設という位置づけでつくってまいりました。そのような形でこのスクエア荏原も同じということで減免制度は設けてございません。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"地方自治法の第２４４条には、区民の利用だと思うんですが、供するための施設です。私はサービスの低下であって、あってはならないと思うんですが、この点はいかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"これは再三私のほうも皆さんにもご説明に参りましたけれども、各２３区の調査の上、いろいろなことをしてまいりました。そして、会議室につきましても、同じように２３区同じような場所、駅からの徒歩ということで考えてまいりました。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"料金が高いのは減免制度がないから高いと言っているんですね。なんで総合区民会館になると減免制度がないのか、その辺もあわせてなんですが、減免制度を阻むものは一体何なのかお聞かせほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"そして、文化の団体というのは区内に文化センターが５館あります。文化活動だけにとどまらないで、地域のさまざまな町会活動ならびに自治会活動も含めて、いろいろな活動にご利用いただくです。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"経営の面でも原因なんでしょうか。そこまでも踏み込んでお伺いしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"そして、利用率ですけれども、このところ非常に高くて、会議室等につきましては、この８月現在の段階で、１年間の予定のもう６４％を達成していると。本来ですと、この時点ですと４０％ぐらいですけれども、結構皆さんにご利用をしていただいているところです。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"高齢の難聴者の方から磁気ループを設置・普及してほしいと言われているんですが、多人数、会議などでの話が聞き取れないといったことを伺っています。五反田文化センター後の設置状況、設置の基本的な考え方を聞かせてほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"今の磁気ループですけれども、今、五反田文化センター、平成２２年１０月にオープンしました。五反田の実績ですけれども、残念ながら今のところゼロです。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"新設、改修時にはもちろん設置をしていただきたい、当然と思いますけれども、携帯型、移動型、とても安価で持ち運びも便利だそうです。いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"いわばバリアフリーの一部ということで、区も改修しました平成２２年の五反田文化センターにも取り入れました。荏原文化センターにもそういう目的で取り入れているところです。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"設置、改修時、改築のときはもちろんと言ったんです。誰でもきちんと会議に参加できるということなので、ぜひこの移動用も貸し出しも含めてお考えいただきたいと思うんですが、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"私どもも先ほどの考え方でそういう設置式のものをホールにはつくってまいりました。そんな中で、今後、費用の面も含めまして研究をさせていただきたいと思います。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ考えて実行してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"私のほうからは、成果報告書の１０９ページ、防犯設備整備助成金についてと、１１８ページの戸籍事務費についてお伺いをしたいと思います。どういった刑罰というか、罰則というか、どういったことになるのかということをまずお伺いしたいと思います。","respondent":"井浦戸籍住民課長","answer":"必ず通知を文書で差し上げまして、ご本人に無断で出されたことがないかどうか確かめることができるようなことで対応しております。ご相談申し上げまして、警察等とも協議をしまして、法的な対応等をした件が１件あります。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問","question":"本人通知というお話がありましたが、これは多分、封書かなんかでされているんでしょうか。そういったところで、挙動不審だから、そこら辺で受理をしないということが職員としてどういうことになってしまうのかということをお伺いしたいです。","respondent":"井浦戸籍住民課長","answer":"戸籍事務につきましては、全国統一の事務です。法的な判断が難しいものにつきましては、法務局に協議をいたしまして、法務局とよく相談をした上で慎重に対処するということで対応しています。","id":"exchange-035"},{"speaker":"塚本委員","kind":"確認","question":"現実には実生活がある中でそういったことを個人がやっていくのは大変なので弁護士に依頼すると、聞いた話ですと、やっぱり３０万ぐらいかかると。確認させていただいてから戸籍の受理をするとか、そういったことが可能なのかどうか、その点はいかがか尋ねました。","respondent":"井浦戸籍住民課長","answer":"成人の立会人の立会いをもって確認をするという、これはもう全国での制度なんですが、そのようになってあります。したがいまして、実質的に婚姻関係がない方が法的に出されてしまったときには、やはり法的に対応していただくしかないというふうに考えてあります。","id":"exchange-036"},{"speaker":"塚本委員","kind":"質問・要望","question":"相手方に確認をするとかということができる可能性というんですか、そういうところを検討していただいて、よろしくお願いしたいと思います。品川区において、防犯カメラの設置状況というんですか、こういったものはどういうふうになっているかというのを現状をお伺いしたいと思います。","respondent":"上垣外生活安全担当課長","answer":"今の委員のご質問、現在の犯罪状況に応じた防犯カメラの設置状況というお話でありました。現在、この東京都が始めました補助金の制度に基づいて設置をしている防犯カメラにつきましては、設置の助成をさせていただいているところであります。","id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"なぜかしらここは狙われやすいのか、例えば最初の設置の初期費用については全額を助成するとか、こういった形も必要なのではないか。区内の治安維持というか、この点、いかがお考えになりますか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"まだまだ設置すべき範囲が広いと考えておりますので、まずは町会・自治会のほうの自主的な判断と費用に基づいて設置をしていただくことが第一段階。その設置の全額助成等につきましては、次の段階の検討になるというふうに考えております。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問・要望","question":"地域において、ランニングコストということについても、なかなか負担感というものを持たれているというお話を聞いております。このランニングコストということについても、次の段階という中でお話がありましたけれども、ぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"確認","question":"統計調査費は昨日の質問、どうも理解ができないところがあったので、再度確認をさせてください。人件費部分というのはどうなってくるのか、その点の確認を財政上でお聞きしたつもりだったんですが、もう一度お答えをお願いします。","respondent":"本城企画財政課長","answer":"実際の歳出としてのほうは１７万７,０００円余ということで、６,１００万円余ということになっておりますが、そういう関係ということでご理解いただければと思います。","id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"確認","question":"そこが何か方法がないのかなというつもりで確認をしたところです。もう一回ちょっと。","respondent":"本城企画財政課長","answer":"人件費の相当部分がほかの調査に比べて職員が直接やった部分が多かったものですから、それで職員給与費の中にカウントされる部分が多く、それで委託金との差額がほかの調査に比べて大きくなってしまっている記載になっているという関係です。","id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"委託事業自体がやっぱりどうしても人件費の部分が多いのだと思いますので、それは了解しました。なるべく早く処理していただきたいという希望を含めて、状況はわかりますので、今後の概略だけ教えてほしいと求めました。","respondent":"工藤総務課長","answer":"今後の処理ですけれども、私ども、本日早朝、第２回品川区不発弾対策本部の中で、今後の不発弾処理の計画の方針を決定したところです。今後の処理概要といたしましては、１０月２７日の日曜日の午前中に予定を組むということで決定をしています。","id":"exchange-042"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。１０月２７日というと、その辺、同日ということでよろしいのか尋ねました。","respondent":"鈴木防災課長","answer":"不発弾処理の予定日に地区の訓練が重なっているという件についてのお尋ねですが、区のほうの支援を両方に派遣することで、その当日で実施をしていただくということでご了解いただいたところです。","id":"exchange-043"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それを踏まえてなんですが、交流負担金として１,０３８万円余という金額が出ていますが、これの内訳について一応確認をさせてください。あまり考えられないんですけれども、そういう制限があるというふうに聞いているので、その辺を確認をさせてください。","respondent":"久保田地域活動課長、安藤文化スポーツ振興課長","answer":"ひだまりの里の運営負担金ということで、それを品川区が負担するという協定になってございまして、これが２４０万円になってあります。八潮太鼓とか、大井権現太鼓の派遣というものを行ってありますので… 私のほうからは、社会教育関係登録団体のことについてご説明します。成果報告書１０９ページの中ほどの各種団体支援のところに社会教育関係登録団体の支援ということで入ってあります。","id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それはうまくご説明の上で扱っていただきたいんですが、自主的な会ですから、メンバーを多くしていきたいと。そこら辺の整合性が合わなくなってくるんじゃないかと、ちょっとその点も確認させてもらいたい。","respondent":"寺嶋協働・国際担当課長、久保田地域活動課長","answer":"ですから、今ご質問にありました社会教育登録団体ももちろんこの中に含まれている、さらに広く含まれているということで登録は可能です。参考までに、営利団体の場合でありましても、社会貢献活動を行っている内容の登録もできると… 山北町と今後のあり方について検討しているところでございまして、品川区として問題意識を持っているのが、ひだまりの里の利用にかかる経費。こうした点を交渉しながら、できるだけ経費削減に努めていきたいと考えているところです。","id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、すまいるネットはすまいるネットでもちろん了解しています。ここが同じでいいんですねということの確認、同じかどうかということを確認します。","respondent":"安藤文化スポーツ振興課長","answer":"先ほどのご説明の延長線になると思いますけれども、すまいるネットでも募集をかける、仲間を募集するのは結構です。どういうような活動内容で、どういうような方針だというような中身を話していく中で、そういう判断をしていくです。","id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今の算出基準、人口が大分変わってきている中で、その算定を見直ししないでいいんでしょうかというお話です。１万２,０００人ぐらいいらっしゃるような町会も出てきている中で、その辺のこれからの検討のお考えをお聞かせほしいと求めました。","respondent":"久保田地域活動課長","answer":"区民まつりのほうは、平成２年の人口をもとに、町会数、人口の按分で割ってあります。区民まつりだけということではなくて、町会への支援の施策全般を見直す中で、いろいろと検討していく必要があるという認識を持ってあります。","id":"exchange-047"},{"speaker":"西本委員","kind":"提案","question":"今、大体午前９時ぐらいからですかね。今、朝活なんかで結構盛んにやっているので、そこに利用できるような緩和策ができないだろうかという提案ですとの意見を述べました。","respondent":"久保田地域活動課長、鈴木防災課長","answer":"集会所の朝の利用ですが、集会所は、今、９時から夜の９時半までの中で利用していただいてあります。職員が出勤する等も含めまして、今の段階で朝の早い時間から時間設定を設けてお貸し出しするということは難しい状況にあると考えてい… ２月に各町会・自治会にスタンドパイプを配備させていただきました後、スタンドパイプの操作方法等に習熟をしていただくということを実施しています。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問・要望","question":"というところだってあるわけですから、ぜひそれを研究をしていただきたいということで、そのお考えをお聞きします。小さいハンドブックにするとかというような、そういう気軽に見られるというようなものができないだろうかというふうに思いますが、いかがか尋ねました。","respondent":"久保田地域活動課長、鈴木防災課長、平澤経理課長","answer":"集会所の件ですけれども、先ほども言いましたように、近隣への配慮、またセキュリティの問題等もあります。そういったことを考えますと、今… 署員にも限りがありますので、同日にあまり複数の訓練が重なるような場合には、日程の調整をお願いするようなケースがあります。それと… 庁舎そのものがそういった構造にはなっていないということがまず第１点目、こちらは難しいというふうに考えているところです。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな使い方ができるのではないかというのでは、これに限らず、これからいろいろな使い方を工夫していただきたいと考えています。それから、やはりすぐ活用できるような内容をチョイスするだけで結構いいものができ上がると思いますので、ぜひご検討を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"鈴木（博）委員","kind":"質問","question":"成果報告書の１１６ページの医療救護体制整備費、７０万８,０００円に関連して、防災医療についてお尋ねいたします。これは成果報告書を見てもちょっとどこだかわからなかったのですが、これはどこに掲載されているのか尋ねました。","respondent":"鈴木防災課長","answer":"お尋ねありました初動対応に必要な医療キットの件ですが、これは申しわけありません、その内容ということでお聞きいただければと思います。基本的にはそれと同じような機能を持つものをそろえまして、各救護所に配備をするという予定で進めているものです。","id":"exchange-051"},{"speaker":"鈴木（博）委員","kind":"質問","question":"昨年もお聞きしたんですが、現在、男女共同参画センターの実際の施設の利用状況はいかがなのでしょうか。長らく利用者の低迷が続いていたと思うんですが、それをまずお尋ねいたします。","respondent":"提坂人権啓発課長","answer":"男女共同参画センターの利用状況に関してのお尋ねですけれども、平成２４年度が午前中の利用率が４４.９％、午後が６２.４％、夜間が２５.１％、全体の利用率が４４.１％です。","id":"exchange-052"},{"speaker":"鈴木（博）委員","kind":"質問","question":"昨年、一昨年に比べて、その実績はいかがなんか尋ねました。","respondent":"提坂人権啓発課長","answer":"全体では、平成２３年度の利用率が４０.２％でございました。平成２４年度は４４.１％ということで、４ポイント強増となっております。","id":"exchange-053"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それは改善したと見てよろしいのでしょうか。一応、前、いろいろ催し物をするとか、いろいろな取り組みをされていたみたいですが、何かポイントとかというのはあったのか尋ねました。","respondent":"提坂人権啓発課長","answer":"相談の回数を平成２４年度から、ＤＶ相談については、月３回だったものを毎週やっているようになりました。それから、今年度については、センター改修工事を行いまして、さらに利用しやすいような状況に改善したところです。","id":"exchange-054"},{"speaker":"鈴木（博）委員","kind":"意見","question":"男女共同参画センターというのは非常に大切なその措置だと思いますので、今後も精力的に活動して、男女共同社会の実現に向けて努力していただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"こんの委員","kind":"質問・要望","question":"改訂をする際に、そして発行されていると思いますけれども、改訂に当たって区民の方からのご意見やご要望というのが改訂の中に入っているのかどうか。それから、資機材保守点検ですけれども、こちらの資機材保守点検は、いつされているのか、定期、不定期、どのような状況なのか尋ねました。","respondent":"荒井広報広聴課長、鈴木防災課長","answer":"しながわガイドの改訂に当たって、日々寄せられておりますさまざまなお声、それを反映させるように努めているところです。２点目のケーブルテレビの番組ですが、「しながわＥＹＥ」につきましては… 定期的な保守点検かどうか、いつごろかですが、基本的には２年に一度を目途に実施しております。ただし、訓練等で使っている中で、故障したり、不具合が発見された場合には、随時対応するというような形で保守を行っているものです。","id":"exchange-056"},{"speaker":"こんの委員","kind":"質問・要望","question":"この番組は広報広聴課の方もご覧になっていらっしゃるかどうか、ご要望がございまして、とても工夫する余地があるのではないかというご意見なんです。ですので、そこら辺はいかがか尋ねました。","respondent":"荒井広報広聴課長、鈴木防災課長","answer":"さらに精査をいたしまして、検討をしてまいりたいというふうに思っております。それから、また、そちらを通じて直接お声を寄せていただくということが一つの方法ではないかというふうに考えているところです。 委員ご指摘のように点検をいたしまして、必要なものについては更新をするなど、しっかりと訓練ができる体制を整えていきたいというふうに考えております。","id":"exchange-057"},{"speaker":"こんの委員","kind":"確認","question":"さまざまな箇所で考えられますので、ぜひ精査というよりは、全体的に入れていただくようご検討をお願いしたいと思います。手直しをするという課題にもなるんですが、事前の確認というのはやはり必要かなと思うんですが、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"水槽等については、ほとんど区の所有になりますので、区のほうでしっかりと点検も含めた維持管理をしていきたいというふうに考えております。","id":"exchange-058"},{"speaker":"あべ委員","kind":"質問","question":"それから１１８ページの選挙に関連して、余裕があれば１０９ページの歩行喫煙防止推進経費についてもお伺いしたいと思います。区民スポーツの振興、そしてそれがスポーツ関係予算のどのくらいを占めていらっしゃるか、ざっくりとで構いませんので教えていただけますか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"障害者スポーツについては、総合体育館と戸越体育館のほうでそれぞれ実施しています。そして、予算ですが、両方合わせて５００万円弱の予算を計上しています。","id":"exchange-059"},{"speaker":"あべ委員","kind":"提案","question":"そういった意味でも、やはり開催都市東京として、そこは意図的に頑張っていただきたいところであると考えています。品川区としてただいまの区民スポーツ大会に対しての提案、そして今後、現段階でのお考えを説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"そういうことから、大会については今後、スポーツ協会とも十分検討していきたいと思っています。そんな中で、大会に向けて何ができるのかということを今後検討させていただきたいと思います。","id":"exchange-060"},{"speaker":"あべ委員","kind":"質問","question":"それを受け取って、それに書いてまた送らなければいけないということで、２往復しなければいけなくなる。品川区でもぜひこの制度の周知を図るとともに、宣誓書を入手しやすくするようにしてほしいと求めましたが、お考えをお願いします。","respondent":"諸岡選挙管理委員会事務局長","answer":"ただいまの選挙について、品川区にいらっしゃらない方、こういった請求はだんだん増えてきていることは事実です。口頭での説明を中心にさせていただきましたが、それから、より使いやすい制度になるように工夫してまいりたいと考えています。","id":"exchange-061"},{"speaker":"あべ委員","kind":"質問","question":"ちょっと駆け足ですが、歩行喫煙について１点だけ。ぜひ朝の歩行者が多い時間帯だけでも構いませんので、喫煙ができないようにできないかということをお願いしたいんですが、いかがか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"そこの箇所について、喫煙者のマナーを守って喫煙していただくために、１カ所吸っていいという場所に指定させていただいているところです。この場所については、引き続き、喫煙者のマナーを守っていただくという方向で指導を継続させていただきたいというふうに考えております。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほども質問ありましたけれども、特に木密地域では早急にこの訓練を行うよう働きかけていただきたいと思うんですけれども、いかがでしょうか。技術的には、巨大地震に継手耐震化をすることで耐えられるということでお聞きしたんですけれども、このことの確認をまずお願いしたいと思います。","respondent":"鈴木防災課長","answer":"防災課と消防署、全区的に配備をいたしましたスタンドパイプを有効に活用していただけるような訓練を継続していきたいというふうに考えております。","id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"技術的にはこの継手耐震化で巨大地震に耐えられるというところは確認させていただけますでしょうか。そういうことになると、やっぱり１００％目標をぜひ求めていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"東京都水道局のほうで取り組んでおります水道管路の耐震継手化１０カ年事業についてのお尋ねだと思います。今後も引き続き都とは連携しながら取り組んでいきたいというふうに考えております。","id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"火災によって焼失するのが３２％という想定が出ている品川区だからこそ、これを進めていただきたいし、強力に東京都に求めてほしいと求めました。つくっていただいて、ここにぜひ消火栓と貯水槽のマップもあわせてつくっていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"消火栓、実は今年度予算におきまして、これに東京消防庁からいただきました消防水利のデータを反映できるような改修の作業を行っているところです。","id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"次に、医療機関の耐震化助成や自家発電設備の助成をぜひしていただきたいという質問をさせてほしいと求めました。そしてこれは阪神・淡路大震災の３.６倍で、品川では８,０１６人が負傷するということで想定が出ていますけれども、この区の認識を伺います。","respondent":"鈴木防災課長","answer":"それから、基本的にはそれぞれの医療法人、もしくは建物の設置者のほうの管理のもとで耐震化は行われるのが原則になっております。基本的な耐震の基準は満たしているということもありますので、直接そういうような経費の支援をするというような事業は考えていないところです。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私が伺ったのは、この区の認識を伺いましたので、そのことを改めてお伺いしたいと思います。その後、そこのところで把握をしていたら、実態についてお聞かせほしいと求めました。","respondent":"品川木密整備担当課長、鈴木防災課長","answer":"そういった人が集まるような機関につきましては、耐震診断を義務化していくというような制度改正が今行われつつある状況です。この辺の国とか都の動向を見まして、区のほうも対応を考えていきたいというふうに考えております。それを守ることに対しての区の認識というお尋ねですが、区としましても、それを保護するという視点は重要だというふうに認識しております。","id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"看護師の命、そこで負傷者を助けるという活動ができなくなってくるわけですから、私はそこのところに真剣に区としても向き合っていただきたい。東京都にそういうことを出しているわけですから、区としても独自の思いでもぜひやっていただきたいと思うんですけど、改めてお願いします。","respondent":"品川木密整備担当課長","answer":"先ほど答弁しましたとおり、これにつきましては、国、それから東京都、この機関等と、またなおかつ、２３区全体の動向を見ながら制度のほうを検討していきたいというふうに考えている状況です。","id":"exchange-068"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは医師会のほうからも要望として上げられていることです。耐震化、自家発電設備の助成、ぜひともつくってください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"松澤委員","kind":"意見","question":"防犯カメラ、この平成２４年度は、予算２,２００万円強に対して２,７００万円強使っている。防犯設備整備事業ということで３分の２助成、二つのことに分かれていますけれども、このそれぞれの事業内容についてお知らせほしいと求めました。","respondent":"上垣外生活安全担当課長","answer":"これにつきましては、平成１７年に東京都の助成制度が始まりまして、これに準拠して区でも実施をさせていただいているものであります。商店街が設置をする場合に、都と区で３分の２を助成いたしまして、商店街で３分の１を負担いただくという制度になっております。","id":"exchange-070"},{"speaker":"松澤委員","kind":"質問","question":"今年度の申請件数を聞いたので、それをお聞きしたいと思います。","respondent":"上垣外生活安全担当課長","answer":"平成２５年度につきましては、７団体、申請をいただいております。","id":"exchange-071"},{"speaker":"松澤委員","kind":"質問","question":"順調に伸びているということなんですけれども、いろいろな犯罪のときに防犯カメラで見つかったとかというような話があります。放火が多いものですから、商店街とやれば６分の５だよという話をしても、何かモデル的なもので数字がありましたらお教え願いたいと思います。","respondent":"上垣外生活安全担当課長","answer":"加えまして、設置業者によっては、そのほかに機材のメンテナンス、こういったものがかかる場合があります。ただし、業者によりましては、このランニングコストを設置から５年間は免除するという仕組みをとっているところがあります。","id":"exchange-072"},{"speaker":"松澤委員","kind":"質問","question":"大体１台４,０００円ぐらいですかね。品川区も積極的にこれに協力すべきだというふうに思いますけれども、いかがか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"ようやく２０５町会・自治会中３２の町会・自治会と、１０８商店街中２２の商店街において街頭防犯カメラの設置をしていただいたところであります。こういった中で、やはり設置の助成、ランニングコスト等の助成は次の検討であるというふうに考えております。","id":"exchange-073"},{"speaker":"松澤委員","kind":"質問","question":"このスタンドパイプそのものが平成２５年度の事務事業概要には何も触れていないんですね。スタンドパイプのスもないんですけれども、その辺のことをちょっとお聞きしたいと思います。","respondent":"鈴木防災課長","answer":"申しわけありません、継続する事業ではないということで、事務事業概要の一本立ちした事業としては表記がございません。ただ、今後はしっかりとそういう使用していただける機材があるということも表記をしていきたいというふうに考えております。","id":"exchange-074"},{"speaker":"松澤委員","kind":"質問・要望","question":"その世話をするのは、まさに継続ですから、しっかりとやっていただきたいというふうに思っています。模擬消火栓というんですか、どういうふうにしているのか、お聞きしたいと思います。","respondent":"鈴木防災課長","answer":"スタンドパイプの訓練等に使える模擬消火栓についてのお尋ねですが、品川区のほうで３台ほど注文して作製をして、区のほうで常時保管をしております。貸し出しをして活用していただくということで、現在、活用しています。","id":"exchange-075"},{"speaker":"松澤委員","kind":"質問・要望","question":"幾らしましたかと、一つが２０万円したというんですね、７カ所、１４０万円、どうしてこのお金を捻出したんですか、これは古紙回収でやりました。いつごろまでこれを使うのかについてもお伺いしたいと思います。","respondent":"鈴木防災課長","answer":"新しい年度、平成２５年度の調査が予定されていることはわかっておりましたが、まずはその当時の情報でつくらせていただいたものになります。これにつきましても、それぞれの新しい情報を踏まえた改訂のものを、できるだけ近いうちにまた出したいというふうに予定をしています。","id":"exchange-076"},{"speaker":"山元委員","kind":"質問・要望","question":"私からは、１０４ページの山北町との交流事業、そして時間がありましたら、その手前、１０３ページの職員研修費についてお伺いしたいと思います。実はその下のところに郷土芸能派遣経費と書いてあるんですが、これとまた違うのかどうか、ちょっとその辺を教えてほしいと求めました。","respondent":"久保田地域活動課長","answer":"すみません、改めてご説明いたします。私が先ほど言いました八潮と大井権現太鼓の派遣については、その下の郷土芸能派遣経費ということで９１万円のことを指しているものです。","id":"exchange-077"},{"speaker":"山元委員","kind":"質問・要望","question":"納得いたしました。使用料がわかるのであれば教えていただきたいということと、それから、それもわかれば教えてほしいと求めました。","respondent":"久保田地域活動課長","answer":"テニスコートにつきましても、品川区民の利用が６.１％、山北町民が５５.８％、山北、品川区民以外の場合は３８.１％です。８０％が品川区民、町民、区民以外の利用はないという状況です。","id":"exchange-078"},{"speaker":"山元委員","kind":"質問・要望","question":"結構５０％使っているとかとおっしゃっていたのでちょっとびっくりしたんですけれども、それはやはりきちっとはっきり言っていただきたいなと思いますが、その辺は話し合いはできているのか尋ねました。","respondent":"久保田地域活動課長","answer":"指定管理料相当額になります平成２４年度の支払ったお金は２４０万円なんですけれども、今、協議をしています。まだちょっと今、お示しすることができませんけれども、協議はしています。","id":"exchange-079"},{"speaker":"山元委員","kind":"質問","question":"地割れというんでしょうか、直すというんですか、そういうのも今まで品川区で負担をしていたんでしょうか。それともこれから、例えば来年契約を見直すときに、それも双方でというふうな形になるんか尋ねました。","respondent":"久保田地域活動課長","answer":"この間、修繕等もしてきたところですので、その辺は施設全体の運営の中で必要な修繕等は行ってきたものというふうに考えてあります。","id":"exchange-080"},{"speaker":"山元委員","kind":"質問・要望","question":"５月に地元の高齢者クラブの方たちと小菊交流というんですか、言うべきことはきちっと言っていただいて、継続できればしてほしいと求めました。１年間で１,５００万円をかけて、やはり当たり前のことですが、研修してやっぱり成果は出ているのか尋ねました。","respondent":"堀越人事課長","answer":"研修につきましては、今、委員からご紹介ありました１,６００万円前後の研修費をかけまして研修を実施しています。さまざまな創意工夫を図りながら、区政を振興できているというところで、全体的な効果はあらわれているというふうに考えているところです。","id":"exchange-081"},{"speaker":"山元委員","kind":"質問・要望","question":"やはり対応、窓口の対応がとっても不愉快になるという、そんなクレームがついています。特に窓口に出てくる方に対しての研修というんですか、その辺を重点に置いてやってほしいと求めましたが、いかがか尋ねました。","respondent":"堀越人事課長","answer":"それから、職場単位で窓口の研修も行っております。引き続き、努めてまいります。","id":"exchange-082"},{"speaker":"藤原委員","kind":"質問・要望","question":"ほかの地区のサインを含めて、これがイメージアップ運動経費でいいんでしょうか、見解をお伺いします。１０９ページ、品川区の安全を守るという気持ちで来てくださっていると思うんですが、率直に品川区に対しての担当課長のお気持ちをお伺いします。","respondent":"寺嶋協働・国際担当課長、安藤文化スポーツ振興課長、堀越人事課長、荒井広報広聴課長、工藤総務課長、上垣外生活安全担当課長","answer":"いまだ十分あるというふうに認識しておりますけれども、いわゆるポートランドの都市交流が始まって来年度で３０周年を迎えます。… 私からは、大森貝塚の件についてご説明します。第３点目は、また平成５年の公園の拡張工事の際にも同じことで調査を行ったところ… 例えば４０歳ですとか、５５歳ですとか、それから資質の向上を行っているというものです。","id":"exchange-083"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、この事業をぜひ地域と一緒になってやっていってほしいと求めましたが、それのご答弁をほしいと求めました。区長の発案だと思うんですけれども、日本で行われるわけですから、改めて今後の国際交流の展開をどのように考えているかお尋ねします。","respondent":"上垣外生活安全担当課長、寺嶋協働・国際担当課長","answer":"私たちが平素から取り組んでおりますきれいなまちには犯罪が起こりにくいというものの取り組みの一環であるというふうに考えています。ですので… まず、児童・生徒の語学力だけでなく国際力の向上ということで、海外に対応できる人材の育成ということに力を入れていきたい。","id":"exchange-084"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に、ありがたい苦情もありますけれども、クレーマーによって職員の方が本当につらくなってしまう思いというのは必ずあると思うんです。今日はもう時間がないので話しっ放しで終わりますが、もうそろそろシステム等をつくって、そういう意味で職員を守ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"高橋委員","kind":"質問・要望","question":"幾つかお尋ねしますが、第３次一括法の成立によって義務づけ、枠づけの見直しが行われたと思います。地方青少年問題協議会法が改正されたとお聞きしておりますが、どの点で改正され、どのような目的で改正されたのか尋ねました。","respondent":"福島青少年育成課長","answer":"では、お答えします。それは先ほど言いましたように、各地方自治体に権限を持たせるという意味合いです。","id":"exchange-086"},{"speaker":"高橋委員","kind":"意見","question":"委員の方の欠席の関係ということで、決算についてはわかりました。もう一つ、委員のほうでもかと思われるんですが、そちらについてはとの意見を述べました。","respondent":"福島青少年育成課長","answer":"そちらにつきましても、地方自治体の自主性といいますか、任せられるようになりました。予定ではありますけれども、来年の第１回定例会あたりには、そういうことを検討していきたいというふうには考えております。","id":"exchange-087"},{"speaker":"高橋委員","kind":"質問","question":"今伺おうと思ったんですが、ありがとうございました。どのような特性を委員の中で生かしていくようなお考えが、ちょっと仮定の話ですけれども、もしあれば。","respondent":"福島青少年育成課長","answer":"これからの検討の過程ですけれども、それを継続するような形で、法の趣旨を踏まえながら十分な検討をしていきたいというふうに考えてあります。","id":"exchange-088"},{"speaker":"高橋委員","kind":"質問・要望","question":"このような組織については、過去にもいろいろ言われたことですが、このようになっている組織形態のメリットは、どのようなものでしょうか。それぞれの連携はどのように行われて、それが連携した結果、どのような施策に生かされてきたのかお伺いいたします。","respondent":"福島青少年育成課長","answer":"青少年の健全育成にかかわるものは幅広いところが行っているものですので、そういった中では、各部署との連携が必要であるというふうに考えています。","id":"exchange-089"},{"speaker":"高橋委員","kind":"質問・要望","question":"これは要望であります。青少年対策の一体化の対応が求められている部分から、これはもし所管が外れてしまったら申しわけないんですが、区としてのお考えをお伺いします。","respondent":"福島青少年育成課長","answer":"確かにホームページ上は、なかなかいろいろな分野にわたっておりますので入りにくいというところもあります。そういう点もありますので、来年度、その中で青少年についてはまとめてわかりやすいものにしていきたいというふうに考えております。","id":"exchange-090"},{"speaker":"高橋委員","kind":"質問・要望","question":"リニューアルのときに、ぜひこれらのことがすぐに調べていけるような形をとってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は、成果報告書の１０７ページの区有施設跡地活用等検討経費について伺いたいと思います。長期基本計画とのかかわりも説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"決算には１００万円余の検討経費がありますが、平成２２年から検討を始めてございまして、検討を行ったと。２年ほど検討を進めた中で、昨年の７月に公表させていただいたというものです。","id":"exchange-092"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"会社を教えていただきたいのと、積極的な誘導を図る等々、負担と責任を企業任せにしていることが明記されたプランだなと思いました。そんなに抑制しなくても、民間に頼らなくても自力でやっていける力はあるんじゃないかなと思うんですけれども、どうか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"この公共施設有効活用プランそもそもの考え方ですけれども、３０年代、４０年代の建物が非常に多いということです。そういったところを種々検討した中で、こういったところも有効な手立てであろうということで、方針を示させていただいたというものです。","id":"exchange-093"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"障害者施設なども区民の強い要望がある中で、そういう願いはあるけれども、つくらないということなんでしょうか。そのための土地の確保の必要性、それと、それを自治体が責任持って施設を設置するという必要性を区はどのように考えているのか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"しかしながら、先ほども申しましたように、施設の改修について、今後の改築の場合において、多額な費用がかかってくるというところがあります。","id":"exchange-094"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今も施設を区民の要望に沿って建てていく必要性は認識はあるということなので、やる気の問題なのではないかなと思うんです。でも、区民の切実な願いの施設は抑制、そして民間任せでは、区民の理解は得られないと思うんですけれども、いかがか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"３０年先には、２０年後には、このままやりますと４３０億円かかるのではないかという試算も出ています。いろいろこういった方針をもとに、それぞれの行政需要にいかに対応していくかというのは判断していくものだと思っています。","id":"exchange-095"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ここに要望に応えて進めていくと、そしてこのプランそのものが、やはり開発優先のまちづくりに公有地も巻き込んでいくというものだと思うんです。区民が求める施設を必要数設置していくと、そういう計画こそ立てるべきだと思うんですが、いかがか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"このＴＯＣとの関係でずっと調整をした中で、そういった判断のもとで一時的な貸付をするといったところで、旧第一日野小学校は判断したものです。","id":"exchange-096"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"では最後に、この区民の切実な要望に応えて国有地を購入していくという考えはあるんか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"国有地の関係です。基本は時価での売却というふうに出てありますので、こちらのほうはかなり費用がかかるというところがありますので、慎重な判断が必要と考えています。","id":"exchange-097"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ購入して、お金がかかると言いますけれども、これからそれも区の財産になっていくわけですので、区民の願いに応えてぜひとも購入してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"若林委員","kind":"質問・要望","question":"成果報告書の１０７ページの財産管理費について何点かお伺いいたします。徐々にというんでしょうか、建物、増えているという状況があります。","respondent":"平澤経理課長","answer":"公有財産の昨年度の主な増加につきましては、例えば、建物でまいりますと、荏原平塚の総合区民会館、こういったところが大きなところ。敷地につきましては、品川学園の敷地を引き継いだというところで、増減、これは相見合いのところですが、そういったところが増加です。","id":"exchange-099"},{"speaker":"若林委員","kind":"意見","question":"具体論は今日聞いていませんので、区政としての方針、どこでどのように決定されて、この毎年の増とか減につながっているんですよという、そういう見解を聞きたいと思うんですがとの意見を述べました。","respondent":"柏原行財政改革担当課長","answer":"区有財産です。例えばこれは売却すべきものとか、そういった判断をしながら、こういった増減につながるというものです。","id":"exchange-100"},{"speaker":"若林委員","kind":"質問・要望","question":"２２７ページに維持補修費がありますけれども、これが品川区全体の公有財産を維持補修管理するための費用かというのを確認させていただいて、いや。もう１点は、補修が回らなかったために施設の使用が一時中止されたとか、そういう事例があれば教えてほしいと求めました。","respondent":"本城企画財政課長","answer":"２２７ページの数字は、それらを含めて建設と維持修繕を含めたトータルはまたそれとは、光熱水費等の部分を含めて合わせたものということになります。その中で光熱費が約１６億円です。","id":"exchange-101"},{"speaker":"若林委員","kind":"質問","question":"要するに、約１０億円以上に施設等の維持管理にかかっているのか、それともこの中で全部おさまっているんですよというような端的なお答えでいい。破損等でけが人、また使用中止があったかどうかについてももう１回お聞きします。","respondent":"本城企画財政課長","answer":"その１０億円は補修関係ということになってきますので、それ以外にまた光熱費を含めたものは別にかかってくるという意味です。","id":"exchange-102"},{"speaker":"若林委員","kind":"質問・要望","question":"検討というものをしっかり行って、改築とともに維持修繕についても気を配って私たちに知らせていただきたいということ、時間の関係で。では、ご答弁をお願いいたします。","respondent":"桑村企画部長","answer":"長期基本計画の改訂の中で、どういうようにこれを維持していくか、それについての大きな計画をつくっていく必要があるというふうに思ってあります。よろしくお願い申し上げたいと思います。","id":"exchange-103"},{"speaker":"若林委員","kind":"質問・要望","question":"地上権の活用策があればお聞かせいただきたいのと、この地上権の中に、もう一つ空中権という物件の一種があるというふうに伺いました。この空中権については、品川区では設定されているのか、また、その活用策についても行革の中で検討されているのか、その２点だけ。","respondent":"平澤経理課長","answer":"財産の地上権のことですが、ファミーユ西五反田の敷地の部分です。それともう一つ、空中権と申しましょうか、地役権として大崎東西自由通路の用地につきまして権利を持っているというのが中身です。","id":"exchange-104"},{"speaker":"原委員","kind":"質問・要望","question":"平成２４年度の決算ですので、その前と後ろぐらいで金額的推移、全体的に今後どういった形になるかというお考えがあれば教えてください。２点、お願いします。","respondent":"上垣外生活安全担当課長、安藤文化スポーツ振興課長、寺嶋協働・国際担当課長","answer":"１点目のお尋ねの歩行喫煙防止推進経費につきましては、携行横断幕、こういった広報啓発活動に使う物品が一つ。もう一つが… 私からは、文化振興事業団の助成金につきましてご説明します。中身につきましては、文化振興事業団の事務局の人件費ならびにメイプルセンター… 品川区国際友好協会の補助金の金額につきましてお答えいたします。","id":"exchange-105"},{"speaker":"原委員","kind":"質問・要望","question":"それを片づけて頼みにくいんだけれどもどうかなというようなまち場の声もあるものですから、その辺についてのお考えをお答えほしいと求めました。より堅固な品川の自治体になっていくという思いが私はあるものですから、意外と質問して、その辺をお考えをお聞かせほしいと求めましたので。","respondent":"上垣外生活安全担当課長、安藤文化スポーツ振興課長、寺嶋協働・国際担当課長","answer":"１点目の歩行喫煙防止推進に関しましては、これは品川区歩行喫煙および吸い殻・空き缶等の投げ捨ての防止に関する条例に基づいて実施しております。… 私からは、文化振興事業団の公益化に伴う問題についてご説明します。今後とも健全な事業の運営に携わっていきたいと思っています。国際友好協会につきましても、区の方針に沿った形での事業実施を品川区とのタイアップとしてやっていただくようにしていきたいと思っています。","id":"exchange-106"},{"speaker":"原委員","kind":"意見","question":"文化振興事業団、７１％というのは大変な数字だと思います。思いがありましたら、すみませんけれども、もう一言ずつでもほしいと求めました。","respondent":"安藤文化スポーツ振興課長、寺嶋協働・国際担当課長","answer":"やはり文化につきまして、平成２０年４月にできました品川区文化芸術・スポーツのまちづくり条例の理念に沿って、文化、スポーツを文化振興事業団とともに進めていきたいと思っています。 品川区にお住まいの外国人の方、それから品川区を訪れる外国人の方との交流が一層促進されるよう努めていきたいと思います。","id":"exchange-107"},{"speaker":"井上委員","kind":"質問","question":"１０３ページ、１１３ページの文化センター経費、１０８ページの協働推進経費についてお伺いいたします。そこで、必要としている方たちに積極的にその情報を提供したのかどうかお伺いしたいと思います。","respondent":"荒井広報広聴課長","answer":"ホームページの読み上げサービスについてですが、ホームページ上でお知らせしたり広まっているところです。","id":"exchange-108"},{"speaker":"井上委員","kind":"質問・要望","question":"こういうふうにしましたよというフォローがいろいろな部署で足りないのではないかというふうに思っております。視覚障害や必要としている方々に直接会うわけですから、個人の意識のレベルで解決を求めるのではなくて、いかがか尋ねました。","respondent":"荒井広報広聴課長","answer":"やり始めた事業といいますか、事業についての周知については、さまざまな方法があるかと思います。今委員ご指摘の伝達の手段について、組織的な対応をというご意見につきましては、真摯に受けとめて対応の方策を考えていきたいというふうに思います。","id":"exchange-109"},{"speaker":"井上委員","kind":"質問","question":"一定の検討は進んでいるのでしょうか。進捗状況をお伺いいたします。","respondent":"工藤総務課長","answer":"要綱は、職員が事務処理を進めていく上で、行政運営の指針や行政活動の取り扱いの基準を定める内部的な規範というふうに考えております。このような要綱の性格等を踏まえながら、今、一定の検討を進めているところです。","id":"exchange-110"},{"speaker":"井上委員","kind":"提案","question":"２００９年でしたでしょうか、要綱の閲覧をできるようにして、私たちも直接行かないでそこで調べていろいろな提案ができるようになりました。一定の検討というのは、具体的にはどういうことか尋ねました。","respondent":"工藤総務課長","answer":"私どもも要綱の内容等を精査しながら検討しています。要綱というわけではありませんが、そういった意味では、要綱にかわるものをしっかりと区民の皆様に周知しているというふうに考えているところです。","id":"exchange-111"},{"speaker":"井上委員","kind":"提案","question":"協働の視点というところも含めて、ぜひもう少し進捗状況を早めていただければなというふうに要望して次に行きたいと思います。この駐輪場は、利用者から苦情が多いというふうに感じておりますけれども、苦情の原因を分析されていますか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"五反田文化センターには、駐輪場として４０台、機械式と申しましょうか、置き型の駐輪場があります。その駐輪場が非常に狭いスペースに配置されているというようなご意見はいただいているところです。","id":"exchange-112"},{"speaker":"井上委員","kind":"質問","question":"具体的にお伺いしますけれども、五反田文化センターとスクエア荏原の駐輪場の平置きラックの間隔は、どのぐらい違いますか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"そして、残りの７６台も４０センチ幅のピッチをとってあります。ちなみに、業者いわく、駐輪の間隔は一般的には３５センチから４０センチの間です。","id":"exchange-113"},{"speaker":"井上委員","kind":"質問","question":"国の基準３０センチというのは、もうその基準は捨てていただいたほうがいいかなというふうに思っております。五反田文化センターの駐輪場を今後どうするのかというふうに考えたときに、どのぐらいの費用がかかるというふうに見込まれますか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"大変恐縮ですけれども、今すぐここで改修をしようというような判断はしてございません。そういうことで、経費のことについては、今、把握しているところではございません。","id":"exchange-114"},{"speaker":"井上委員","kind":"提案","question":"もうちょっと使うのでしょうか、新しくできたところですから、そういった説明もある程度していただければなというふうに思っております。当時は区民提案と行政提案で対象事業を選定して予算化する事業だったかと思いますけれども、現況は行政提案のみになっていますけれどもとの意見を述べました。","respondent":"寺嶋協働・国際担当課長","answer":"協働事業提案制度につきましては、平成２０年度に開始しておりまして、当初の３年間は区民提案のものがありました。同じく区から課題を提起する事業も平成２０年度から実施していて、平成２３年度からは区民提案事業のほうは、中止しております。","id":"exchange-115"},{"speaker":"井上委員","kind":"提案","question":"区民活動支援というのは、自分たちがこういう活動をしていますということでわりと提案がしやすいだろうなというふうに思うんですけれども。ぜひ区民の提案事業というのは大変評価していた事業でしたので、工夫してほしいと求めましたけれども、区のお考えをお知らせくださいとの意見を述べました。","respondent":"寺嶋協働・国際担当課長","answer":"これは私どもとしましては、いわゆる活動助成事業のほうがよりご利用しやすい事業であるというふうに地域団体の方は判断したというふうに考えておりまして、こういう形をとったところです。","id":"exchange-116"},{"speaker":"須藤委員","kind":"質問","question":"１０３ページの職員研修費と、１０５ページの被災地支援職員派遣費について、関連して質問させてもらいます。感激されたというようなことを漏れ伺ったんだけれども、そういった情報は議会のほうにどういうふうに、教えてほしいと求めました。","respondent":"堀越人事課長","answer":"被災地への支援の派遣費、予算の内容ですけれども、１０５ページ、被災地支援職員派遣費です。時期を見て、節目節目、また一定程度まとまった段階でご報告をさせていただきたいというふうに考えているところです。","id":"exchange-117"},{"speaker":"須藤委員","kind":"質問・要望","question":"我々はその後のところでどういうことが必要なんだということもその中からかいま見えるのではないかと思って、ぜひ情報をほしいと求めました。そういった研究自体は２３区のそういったものについて、それから、区有施設というのはどこまでを保険をかけられているのか説明を求めました。","respondent":"平澤経理課長","answer":"地震保険についてですが、こちらは共済ということで、２３区共同でやっているというところで、こちらでは地震という項目がございません。そういったところも含めて今後の研究課題ということであります。","id":"exchange-118"},{"speaker":"須藤委員","kind":"質問","question":"１１２ページ、平塚小学校跡地文化スポーツ施設整備、スクエア荏原についてなんだけれども、何回か質問がありました。なぜそうするかというと、そういう関係のメンバーがきちっとわかるような仕組みをつくられたらと思うんですが、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"いろいろなところにひらつかホール、またスクエア荏原、ネーミングのＰＲをしてまいりたいと思っています。スクエア荏原のひらつかホールというような形で紹介させていただいて、また、チラシ等もそのような形でＰＲしていきたいと思っています。","id":"exchange-119"},{"speaker":"須藤委員","kind":"質問・要望","question":"これは要望だけ。天皇皇后両陛下がお見えになるというようなお話も伺っているんだけれども、天皇皇后両陛下がみえるというときには、お顔を出さないでいいのかな。","respondent":"安藤文化スポーツ振興課長","answer":"ハンドボール競技についても、品川区はじめ五つの区市町村でやってあります。これは本当に秘密の秘密ということで、そういうような形で、品川区には今のところ来る予定はございません。","id":"exchange-120"},{"speaker":"須藤委員","kind":"意見","question":"失礼しました。それぞれの国体を、そして２０２０年のオリンピックもまたみんなで協力していい形にしたいと、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-121"},{"speaker":"浅野委員","kind":"質問","question":"１０２ページのパソコン・周辺機器等借料、それと１０６ページのホームページ等々について質問をします。区役所のほうで事務機器ですか、来年の４月９日にこちらのサポートが終了するということで、現状について教えてほしいと求めました。","respondent":"秋山情報システム課長","answer":"そのうちＸＰですけれども、基本的にWindows７が出るまではＸＰで運用を続けてまいりました。計画的に対応しておりまして、Windows７にアップグレードしている最中ということで、今年度中には全て対応が終わるという状況です。","id":"exchange-122"},{"speaker":"浅野委員","kind":"質問","question":"最近特に多いのが、サイバー攻撃とか、不正アクセスですか、そういうものが大きく問題になっている時期もありました。統計とかそういうのはとられているかどうかということと、そういう危ない事例とか、そういうものがあったかどうかについて説明を求めました。","respondent":"秋山情報システム課長","answer":"私どもの対応としましては、それについては注意をするようにということで、これはもうセキュリティ研修などで繰り返し職員に注意をしています。ただ、業者のほうにこれがそういうものなのかということで対応をさせたものはありますけれども。","id":"exchange-123"},{"speaker":"浅野委員","kind":"質問","question":"４,７７６ということで、これが多いか少ないかということについて、どのように考えられているのかということについてお伺いしたいと思います。５,０００というと、そしてこれまで運営してきて苦労された点ですとか、注意されている点についても説明を求めました。","respondent":"荒井広報広聴課長","answer":"ツイッターにつきましては、平常時につきまして、１週間に一度は必ず出すような形で考えているところです。防災といいますか、集中豪雨等がありましたときには、そういった情報も流して皆さん方に関心を持っていただけるように努めているところです。","id":"exchange-124"},{"speaker":"浅野委員","kind":"意見","question":"ツイッター、もう１点ですけれども、ツイッターアラートというサービスが９月２５日からスタートしております。この点についてご意見をお願いしますとの意見を述べました。","respondent":"荒井広報広聴課長","answer":"ツイッターアラートの件ですが、十分な研究をしながら検討を進めてまいりたいと考えています。","id":"exchange-125"},{"speaker":"浅野委員","kind":"質問・要望","question":"もう１点ですけれども、９月から、「新居浜いんふぉ」というアプリを提供しております。ぜひともこういうような連携も今後とも進めてほしいと求めましたが、ご意見、また今後のお考えなどについて説明を求めました。","respondent":"荒井広報広聴課長","answer":"委員ご指摘の、例えば重要なものをどういうふうに掲載するかということも含めまして検討を進めているところです。それから、ケーブルテレビとの連携につきましては、さらに連携を深めて情報発信に努めてまいりたいというふうに考えております。","id":"exchange-126"},{"speaker":"南委員","kind":"確認","question":"経済的な理由により修学が困難な者、いわゆるこの事業は、低所得者を対象にした事業かということで確認したいと思います。それと、申請状況をこの数年間のスパンで、できたら平成２０年あたりから伺いたいと思います。","respondent":"福島青少年育成課長","answer":"こちらの奨学金の貸付ですけれども、事務事業概要にあるように、経済的な理由で高校進学ができない方のために貸し付けるものです。","id":"exchange-127"},{"speaker":"南委員","kind":"質問","question":"生活保護世帯は外すということでありますけれども、所得の比較的低い、そういう方たちを対象にした事業だということでいいのでしょうか。この３桁あったものがずっと減ってきているその状況を、どういうふうに区は見ているのか、そこをちょっと伺いたいと思います。","respondent":"福島青少年育成課長","answer":"ここ数年特に平成２３年、平成２４年から２桁という形で減っています。これはもちろん平成２２年４月から高校の無償化が進められているということで、私どもの条例改正を平成２３年度に行いまして、どちらかといいますと。","id":"exchange-128"},{"speaker":"南委員","kind":"質問・要望","question":"２０代、３０代の若い人であったと、こういうふうなことが公表されているんですね。思い切って給付制度に制度内容を切り替えるべきだというふうに、この点についての認識はどういうふうになっているか教えてほしいと求めました。","respondent":"福島青少年育成課長","answer":"各人の事情を踏まえながら、低い方では月３,０００円ですとか、そういうぐらいで返済していただくという形で対応をしています。公立高校には年１３万円と、その方向で検討しているということを聞いてありますので、品川区としては給付に切り替える予定はないです。","id":"exchange-129"},{"speaker":"南委員","kind":"質問・要望","question":"二十歳になる前から債務者にして、そして負担をかけていくという点については、やっぱり私は考慮していくべきじゃないかというふうに思うんです。目指すべきだというふうに思っているんですけれども、どういうふうに、そのあたりをお願いしたいと思います。","respondent":"福島青少年育成課長","answer":"品川区としましては、あくまでも貸付事業ということで行います。先ほど答弁しましたように、月額３,０００円ですとか、こういった事業を継続していきたいというふうに考えております。","id":"exchange-130"},{"speaker":"南委員","kind":"質問・要望","question":"非常に今の若い人たちに対して冷たい姿勢だというふうに思います。やっぱり給付制度を国にしっかりやれと、早くやれということを求め、品川区も率先して取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"品川区役所では、同様な事件が、火炎瓶が２本投げ入れられたとか、こういう状況が起きた場合に、同じような被害が想定されるのでしょうか。どうなんですか、その辺についてちょっとお聞きしたいと思います。","respondent":"工藤危機管理室長","answer":"その中でもそのような事件がまさに起ころうとするときには、いろいろと対応を予測しながら、しっかりと対応できるような体制を整えているところです。具体的には、研修の実施等もやっているところです。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"今回のように火災が庁内で誤って発生した、それから不審者が押し入ったりした場合、職員は対応できるんですか。ちゃんと対応できるように、道具とか、その他、何かいろいろ用意はしてあるのか尋ねました。","respondent":"平澤経理課長","answer":"こちらにつきましては共済組合ということで、１００％の補償が見込まれていると、これまでは出ていたということもあわせてご報告します。そういうことで、訓練等も実施しているです。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"私が、今、保険のことは聞きましたけれども、そうではなくて、実際、不審者が押し入った場合、何か対応する道具とか何かアイテムはあるんですか。職員はきちんとその方に向かって応戦できるんか尋ねました。","respondent":"工藤危機管理室長","answer":"所管によっていろいろな対応事例が異なると思いますけれども、そのようなトラブルが多い所管には、そのような、例えばさすまたのようなものを常備したり、いろいろといわゆる何かなぐりかかられたときに対応できるように、防護服のようなものを購入して控えているものです。","id":"exchange-134"},{"speaker":"須貝委員","kind":"確認","question":"その辺についても安全上はきちんとなっていると、そういうふうに考えていいのでしょうか。それについても、今、経理課長がお話してくださったように、全額大丈夫だというふうに考えていていいのか尋ねました。","respondent":"平澤経理課長","answer":"それをもってして宝塚市役所の事件が防げたかというと、これはそのときの、そのケースごとによって異なってくるのではないかなというふうに思います。","id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"実際、保険として総額幾らぐらいかけているのでしょうか。ここには２３０何万円と出ていますが、こんな額ではとてもではないけれども追いつかないと思うんですが、実際そんなものなんか尋ねました。","respondent":"平澤経理課長","answer":"私の申し上げましたのが、建物と土地の両方の合計でございまして、建物だけですと、１,４６６億円が財産価格になります。ただ、先ほど申し上げましたとおり、この保険を用いて一番近々の例でいきますと、平成２２年度の発災においては全額補填されているです。","id":"exchange-136"},{"speaker":"須貝委員","kind":"質問","question":"こういうふうに区でも都でも国でも言っているならば、できるだけ区有財産に関してリスク管理、危機管理というのはやるのは当たり前ではないですか。そこら辺についてどのようにお考えなんか尋ねました。","respondent":"平澤経理課長","answer":"１,４６６億円の保険金の責任分担額になっているというところでございまして、これまであった火災につきましては、全額補填されていたです。そういったところも含めまして、保険、また財産の維持管理につきましては、総合的な検討が必要だというふうに考えているところです。","id":"exchange-137"},{"speaker":"須貝委員","kind":"質問","question":"絶対大丈夫なんですか。コンピューターは大丈夫なんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"いながわ委員","kind":"質問","question":"１１７ページ、１１４ページに戻って、歴史館経費についてお伺いします。今、地域から情報がまた上がってきたときに、編さん中の区史にそれを入れるような形ができるのかどうなのかということもあわせてお伺いします。","respondent":"工藤総務課長","answer":"進捗状況としましては、来年の８月刊行を目指しまして、今、急ピッチで編集を進めているところです。今年度内でトピックス等が新たな部分があれば、そういった部分も一定考慮しながら進めていくという形になります。","id":"exchange-139"},{"speaker":"いながわ委員","kind":"質問・要望","question":"その助成がどういう形で、町会にどういう補助金が出ているかということは、足を運んできちんと説明をしなければならないと思っていると。来年度以降だから今年度ですね、実際これは今どういう状況になっている、ちゃんと地域の方に説明をされたのかどうなのか説明を求めました。","respondent":"久保田地域活動課長","answer":"６月から７月にかけて、私を含めて地域活動課で１３地区の自治会、自治会に深くかかわりのあると思われる助成金の一覧表を庁内で集約しまして説明に行ってきたところです。","id":"exchange-140"},{"speaker":"いながわ委員","kind":"質問","question":"やったらどうかというのもあわせて質問したときに、判断指標というんですか、その辺についてはいかがでしょうか。先ほどの答弁で同じ答弁がまた１年たった今でも出てきているので、何も進んでいないのかなという思いがしましたので、今質問しています。","respondent":"久保田地域活動課長","answer":"そうした中で検討していますので、昨年と答えは同様の内容かもしれませんけれども、課として一生懸命取り組んでいるところです。昨年もお話をしましたが、判断指標とか、どういうふうに設けるかというのは難しいというところもあります。","id":"exchange-141"},{"speaker":"いながわ委員","kind":"提案","question":"そこに一つのスタンドパイプで十分なのかどうなのかを１点お伺いします。その一つが鍵のかかった格納庫に入っているということが、初期消火をおくらせるのではないかと思いますが、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"そのようなものがだんだん検討されて、本数が適切であるかというようなところは、しっかりと見極めをしたいというふうに考えている段階です。","id":"exchange-142"},{"speaker":"いながわ委員","kind":"質問・要望","question":"次、１１７ページ、区民消火隊の装備品についてですが、区民消火隊はＣ級ポンプがあります。そのうち更新するべき台数、もし替えなければいけない台数があるのであれば、それをどういう計画で替えていくのかということをお知らせください。","respondent":"鈴木防災課長","answer":"それからＤ級につきましては昭和５９年から行っておりまして、ポンプの耐用年数がおおむね２０年程度ですので、実はもう更新が始まっております。","id":"exchange-143"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひこういうのはどんどん更新をしていただいて、区民消火隊のやる気をぜひ出していただきたいと考えていますので、よろしくお願いしします。一言あればお願いします。","respondent":"鈴木防災課長","answer":"ご指摘いただきましたセルの使いにくさについては認識をしておりますので、今後更新の際に、使いやすい機種の選定であるとかということで、ぜひ活用いただけるように更新をかけていきたいと思います。","id":"exchange-144"},{"speaker":"たけうち委員","kind":"提案","question":"私は、１１５ページの防災対策費、それから１０４ページの庁舎等維持管理費、先に防災のほうからお聞きします。私は一つ提案させていただきたいのは、防災用の高所に全方位型のカメラを設置する、区としてはこういう何か検討されているかどうか説明を求めました。","respondent":"鈴木防災課長","answer":"災害時に活用できる高所カメラのご質問ですが、実は品川区には、庁舎ではなくて、隣のファミーユの建物の屋上ですが、２基の高所カメラを設置しておりまして、万が一の災害時には区内の様子を映し出せるような体制をとっているところです。","id":"exchange-145"},{"speaker":"たけうち委員","kind":"質問","question":"ヒカリエの８階に防災センターができて、それを見せていただいたんですけれども、非常に渋谷区内全域が見渡せる。どこで建物が崩れているとか、そういうところまでわかるような、そしてそれが防災センターのほうでキャッチできるような感じになっているんか尋ねました。","respondent":"鈴木防災課長","answer":"品川区の２台のカメラにつきましても、２系統の無線でつながっておりまして、常に災害対策本部のほうで映像を確認できる体制をとっているところです。","id":"exchange-146"},{"speaker":"たけうち委員","kind":"質問","question":"それはどうなっているのかなと思ったので、今度ぜひしっかり見せていただいて、またさらにＰＲをして有効活用できればいいと考えています。どこで起きているのかなとお聞きする場合があるんですけれども、それで見て、どこで起きているということの情報なんかはキャッチできるんか尋ねました。","respondent":"鈴木防災課長","answer":"火災等につきましては、消防署と通常から連携をとっておりますので、火災の第一報が消防署に入った時点で区のほうにも連絡をいただいております。生徒の安全の確認のためとか、必要がある場合には、区のほうでもカメラを利用しまして状況が確認できるようには設置をしています。","id":"exchange-147"},{"speaker":"たけうち委員","kind":"質問","question":"屋上のところにはヒーリングガーデンですか、やっぱりナスなんかもなっていて、ナスがもう干からびてしまっているんです。つる委員が質問させていただいた区民の方のアンケート、管理が大変なのでしょうかとか、いろいろそういうご意見が非常にありました。","respondent":"平澤経理課長","answer":"委員ご指摘の屋上緑化ということで、平成１４年１０月に行ったところです。そういったところも含めまして、そういった形でやっていきたいなというふうに思っているところです。","id":"exchange-148"},{"speaker":"たけうち委員","kind":"質問・要望","question":"けれども、職員の方も行っているようですし、また、区民の方も行っているんでしょうけれども、やっぱり区民の方が見ると残念だと思うんですね。どうしていくか、それをどうしていくかという、それも含めてどうしていくかというのをお話をほしいと求めました。","respondent":"平澤経理課長","answer":"その中で、その上でどうしていくかということを検討しなければならない時期に来ているというのは間違いない事実です。そういったところをいろいろと考えながら検討してまいりたいというふうに考えているところです。","id":"exchange-149"},{"speaker":"たけうち委員","kind":"意見","question":"わかりました。人ごとではなくてという、そこが大事かなと思いますので、そこも含めてしっかりお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-150"},{"speaker":"本多委員","kind":"質問","question":"平成２３年度は大震災の影響により受け入れを中止、それで平成２４年度は軌道に乗り、ここ５年間では交流事業参加者が一番多かったと思うんですね。自主的に努力をされているというふうに認識しておりますが、その点、区としてどのように受け取っていますか尋ねました。","respondent":"寺嶋協働・国際担当課長","answer":"新しい市長の方針では、例えば今年度に関しては、予定では受け入れをする予定だったものが中止になった。そのことにつきましては、友好協会が何か例えば削減をするとか、そういった形で絞ったとか、そういったものではございません。","id":"exchange-151"},{"speaker":"本多委員","kind":"意見","question":"経緯や歴史や友情がありまして、直接区民の利益に結びつくと思いますので、工夫をされて継続という方向でお願いしたいと思います。一言それだけお答えくださいとの意見を述べました。","respondent":"寺嶋協働・国際担当課長","answer":"委員ご指摘のとおり、国際交流の重要性については大変強く認識しておりますので、今後も時代の流れに沿った形で継続していきたいと考えています。","id":"exchange-152"},{"speaker":"本多委員","kind":"質問・要望","question":"区民芸術祭に行きますが、平成２０年４月１日に、平成２２年３月に品川区文化芸術・スポーツ振興ビジョンが策定されました。この条例より５年間経過して、その節目の５年間という成果についてお知らせいただきたいのと、その辺について説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"それで、回を重ねまして、芸術祭も第１回目は手さぐりでやってまいりました。決算ですけれども、やはりコンサート開催経費等につきましては、コンサートそれぞれのその年度による中身によって充実をしていくです。","id":"exchange-153"},{"speaker":"本多委員","kind":"質問・要望","question":"昨日も屋上のところで要望させていただきましたが、議会棟と四つの屋上がありまして、できれば一つはスポーツの充実をしてほしいと求めました。区の庁舎を通っていくわけですから、その辺について、活用についていかがか尋ねました。","respondent":"平澤経理課長","answer":"構造設備を考えたり、そういったところを十分に検討しないと実現は非常に難しい課題かなです。先ほどのそういったところもあわせまして、今後、研究いたします。","id":"exchange-154"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/571589?Template=document&Id=1374#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":114379,"voices":363}}]);
